export interface PitfallItem {
  label: string;
  detail?: string;
}

// Mistake-callout items per lesson×locale; lessons without the callout are
// absent (their mind map hides the pitfalls branch).
export const PITFALLS_REGISTRY: Partial<
  Record<LessonSlug, Partial<Record<Locale, PitfallItem[]>>>
> = {
  "cartesian-and-uv-space": {
    vi: [{"label":"Quên cộng 0.5 khi map pixel → UV","detail":"Dùng u = x / width thay vì u = (x + 0.5) / width khiến cả lưới UV lệch nửa pixel — không rõ ở ảnh mượt, nhưng lộ ngay ở pattern lặp, lưới caro, hay text nhỏ bị mờ/lệch 1px."},{"label":"Nhầm chiều Y giữa canvas 2D và Descartes/NDC","detail":"Canvas 2D có y tăng xuống; Descartes chuẩn và NDC có y tăng lên. Copy công thức vẽ đồ thị toán vào canvas mà quên đảo dấu y (hoặc quên 1 - 2v khi ra NDC) làm hình lật ngược theo trục dọc."},{"label":"Nhầm gốc UV của ảnh với gốc UV của texture WebGL","detail":"Ảnh bitmap (canvas, <img>, PNG/JPEG) luôn lưu hàng pixel đầu ở trên cùng (v=0 là trên). Texture WebGL/OpenGL cổ điển lại coi v=0 là dưới cùng. Upload thẳng ảnh vào texture mà không set UNPACK_FLIP_Y_WEBGL khiến texture hiện lộn ngược — lỗi kinh điển ngay bài texture đầu tiên ở Track 1."}],
    en: [{"label":"Forgetting to add 0.5 when mapping pixel → UV","detail":"Using u = x / width instead of u = (x + 0.5) / width shifts the entire UV grid by half a pixel — invisible on smooth images, but obvious on repeating patterns, checkerboards, or small text offset by 1px from the original design."},{"label":"Mixing up the Y direction between 2D canvas and Cartesian/NDC","detail":"Canvas 2D has its origin top-left with y increasing downward; standard Cartesian and NDC have y increasing upward. Copying a math-plotting formula straight into canvas code without flipping y (or forgetting the 1 - 2v when converting to NDC) flips the drawing upside down."},{"label":"Confusing an image's UV origin with a WebGL texture's UV origin","detail":"Bitmap images (canvas, <img>, PNG/JPEG) always store their first pixel row at the top (v=0 = top). Classic WebGL/OpenGL textures instead treat v=0 as the bottom. Uploading an image straight into a texture without setting UNPACK_FLIP_Y_WEBGL (or flipping manually) renders the texture upside down — a classic bug that shows up in Track 1's very first texture lesson."}],
  },
  "dot-and-cross-products": {
    vi: [{"label":"Dùng dot của hai vector chưa normalize như thể nó là cosine","detail":"Công thức a · b = cos θ chỉ đúng khi | a| = | b| = 1; quên normalize trước khi so sánh góc hoặc tính lighting cho ra giá trị sai lệch theo đúng tỉ lệ độ dài hai vector, không phải cosine thật."},{"label":"Tưởng cross product tồn tại ở 2D giống hệt 3D","detail":"Cross 2D không cho ra một vector — nó suy biến còn đúng một số vô hướng (chính là thành phần z duy nhất của công thức 3D khi coi a_z = b_z = 0): a_x b_y - a_y b_x, dùng để biết b lệch trái hay phải so với a. Viết code mong đợi một Vec2 trả về từ \"cross 2D\" là hiểu sai định nghĩa."},{"label":"Đổi thứ tự tham số cross mà không nhận ra pháp tuyến đã đảo dấu","detail":"cross(ab, ac) và cross(ac, ab) cho hai vector ngược hướng nhau hoàn toàn — nhầm thứ tự khi dựng pháp tuyến tam giác làm mặt bị tối bất thường (pháp tuyến chỉ vào trong thay vì ra ngoài) hoặc bị backface culling loại bỏ nhầm."}],
    en: [{"label":"Using the dot product of two un-normalized vectors as if it were a cosine","detail":"The identity a · b = cos θ only holds when | a| = | b| = 1; forgetting to normalize before comparing angles or computing lighting produces a value skewed by the vectors' actual lengths, not a real cosine."},{"label":"Assuming the cross product exists in 2D the same way it does in 3D","detail":"A 2D cross product doesn't produce a vector — it degenerates into a single scalar (exactly the lone z component of the 3D formula with a_z = b_z = 0): a_x b_y - a_y b_x, used to tell whether b leans left or right of a. Writing code that expects a Vec2 back from \"2D cross\" is a misunderstanding of the definition."},{"label":"Swapping the cross product's operand order without noticing the normal flipped","detail":"cross(ab, ac) and cross(ac, ab) produce two vectors pointing in exactly opposite directions — getting the order wrong while building a triangle normal makes a face look unexpectedly dark (normal pointing inward instead of outward) or get incorrectly discarded by backface culling."}],
  },
  "euler-angles-and-gimbal-lock": {
    vi: [{"label":"Tưởng rotation.x/y/z là ba con số độc lập","detail":"Đổi object.rotation.order mà giữ nguyên x, y, z vẫn đổi hướng cuối — order quyết định các ma trận R_x,R_y,R_z nhân theo thứ tự nào, không chỉ là nhãn."},{"label":"Lerp góc thẳng qua biên 0°/360°","detail":"Nội suy 350° → 10° bằng lerp thường đi qua gần 340° (đường dài) thay vì 20° (đường ngắn) — phải đưa hiệu góc về (-180°,180°] trước khi lerp."},{"label":"Coi gimbal lock là lỗi phần mềm cần \"sửa\" bằng tăng độ chính xác số học","detail":"Đây là tính chất cấu trúc của MỌI biểu diễn xoay bằng ba phép xoay trục tuần tự — float64 cũng không thoát, vì mất bậc tự do là đại số tại β=90°, không phải sai số làm tròn. Cách thoát duy nhất là đổi biểu diễn, như bài sau làm với quaternion."}],
    en: [{"label":"Assuming rotation.x/y/z are three independent numbers","detail":"Changing object.rotation.order while keeping x, y, z unchanged still changes the final orientation — order decides which sequence R_x,R_y,R_z multiply in, not just a descriptive label."},{"label":"Lerping an angle straight across the 0°/360° boundary","detail":"Naively lerping 350° → 10° tends to sweep through roughly 340° (the long way) instead of 20° (the short way) — wrap the angle difference into (-180°,180°] before lerping."},{"label":"Treating gimbal lock as a software bug to \"fix\" with more precision","detail":"It's a structural property of ANY rotation representation built from three sequential single-axis rotations — float64 doesn't escape it either, because the loss is algebraic (a degree of freedom vanishing at β=90°), not a rounding error. The only real fix is switching representations, exactly what the next lesson does with quaternions."}],
  },
  "homogeneous-coordinates-4x4": {
    vi: [{"label":"Quên đặt w=0 cho vector hướng khi nhân với ma trận có translation","detail":"Nếu vô tình để w=1 cho một vận tốc hay pháp tuyến, nó sẽ bị \"dịch chuyển\" theo translation như một điểm — lỗi im lặng, không crash, chỉ cho ra hướng sai lệch tăng dần mỗi khi object di chuyển xa gốc."},{"label":"Dùng nguyên model matrix để biến đổi pháp tuyến khi có scale không đều","detail":"Pháp tuyến lệch khỏi vuông góc thật với bề mặt, ánh sáng tính sai — lỗi gần như vô hình trên mesh tỉ lệ đều, chỉ lộ rõ khi asset bị kéo dẹt theo một trục."},{"label":"Ghép TRS sai thứ tự","detail":"Đặt rotate hoặc scale sau translate (thay vì T · R · S) làm object xoay/scale quanh gốc toạ độ world thay vì quanh tâm cục bộ của chính nó — biểu hiện rõ nhất là object \"bay quỹ đạo\" quanh world khi đáng lẽ chỉ nên tự xoay tại chỗ."}],
    en: [{"label":"Forgetting to set w=0 on direction vectors when multiplying by a matrix that includes translation","detail":"Leaving w=1 on a velocity or normal by accident makes it get \"translated\" like a point — a silent bug, nothing crashes, just a direction that drifts further wrong the farther the object moves from the origin."},{"label":"Using the plain model matrix to transform normals under non-uniform scale","detail":"The normal drifts away from true perpendicularity to the surface, and lighting comes out wrong — nearly invisible on a uniformly-scaled mesh, only showing up once an asset gets stretched along one axis."},{"label":"Assembling TRS in the wrong order","detail":"Placing rotate or scale after translate (instead of T · R · S) makes the object rotate/scale around the world origin instead of its own local center — the most visible symptom is an object \"orbiting\" the world when it should just be spinning in place."}],
  },
  "interpolation-and-easing": {
    vi: [{"label":"Quên clamp sau remap/invLerp khi input có thể vượt biên","detail":"Thanh máu hay alpha fade nhận giá trị âm hoặc lớn hơn 1 từ ngoại suy không mong muốn — UI vẽ lố khung hoặc alpha ngoài [0, 1] bị GPU lặng lẽ clamp (với framebuffer thường) — thanh vẽ lố khung, bug bị che mất thay vì báo lỗi. Luôn clamp(t, 0, 1) trước khi dùng t làm alpha."},{"label":"Nhầm thứ tự tham số smoothstep trong GLSL","detail":"smoothstep(edge0, edge1, x) — hai tham số đầu là biên, thứ ba là giá trị cần đánh giá; viết nhầm smoothstep(x, edge0, edge1) (thói quen từ clamp) compile được nhưng cho gradient sai hoàn toàn."},{"label":"Dùng value += (target - value) * k mỗi frame mà không nhân theo dt","detail":"Cùng k chạy nhanh chậm khác nhau tuỳ frame rate máy người chơi. Dùng 1 - e^-λ Δ t để tách tốc độ hội tụ mong muốn khỏi frame rate thực tế."}],
    en: [{"label":"Forgetting to clamp after remap/invLerp when the input can go out of range","detail":"A health bar or alpha fade receives a negative or >1 value from unintended extrapolation — the GPU silently clamps out-of-range alpha (on standard framebuffers) — the bar draws past its frame and the bug hides instead of erroring. Always clamp(t, 0, 1) before using t as an alpha."},{"label":"Mixing up GLSL's smoothstep argument order","detail":"smoothstep(edge0, edge1, x) — the first two are bounds, the third is the value; writing smoothstep(x, edge0, edge1) (a habit from clamp) compiles fine but produces a completely wrong gradient."},{"label":"Using value += (target - value) * k every frame without multiplying by dt","detail":"The same k runs at a different effective speed depending on the player's frame rate. Use the 1 - e^-λ Δ t form to separate desired convergence speed from actual frame rate."}],
  },
  "matrix-basics": {
    vi: [{"label":"Đọc hàng thay vì cột","detail":"Nhìn ma trận rồi nghĩ \"hàng trên là biến đổi trục x\" là sai chiều — hàng trên chỉ là thành phần x của cả hai cột. Three.js và WebGL còn lưu ma trận dưới dạng mảng phẳng theo cột (column-major), nên nhầm hàng/cột khi tự tay dựng mat3/mat4 cho ra kết quả biến đổi hoàn toàn khác dự định, dù các con số nhìn \"gần đúng\"."},{"label":"Nhân sai thứ tự khi ghép nhiều transform","detail":"Viết M = A * B rồi mong đợi A chạy trước vì đứng trước trong biểu thức — nhưng M v = A(B v) nghĩa là B chạy trước, A chạy sau. Nhầm thứ tự này (rất phổ biến khi ghép rotate + scale) làm object bị méo theo trục sai mà code không hề báo lỗi gì."},{"label":"Tưởng shear là một dạng xoay nhẹ","detail":"Cả hai đều làm hình \"nghiêng\", nhưng chỉ xoay bảo toàn độ dài mọi cạnh; dùng nhầm ma trận shear ở chỗ cần rotate (hoặc ngược lại) khiến object bị kéo dài âm thầm theo một trục, lỗi chỉ lộ rõ khi nhìn kỹ tỉ lệ cạnh chứ không phải qua console log."}],
    en: [{"label":"Reading rows instead of columns","detail":"Looking at a matrix and assuming \"the top row is the x-axis transform\" reads it backwards — the top row is just the x component of both columns combined. Three.js and WebGL even store matrices as flat column-major arrays, so swapping rows and columns while hand-building a mat3/mat4 produces a completely different transform even though the numbers \"look about right.\""},{"label":"Multiplying in the wrong order when chaining transforms","detail":"Writing M = A * B and expecting A to run first because it's written first — but M v = A(B v) means B runs first, A second. Getting this backwards (extremely common when combining rotate + scale) warps an object along the wrong axis, with no error thrown anywhere."},{"label":"Mistaking shear for a mild rotation","detail":"Both make a shape \"lean,\" but only rotation preserves every edge's length; reaching for a shear matrix where a rotation was needed (or vice versa) silently stretches the object along one axis — a bug that only shows up when checking proportions carefully, never in a console log."}],
  },
  "model-view-projection": {
    vi: [{"label":"Nhân sai thứ tự ma trận","detail":"three.js dùng column-major và nhân vector cột từ bên phải, nên biểu thức đúng luôn là P V M p. Viết nhầm thành MVP hay đổi chỗ bất kỳ hai ma trận nào cho ra một phép biến đổi hoàn toàn khác — thường là object biến mất khỏi màn hình hoặc bị méo không nhận ra được, chứ không phải lệch nhẹ."},{"label":"Quên chia cho w sau khi nhân P","detail":"Clip space vẫn là toạ độ 4D chưa chuẩn hoá; so sánh trực tiếp x, y, z với khoảng [-1, 1] mà chưa chia w luôn cho kết quả sai, vì w đúng bằng -z_view chứ không phải hằng số 1."},{"label":"Dùng thẳng ma trận transform của camera (C) làm view matrix thay vì C^-1","detail":"Camera di chuyển sang phải, code lại thấy cả thế giới cũng trôi sang phải theo đúng hướng thay vì ngược lại — lỗi khó phát hiện bằng mắt vì hình vẫn \"chạy,\" chỉ sai chiều điều khiển."}],
    en: [{"label":"Multiplying the matrices in the wrong order","detail":"three.js is column-major and multiplies column vectors from the right, so the correct expression is always P V M p. Writing MVP instead, or swapping any two matrices, produces a completely different transform — usually an object that vanishes from the screen or warps beyond recognition, not something merely \"slightly off.\""},{"label":"Forgetting to divide by w after multiplying by P","detail":"Clip space is still an unnormalized 4D coordinate; comparing x, y, z directly against [-1, 1] before dividing by w is always wrong, because w equals -z_view, not the constant 1."},{"label":"Using the camera's own transform matrix (C) as the view matrix instead of C^-1","detail":"The camera moves right, and the code sees the whole world drift right too, in the same direction, instead of the opposite one — a bug that's hard to spot by eye because the scene still \"moves,\" just in the wrong direction."}],
  },
  "quaternions": {
    vi: [{"label":"Quên normalize sau nhiều phép nhân hoặc chỉnh tay component","detail":"Sai số dấu phẩy động tích luỹ dần khiến |q| trôi khỏi 1 — object không quay sai hướng rõ rệt, mà âm thầm bị co giãn nhẹ, rất khó nhận ra bằng mắt cho tới khi sai số đủ lớn."},{"label":"Slerp mà không kiểm tra dấu dot product","detail":"Vì q và -q mô tả cùng một hướng nhưng nằm hai phía đối nhau trên S^3, slerp giữa hai quaternion có q_1 · q_2 < 0 đi vòng xa hơn cần thiết — object có thể xoay dư tới gần 360° trong trường hợp xấu nhất (hai keyframe gần nhau nhưng ngược dấu) thay vì đi đường ngắn. Tự viết slerp tay (blend nhiều clip animation, chuyển động tác giữa hai rig) mà quên bước đảo dấu này là lỗi kinh điển."},{"label":"Coi phép nhân quaternion giao hoán như nhân số thực","detail":"q_1 q_2 neq q_2 q_1 nói chung — nhầm thứ tự nhân đổi hẳn ý nghĩa \"xoay theo hệ local trước hay hệ world trước\", khiến object xoay đúng góc nhưng sai hẳn hướng tổng thể khi ghép nhiều phép xoay liên tiếp."}],
    en: [{"label":"Forgetting to normalize after many multiplications or manual component edits","detail":"Floating-point error accumulates gradually and drifts |q| away from 1 — the object doesn't rotate obviously wrong, it quietly picks up a slight scale distortion, hard to notice by eye until the error grows large enough."},{"label":"Slerping without checking the dot product's sign","detail":"Since q and -q describe the same orientation but sit on opposite sides of S^3, slerping between two quaternions with q_1 · q_2 < 0 travels further around the sphere than necessary — the object can spin up to nearly a full extra 360° in the worst case (two nearby keyframes with opposite signs) instead of taking the short way. Hand-rolling slerp yourself (blending clips, retargeting animation) and skipping that sign check is a classic bug."},{"label":"Treating quaternion multiplication as commutative like real-number multiplication","detail":"q_1 q_2 neq q_2 q_1 in general — swapping the multiplication order flips whether a rotation is applied in local space first or world space first, leaving the object rotated by the right angle but facing entirely the wrong way once several rotations are chained together."}],
  },
  "srgb-linear-and-gamma": {
    vi: [{"label":"Trộn hoặc cộng màu trực tiếp trên giá trị sRGB mà không decode trước","detail":"Đúng lỗi vừa tính ở trên — kết quả tối hơn và xỉn màu hơn đáng kể so với trộn đúng trong linear, dù công thức trộn (lerp/mix) nhìn hoàn toàn \"đúng cú pháp\"."},{"label":"Đánh dấu sRGB nhầm cho texture dữ liệu (normal map, roughness map)","detail":"Các texture này không lưu năng lượng ánh sáng — decode qua gamma làm méo toàn bộ giá trị pháp tuyến/độ nhám, gây lỗi shading khó chẩn đoán vì không liên quan trực tiếp tới màu sắc nhìn thấy."},{"label":"Encode hai lần hoặc không encode lần nào","detail":"Quên set outputColorSpace/FRAMEBUFFER_SRGB khiến ảnh ra tối và xỉn (thiếu bước encode cuối); ngược lại, tự tay gọi pow(color, 1.0/2.2) trong shader *rồi* vẫn bật sRGB framebuffer sẽ encode chồng hai lần, làm ảnh cháy sáng giả tạo."}],
    en: [{"label":"Blending or summing colors directly on sRGB values without decoding first","detail":"The exact error computed above — the result is noticeably darker and muddier than a correct linear blend, even though the blend/lerp code itself looks syntactically fine."},{"label":"Marking a data texture (normal map, roughness map) as sRGB by mistake","detail":"These textures don't store light energy — gamma-decoding them corrupts every normal/roughness value, causing shading bugs that are hard to diagnose because they don't look like a color problem at first."},{"label":"Encoding twice, or not at all","detail":"Forgetting to set outputColorSpace/FRAMEBUFFER_SRGB leaves the image dark and muddy (missing the final encode); conversely, manually calling pow(color, 1.0/2.2) in a shader *and* leaving the sRGB framebuffer enabled encodes twice, blowing out highlights that were never supposed to be that bright."}],
  },
  "trigonometry-for-animation": {
    vi: [{"label":"Truyền độ thẳng vào Math.sin/Math.cos mà quên đổi sang radian","detail":"Math.sin(90) không phải 1 — nó hiểu 90 là 90 *radian* (hơn 14 vòng tròn), cho ra 0.893.... Luôn nhân với Math.PI / 180 trước khi gọi hàm lượng giác nếu giá trị gốc là độ."},{"label":"Dùng Math.atan(dy/dx) để ngắm mục tiêu thay vì Math.atan2(dy, dx)","detail":"Khi mục tiêu nằm bên trái (dx < 0), atan trả về góc lệch đúng 180° so với hướng thật — vật thể quay lưng lại mục tiêu thay vì hướng về nó, và lỗi này chỉ lộ ra khi test với mục tiêu ở bên trái, dễ bị bỏ sót nếu chỉ test bên phải."},{"label":"Cộng dồn góc mỗi frame (angle += speed) thay vì tính trực tiếp từ đồng hồ elapsed time","detail":"Cách này làm tốc độ quay phụ thuộc frame rate (trừ khi nhân đúng dt), cộng dồn sai số dấu phẩy động qua thời gian dài, và không tự phục hồi đúng vị trí sau khi tab bị ẩn/tạm dừng. Luôn ưu tiên angle = omega * elapsedSeconds."}],
    en: [{"label":"Feeding degrees straight into Math.sin/Math.cos and forgetting to convert to radians","detail":"Math.sin(90) is not 1 — it reads 90 as 90 *radians* (over 14 full turns), producing 0.893.... Always multiply by Math.PI / 180 before calling a trig function if the source value is in degrees."},{"label":"Using Math.atan(dy/dx) to aim at a target instead of Math.atan2(dy, dx)","detail":"When the target sits to the left (dx < 0), atan returns an angle off by exactly 180° from the real direction — the object turns its back on the target instead of facing it, and the bug only surfaces when testing with a target on the left, easy to miss if testing only covers the right side."},{"label":"Accumulating the angle every frame (angle += speed) instead of computing it directly from elapsed time","detail":"This makes rotation speed frame-rate dependent (unless properly multiplied by dt), accumulates floating-point error over a long run, and never self-corrects its position after the tab is hidden or paused. Prefer angle = omega * elapsedSeconds instead."}],
  },
  "vector-basics": {
    vi: [{"label":"Normalize một vector độ dài 0","detail":"Chia cho | v| = 0 cho ra Infinity hoặc NaN, và NaN lan truyền âm thầm qua mọi phép toán sau đó — object biến mất khỏi màn hình mà không có lỗi nào được ném ra. Luôn kiểm tra length trước khi chia, hoặc trả về vector zero khi độ dài quá nhỏ."},{"label":"Trừ ngược thứ tự khi tính hướng giữa hai điểm","detail":"targetPos - myPos cho hướng *tới* target; myPos - targetPos cho hướng ngược lại. Nhầm hai cái này khiến nhân vật quay lưng, đạn bắn sai chiều — lỗi im lặng, code vẫn chạy, chỉ hướng sai."},{"label":"Cộng một vector hướng vào vị trí như thể cả hai cùng loại","detail":"Pháp tuyến, vận tốc và vị trí đều là vec3, nhưng cộng nhầm (ví dụ dịch chuyển pháp tuyến theo vị trí object) phá vỡ ý nghĩa hình học của phép toán — vấn đề này sẽ quay lại rõ ràng hơn ở bài toạ độ đồng nhất (homogeneous coordinates), nơi thành phần w chính thức phân biệt điểm (w=1) và hướng (w=0)."}],
    en: [{"label":"Normalizing a zero-length vector","detail":"Dividing by | v| = 0 produces Infinity or NaN, and NaN propagates silently through every operation after it — an object simply vanishes from the screen with no error thrown anywhere. Always check length before dividing, or return a zero vector when the length is too small."},{"label":"Subtracting in the wrong order when computing the direction between two points","detail":"targetPos - myPos gives the direction *toward* the target; myPos - targetPos gives the opposite. Mixing these up makes a character face away, or a bullet fire backward — a silent bug, since the code still runs, just aiming the wrong way."},{"label":"Adding a direction vector into a position as if the two were the same kind of thing","detail":"Normals, velocities, and positions are all vec3, but adding the wrong pair (say, translating a normal by an object's position) breaks the operation's geometric meaning — this problem resurfaces much more explicitly in the homogeneous coordinates lesson, where the w component formally separates points (w=1) from directions (w=0)."}],
  },
  "attributes-uniforms-varyings": {
    vi: [{"label":"Quên gl.useProgram(program) trước gl.uniform*. Location…","detail":"Quên gl.useProgram(program) trước gl.uniform*. Location thuộc về chương trình đã sinh ra nó — gọi khi chương trình khác đang active, lệnh bị bỏ với INVALID_OPERATION và uniform giữ giá trị cũ."},{"label":"Coi getUniformLocation luôn trả handle hợp lệ. GLSL compiler…","detail":"Coi getUniformLocation luôn trả handle hợp lệ. GLSL compiler loại bỏ uniform không dùng tới (typo tên, hoặc không ảnh hưởng tới output) — hàm trả null hợp lệ, và gl.uniform1f(null, ...) là no-op im lặng, không throw, không log."},{"label":"Khai vertexAttribPointer sai số component so với kiểu GLSL —…","detail":"Khai vertexAttribPointer sai số component so với kiểu GLSL — shader khai in vec3 aColor nhưng gọi vertexAttribPointer(loc, 2, ...). Component thứ ba không đọc được, GPU tự điền mặc định — màu lệch nhẹ mà không lỗi nào chỉ đúng nguyên nhân."}],
    en: [{"label":"Forgetting gl.useProgram(program) before gl.uniform*. A…","detail":"Forgetting gl.useProgram(program) before gl.uniform*. A location belongs to the program that produced it — called while another program is active, the call is dropped with INVALID_OPERATION and the uniform keeps its old value."},{"label":"Assuming getUniformLocation always returns a valid handle.…","detail":"Assuming getUniformLocation always returns a valid handle. The GLSL compiler strips out any uniform it never uses (a typo, or one that never reaches the output) — the function validly returns null, and gl.uniform1f(null, ...) is a silent no-op: no throw, no log."},{"label":"Declaring vertexAttribPointer with the wrong component count…","detail":"Declaring vertexAttribPointer with the wrong component count for the GLSL type — the shader declares in vec3 aColor but JS calls vertexAttribPointer(loc, 2, ...). The third component never gets read, the GPU quietly fills in a default — colors come out subtly wrong with nothing pointing at the actual cause."}],
  },
  "blending-and-alpha": {
    vi: [{"label":"Quên gl.depthMask(false) khi vẽ vật trong suốt","detail":"Depth ghi từ lớp trong suốt gần hơn chặn nhầm lớp trong suốt xa hơn, tạo lỗ thủng kỳ lạ dù màu trộn đúng công thức."},{"label":"Vẽ vật trong suốt theo thứ tự tuỳ ý","detail":"(không sort theo khoảng cách camera) khi dùng alpha blending — công thức không giao hoán, kết quả màu sai lệch hẳn so với additive, nơi thứ tự vô hại."},{"label":"Xuất màu alpha thẳng vào context premultipliedAlpha: true mặc định","detail":"mà không premultiply thủ công trong shader — viền halo màu lạ quanh vật trong suốt khi trình duyệt composite canvas lên trang."}],
    en: [{"label":"Forgetting gl.depthMask(false) while drawing transparent objects","detail":"Depth written by a nearer transparent layer wrongly blocks a farther transparent layer, punching odd holes even though the color math is correct."},{"label":"Drawing transparent objects in arbitrary order","detail":"(not sorted by camera distance) while using alpha blending — the formula doesn't commute, so the resulting color is flatly wrong, unlike additive blending where order is harmless."},{"label":"Outputting straight alpha into the default premultipliedAlpha: true context","detail":"without premultiplying manually in the shader — a stray colored halo appears around transparent edges once the browser composites the canvas onto the page."}],
  },
  "buffers-vbo-vao": {
    vi: [{"label":"Quên gọi enableVertexAttribArray","detail":"vertexAttribPointer đã gọi đúng nhưng attribute vẫn đọc giá trị hằng số thay vì buffer — hình học biến mất mà không có lỗi nào trong console, vì về mặt kỹ thuật không có gì sai cú pháp cả."},{"label":"Tính sai stride/offset theo byte khi có nhiều attribute xen kẽ","detail":"Quên rằng 3 số thực màu chiếm 12 byte (không phải 3) khi tính offset của attribute tiếp theo — lệch dù chỉ 4 byte cũng đủ khiến GPU đọc nhầm dữ liệu của trường bên cạnh."},{"label":"Tưởng VAO ghi nhớ \"buffer nào đang bind vào ARRAY_BUFFER\"","detail":"VAO không lưu điểm bind toàn cục đó — nó lưu buffer nào đã được bind tại đúng thời điểm mỗi lệnh vertexAttribPointer chạy, riêng cho từng attribute (riêng ELEMENT_ARRAY_BUFFER — buffer chỉ số sẽ gặp ở checkpoint sau — thì VAO có ghi lại). Bind sang buffer khác sau đó không tự cập nhật lại VAO; đây là lý do bạn có thể an toàn bind một buffer khác cho việc khác giữa chừng mà không sợ phá cấu hình VAO đã ghi."}],
    en: [{"label":"Forgetting to call enableVertexAttribArray","detail":"vertexAttribPointer was called correctly, but the attribute still reads a constant value instead of the buffer — geometry vanishes with zero errors in the console, because nothing about it is technically invalid."},{"label":"Miscomputing stride/offset in bytes with multiple interleaved attributes","detail":"Forgetting that 3 color floats take up 12 bytes (not 3) when computing the next attribute's offset — being off by even 4 bytes is enough for the GPU to read the wrong field's data."},{"label":"Assuming a VAO remembers \"which buffer is currently bound to ARRAY_BUFFER.\"","detail":"A VAO doesn't store that global binding point — it stores which buffer was bound at the exact moment each vertexAttribPointer call ran, per attribute (the one exception: ELEMENT_ARRAY_BUFFER — the index buffer coming up in the checkpoint — IS recorded by the VAO). Binding a different buffer afterward doesn't retroactively update the VAO; this is exactly why you can safely bind a different buffer for something else in between without corrupting the VAO's recorded config."}],
  },
  "canvas-context-and-dpr": {
    vi: [{"label":"Chỉ đổi CSS size mà quên đổi drawing buffer","detail":"Set canvas.style.width = \"100%\" nhưng để canvas.width/height nguyên giá trị mặc định 300 × 150 khiến trình duyệt phóng buffer nhỏ để lấp đầy khung lớn — hình bị mờ, và méo tỉ lệ nếu CSS ép cả chiều cao."},{"label":"Bỏ qua devicePixelRatio khi set buffer size","detail":"Set canvas.width = clientWidth, canvas.height = clientHeight (không nhân DPR) trông \"đúng\" trên màn hình thường nhưng vẫn mờ trên Retina, vì buffer thiếu hẳn số device pixel thật màn hình có."},{"label":"Quên gọi lại gl.viewport sau khi buffer đổi size","detail":"Resize canvas.width/height xong nhưng không gọi gl.viewport(0, 0, width, height) khiến GPU tiếp tục vẽ theo viewport cũ — hình bị co vào một góc hoặc kéo dài sai tỉ lệ dù buffer đã đúng kích thước."}],
    en: [{"label":"Changing only the CSS size and forgetting the drawing buffer","detail":"Setting canvas.style.width = \"100%\" while leaving canvas.width/height at their 300 × 150 default makes the browser scale that small buffer up to fill the bigger box — the image comes out blurry, and distorted in aspect ratio if the CSS forces the height as well."},{"label":"Ignoring devicePixelRatio when setting the buffer size","detail":"Setting canvas.width = clientWidth, canvas.height = clientHeight (without multiplying by DPR) looks \"correct\" on a standard display but still comes out blurry on Retina, because the buffer falls short of the screen's actual device pixel count."},{"label":"Forgetting to call gl.viewport again after the buffer changes size","detail":"Resizing canvas.width/height without also calling gl.viewport(0, 0, width, height) leaves the GPU drawing into the old viewport — the image shrinks into a corner or stretches with the wrong aspect ratio even though the buffer itself is now the right size."}],
  },
  "depth-buffer-and-z-fighting": {
    vi: [{"label":"Quên OR gl.DEPTH_BUFFER_BIT vào gl.clear khi vẽ vào FBO","detail":"(hoặc canvas có preserveDrawingBuffer: true). Depth cũ từ frame trước vẫn còn, fragment mới ở cùng vị trí bị so với chính nó và thua ngay cả khi hoàn toàn hợp lệ — vật biến mất không rõ lý do. Canvas mặc định che giấu lỗi này vì trình duyệt tự xoá nó sau mỗi frame."},{"label":"Đặt near cực nhỏ (0.001) \"cho chắc\"","detail":"Dồn gần hết ngân sách precision vào vài milimet đầu tiên, bỏ đói phần còn lại của scene ở khoảng cách bình thường — chính nguyên nhân âm thầm của z-fighting tưởng như ngẫu nhiên."},{"label":"Dùng polygonOffset với dấu sai hoặc quên gl.disable(POLYGON_OFFSET_FILL)","detail":"Offset dương đẩy decal ra xa camera thay vì lại gần (chìm dưới sàn thay vì nổi lên); quên tắt sau khi vẽ khiến offset đó áp nhầm lên các draw call tiếp theo không liên quan."}],
    en: [{"label":"Forgetting to OR gl.DEPTH_BUFFER_BIT into gl.clear when drawing into an FBO","detail":"(or a canvas with preserveDrawingBuffer: true). Last frame's depth survives, a new fragment at the same spot gets compared against itself and loses even though it's perfectly valid — an object vanishes for no apparent reason. A default canvas hides this bug, because the browser clears it after every frame."},{"label":"Setting near absurdly small (0.001) \"just in case.\"","detail":"This dumps nearly the entire precision budget into the first few millimeters, starving the rest of the scene at ordinary distances — the quiet root cause behind z-fighting that looks random."},{"label":"Using polygonOffset with the wrong sign, or forgetting gl.disable(POLYGON_OFFSET_FILL)","detail":"A positive offset pushes a decal away from the camera instead of toward it (sinking below the floor instead of sitting on top); leaving it enabled bleeds that same offset into unrelated draw calls that come after."}],
  },
  "first-triangle-webgl2": {
    vi: [{"label":"Shader compile fail âm thầm. compileShader/linkProgram không…","detail":"Shader compile fail âm thầm. compileShader/linkProgram không ném exception dù GLSL sai hoàn toàn — thiếu cặp kiểm tra COMPILE_STATUS/LINK_STATUS (hoặc bỏ qua log lỗi) khiến chương trình \"chạy\" với shader rỗng/hỏng; useProgram trên một program link-fail sinh lỗi GL nội bộ chứ không phải JS exception, và drawArrays sau đó không vẽ được gì hợp lệ."},{"label":"Viewport 0×0. gl.viewport không tự chạy lại khi canvas…","detail":"Viewport 0×0. gl.viewport không tự chạy lại khi canvas resize — gọi nó trước khi canvas có kích thước thật (ví dụ container chưa layout xong) hoặc quên gọi lại sau resize khiến GPU rasterize vào một vùng 0 pixel: draw call vẫn \"thành công\", chỉ là sinh ra 0 fragment."},{"label":"Attribute location sai. gl.getAttribLocation trả về -1 cho…","detail":"Attribute location sai. gl.getAttribLocation trả về -1 cho một tên không khớp chính xác với shader (typo, hoặc attribute bị compiler loại khỏi chương trình đã link vì không đóng góp vào bất kỳ output nào của shader) — gọi enableVertexAttribArray(-1) không ném exception nhưng ghi lỗi INVALID_VALUE đọc được qua gl.getError(), dữ liệu vị trí không bao giờ tới vertex shader, gl_Position giữ giá trị mặc định cho mọi đỉnh và \"tam giác\" co lại thành một điểm."}],
    en: [{"label":"Silent shader compile failure. compileShader/linkProgram…","detail":"Silent shader compile failure. compileShader/linkProgram never throw an exception no matter how broken the GLSL is — skipping the COMPILE_STATUS/LINK_STATUS check pair (or ignoring the error log) leaves the program \"running\" with an empty or broken shader; calling useProgram on a link-failed program raises an internal GL error rather than a JS exception, and the following drawArrays draws nothing valid."},{"label":"A 0×0 viewport. gl.viewport never re-runs automatically when…","detail":"A 0×0 viewport. gl.viewport never re-runs automatically when the canvas resizes — calling it before the canvas has a real size (say, before its container has finished laying out) or forgetting to call it again after a resize leaves the GPU rasterizing into a 0-pixel region: the draw call still \"succeeds,\" it just produces 0 fragments."},{"label":"The wrong attribute location. gl.getAttribLocation returns…","detail":"The wrong attribute location. gl.getAttribLocation returns -1 for a name that doesn't exactly match the shader (a typo, or an attribute the compiler stripped from the linked program because it contributes to no shader output at all) — calling enableVertexAttribArray(-1) throws no exception but records INVALID_VALUE, readable via gl.getError(), position data never reaches the vertex shader, gl_Position stays at its default for every vertex, and the \"triangle\" collapses to a single point."}],
  },
  "framebuffers-render-to-texture": {
    vi: [{"label":"Bỏ qua checkFramebufferStatus","detail":"Framebuffer thiếu attachment hoặc sai định dạng không throw lỗi khi bạn vẽ vào nó — draw call không vẽ gì, và lỗi chỉ hiện qua gl.getError() hoặc một warning dễ bỏ sót trong console, nên bug thường trông như màn hình đen không rõ nguyên nhân thay vì một exception rõ ràng."},{"label":"Quên đổi viewport khi chuyển pass","detail":"Viewport không tự đồng bộ theo framebuffer đang bind; giữ nguyên viewport của pass trước khi sang pass sau khiến hình bị crop hoặc chỉ phủ một góc canvas, dễ nhầm là lỗi hình học hoặc lỗi shader."},{"label":"Quên bindFramebuffer(gl.FRAMEBUFFER, null) trước khi vẽ ra màn hình","detail":"Nếu FBO vẫn đang bind ở pass \"cuối cùng\", kết quả lại ghi tiếp vào texture offscreen thay vì canvas — màn hình không bao giờ cập nhật, trông như cả pipeline không chạy."}],
    en: [{"label":"Skipping checkFramebufferStatus","detail":"A framebuffer missing an attachment or with a mismatched format doesn't throw when you draw into it — the draw call draws nothing, and the error shows only through gl.getError() or an easily missed console warning, so the bug usually looks like an unexplained blank screen instead of a clear exception."},{"label":"Forgetting to change the viewport when switching passes","detail":"The viewport doesn't auto-sync to the bound framebuffer; keeping the previous pass' viewport while drawing the next leaves the image cropped or confined to a corner of the canvas, easy to mistake for a geometry or shader bug."},{"label":"Forgetting bindFramebuffer(gl.FRAMEBUFFER, null) before drawing to the screen","detail":"If the FBO is still bound during what was meant to be the final pass, the result keeps writing into the offscreen texture instead of the canvas — the screen never updates, as if the whole pipeline silently did nothing."}],
  },
  "rendering-pipeline-a-to-z": {
    vi: [{"label":"Tưởng fragment shader chạy trước vertex shader vì \"fragment\" nghe giống input thô","detail":"Thứ tự luôn cố định: vertex shader chạy trước để xác định hình học nằm ở đâu trong clip space, rasterization mới sinh ra fragment, rồi fragment shader mới chạy — không có đường tắt nào đảo ngược được thứ tự này."},{"label":"Sửa gl_Position để \"canh chỉnh\" màu sắc, hoặc sửa biến màu output của fragment shader để \"canh chỉnh\" vị trí","detail":"Hai trạm có hai trách nhiệm tách biệt hoàn toàn — vertex shader không đọc được, không ghi được màu cuối; fragment shader không thể dịch chuyển hình học đã rasterize xong. Nhầm lẫn này thường dẫn tới sửa sai file suốt hàng chục phút."},{"label":"Quên rằng varying nội suy tuyến tính, kỳ vọng nó tự \"clamp\" hoặc \"step\"","detail":"Một varying có giá trị 0 tại đỉnh A và 10 tại đỉnh B sẽ đi qua mọi giá trị trung gian mượt mà giữa hai đỉnh — muốn có ranh giới cứng (như dải màu rõ nét) phải tự dùng step()/smoothstep() trong fragment shader, nội suy không tự tạo ra điều đó."}],
    en: [{"label":"Assuming the fragment shader runs before the vertex shader because \"fragment\" sounds like raw input","detail":"The order is always fixed: the vertex shader runs first to determine where geometry sits in clip space, rasterization only then generates fragments, and the fragment shader runs last — there's no shortcut that reverses this order."},{"label":"Editing gl_Position to \"fix\" a color problem, or editing the fragment shader's output color to \"fix\" a position problem","detail":"The two stations have completely separate responsibilities — the vertex shader can't read or write the final color, and the fragment shader can't move geometry that's already been rasterized. This mix-up routinely wastes tens of minutes debugging the wrong file."},{"label":"Forgetting that varyings interpolate linearly, and expecting them to \"clamp\" or \"step\" automatically","detail":"A varying that's 0 at vertex A and 10 at vertex B smoothly passes through every intermediate value between the two — a hard edge (a crisp color band, say) requires explicitly calling step()/smoothstep() in the fragment shader; interpolation alone never produces one."}],
  },
  "textures-upload-and-sampling": {
    vi: [{"label":"Quên uniform1i khi dùng texture unit khác 0","detail":"Sampler uniform chỉ giữ một số nguyên chỉ số unit, không giữ texture object; bind texture vào TEXTURE1 mà quên gọi uniform1i(loc, 1) khiến sampler vẫn đọc từ unit 0 — sai texture hoặc texture rỗng, không phải bug ở texture bạn vừa upload."},{"label":"Để TEXTURE_MIN_FILTER ở chế độ mipmap mặc định mà không gọi generateMipmap","detail":"Giá trị mặc định của TEXTURE_MIN_FILTER là NEAREST_MIPMAP_LINEAR — một chế độ đòi hỏi mipmap. Texture mới tạo chỉ có level 0 sẽ \"incomplete\" và render ra màu đen tuyền cho tới khi bạn gọi generateMipmap hoặc đổi MIN_FILTER về NEAREST/LINEAR."},{"label":"Quên UNPACK_FLIP_Y_WEBGL khi upload từ <img>/canvas","detail":"Ảnh bitmap có hàng 0 ở trên, texture GL coi v=0 là dưới — bỏ qua cờ này khiến texture hiện lộn ngược, lỗi kinh điển ngay bài texture đầu tiên."}],
    en: [{"label":"Forgetting uniform1i when using a texture unit other than 0","detail":"A sampler uniform only holds an integer unit index, not the texture object; binding a texture to TEXTURE1 but forgetting uniform1i(loc, 1) leaves the sampler reading from unit 0 — the wrong texture, or nothing at all, not a bug in the texture you just uploaded."},{"label":"Leaving TEXTURE_MIN_FILTER at its default mipmap mode without calling generateMipmap","detail":"TEXTURE_MIN_FILTER defaults to NEAREST_MIPMAP_LINEAR — a mode that requires mipmaps. A freshly created texture with only level 0 uploaded is \"incomplete\" and renders solid black until you call generateMipmap or switch MIN_FILTER to NEAREST/LINEAR."},{"label":"Forgetting UNPACK_FLIP_Y_WEBGL when uploading from <img>/canvas","detail":"Bitmap images store row 0 at the top; GL textures treat v=0 as the bottom — skipping this flag renders the texture upside down, a classic bug in the very first texture lesson."}],
  },
  "vertex-fragment-rasterization": {
    vi: [{"label":"Quên gl_Position hoặc gán sai clip space","detail":"Shader compile và link không báo lỗi gì, nhưng tam giác không hiện — vì gl_Position không được ghi có giá trị *undefined* theo spec (phần lớn driver hành xử như vec4(0,0,0,0)), một điểm suy biến rasterizer không thể tạo fragment từ đó."},{"label":"Đặt tên hoặc kiểu varying lệch giữa hai shader","detail":"out vec3 vColor ở vertex nhưng in vec4 vColor ở fragment (sai kiểu) hay vColour (sai chính tả) có hành vi xác định rõ: fragment in có dùng mà không khớp tên+kiểu là lỗi link chắc chắn; fragment in khai mà không dùng thì bị lặng lẽ loại bỏ — không có \"màu mặc định\" nào cả."},{"label":"Tưởng nội suy varying là tuyến tính đơn giản trong mọi trường hợp","detail":"Với tam giác 2D phẳng đúng như demo bài này, nội suy tuyến tính theo trọng tâm là chính xác; nhưng ngay khi có phép chiếu phối cảnh thật (world space 3D qua ma trận projection), nội suy phải perspective-correct — thiếu bước chia w đó khiến texture hay màu bị méo dọc theo cạnh xa của tam giác, một lỗi kinh điển khi tự viết software rasterizer mà không biết Track 0 (Model → View → Projection) đã cảnh báo trước."}],
    en: [{"label":"Forgetting gl_Position or writing the wrong clip-space value","detail":"The shader compiles and links with zero errors, but the triangle never appears — because an unwritten gl_Position is *undefined* per the spec (most drivers behave as vec4(0,0,0,0)), a degenerate point the rasterizer can't build a fragment from."},{"label":"Mismatching a varying's name or type between the two shaders","detail":"out vec3 vColor in the vertex shader but in vec4 vColor in the fragment shader (wrong type) or vColour (a typo) has fully deterministic behavior: a fragment in that is used without a matching name+type is a guaranteed link error; a declared-but-unused fragment in is silently dropped — there is no \"default color\" case."},{"label":"Assuming varying interpolation is always simple linear interpolation","detail":"For a flat 2D triangle exactly like this lesson's demo, plain barycentric linear interpolation is correct; but the moment a real perspective projection enters (3D world space through a projection matrix), interpolation has to be perspective-correct — skipping that division by w warps textures or colors along a triangle's far edge, a classic bug when hand-writing a software rasterizer without knowing Track 0's Model → View → Projection lesson already warned about it."}],
  },
  "webgl-vs-webgpu-landscape": {
    vi: [{"label":"Copy nguyên code feature-detect của WebGL1 sang WebGL2","detail":"Gọi gl.getExtension(\"ANGLE_instanced_arrays\") trên context WebGL2 trả về null — nên nhánh if (ext) lặng lẽ không bao giờ vẽ, tính năng biến mất chứ không chỉ thừa; instancing đã là hàm gốc trên context."},{"label":"Coi navigator.gpu tồn tại nghĩa là WebGPU chắc chắn dùng được","detail":"Property này chỉ báo trình duyệt *biết* API, không đảm bảo requestAdapter() trả về adapter — GPU process bị tắt, chạy trong CI headless, hay driver bị blocklist đều khiến requestAdapter() resolve null hoặc reject; code phải xử lý nhánh async đó, không giả định đồng bộ."},{"label":"Nghĩ WebGPU chỉ là WebGL đổi tên hàm","detail":"GPURenderPipeline bất biến sau khi tạo — đổi blend mode giữa chừng nghĩa là dùng một pipeline khác đã precompile sẵn, không phải set lại một cờ như gl.blendFunc giữa hai draw call."}],
    en: [{"label":"Copying WebGL1 feature-detection code straight into WebGL2","detail":"Calling gl.getExtension(\"ANGLE_instanced_arrays\") on a WebGL2 context returns null — so the if (ext) branch silently never draws and the feature disappears rather than merely being redundant; instancing is already a native method on the context."},{"label":"Treating navigator.gpu existing as proof WebGPU will actually work","detail":"That property only reports that the browser *knows about* the API — it doesn't guarantee requestAdapter() returns an adapter. A disabled GPU process, a headless CI environment, or a blocklisted driver can all make requestAdapter() resolve null or reject; code has to handle that async path, not assume it's synchronous."},{"label":"Thinking WebGPU is just WebGL with renamed functions","detail":"A GPURenderPipeline is immutable once created — changing blend mode mid-stream means switching to a different, already-precompiled pipeline, not flipping a flag like gl.blendFunc between two draw calls."}],
  },
  "what-webgl-is-and-isnt": {
    vi: [{"label":"Tưởng WebGL là một \"engine 3D\" đầy đủ","detail":"Gọi context bằng getContext(\"webgl2\") xong tìm mãi hàm scene.add() hay light.intensity không thấy đâu — vì chúng không tồn tại ở tầng này. WebGL chỉ có buffer, shader, texture, draw call; scene graph và ánh sáng là code JavaScript người khác (hoặc chính bạn) viết thêm lên trên."},{"label":"Không kiểm tra getContext(\"webgl2\") trả về null","detail":"Một tỉ lệ nhỏ thiết bị cũ hoặc trình duyệt tắt WebGL2 vẫn tồn tại (ước lượng vài phần trăm, theo số liệu caniuse); code gọi thẳng phương thức GL trên biến null throw lỗi runtime mơ hồ thay vì fallback rõ ràng hoặc báo cho người dùng."},{"label":"Quên precision qualifier trong fragment shader","detail":"WebGL1 không có precision mặc định cho fragment shader (bắt buộc khai báo precision mediump float;), thiếu dòng đó là lỗi compile bắt buộc, xảy ra như nhau trên mọi máy — trình duyệt nào cũng validate GLSL ES qua cùng một bộ dịch. Thứ thật sự khác nhau giữa các máy là độ rộng của mediump: 16-bit trên nhiều GPU di động, 32-bit trên desktop — shader chạy đẹp trên máy bàn có thể vỡ sạn trên điện thoại."}],
    en: [{"label":"Assuming WebGL is a full \"3D engine.\"","detail":"Call getContext(\"webgl2\"), then go looking for scene.add() or light.intensity and find nothing — because they don't exist at this layer. WebGL only has buffers, shaders, textures, and draw calls; scene graphs and lighting are JavaScript someone (possibly you) writes on top."},{"label":"Never checking whether getContext(\"webgl2\") returned null","detail":"A small but real slice of older devices or WebGL2-disabled browsers still exists out there (an estimate of a few percent, per caniuse data); code that calls GL methods straight on that null value throws a vague runtime error instead of failing with a clear fallback message."},{"label":"Forgetting the precision qualifier in a fragment shader","detail":"WebGL1 has no default precision for fragment shaders (precision mediump float; is mandatory), missing that line is a mandatory compile error that behaves identically on every machine — every browser validates GLSL ES through the same translator. What genuinely differs between machines is the width of mediump: 16-bit on many mobile GPUs, 32-bit on desktop — a shader that looks fine on a desktop can fall apart on a phone."}],
  },
  "branching-cost-on-gpu": {
    vi: [{"label":"Coi mọi if phân kỳ đều \"gấp đôi chi phí\" một cách máy móc","detail":"Chi phí chỉ đáng kể khi cả hai điều kiện cùng đúng: dữ liệu thật sự phân kỳ giữa các lane trong warp, VÀ nội dung nhánh đủ nặng. Một if phân kỳ bọc quanh phép gán một hằng số gần như không đo được — lo lắng thái quá cho trường hợp này chỉ tổ giảm khả năng đọc code."},{"label":"Nhầm \"phân kỳ\" với \"tần suất mỗi nhánh được chọn\"","detail":"Một if mà 90% pixel đi nhánh A, 10% đi nhánh B vẫn phân kỳ tệ như 50/50 — miễn là hai nhóm đó xen kẽ nhau bên trong CÙNG một warp. Ngược lại, một điều kiện chia màn hình thành nửa trái/nửa phải rõ ràng gần như không tốn gì thêm cho phần lớn các warp, vì đa số warp nằm gọn trong một nửa (chỉ các warp ngay biên mới phân kỳ)."},{"label":"Viết branchless cho một if vốn đã uniform","detail":"Rẽ nhánh trên biến uniform không hề tốn kém — bọc nó trong mix/step không giúp gì về hiệu năng, chỉ làm code khó đọc hơn không cần thiết. Branchless là công cụ cho trường hợp phân kỳ theo dữ liệu per-pixel, không phải quy tắc áp dụng mù quáng cho mọi if."}],
    en: [{"label":"Mechanically treating every divergent if as \"double the cost.\"","detail":"The cost only becomes significant when both conditions hold: the data actually diverges across lanes in a warp, AND the branch content is heavy enough. A divergent if wrapping a single constant assignment is basically unmeasurable — over-worrying about this case only hurts readability for nothing."},{"label":"Confusing \"divergence\" with \"how often each branch is taken.\"","detail":"An if where 90% of pixels take branch A and 10% take branch B diverges just as badly as a 50/50 split — as long as those two groups are interleaved within the SAME warp. Conversely, a condition that cleanly splits the screen into a left half and a right half costs almost nothing extra for most warps, since most warps sit entirely within one half (only warps straddling the boundary actually diverge)."},{"label":"Writing a branchless version of an if that was already uniform","detail":"Branching on a uniform variable costs nothing extra — wrapping it in mix/step buys zero performance and only makes the code harder to read. Branchless is a tool for per-pixel data-dependent divergence, not a rule to apply blindly to every if."}],
  },
  "glsl-builtin-functions": {
    vi: [{"label":"Đảo thứ tự tham số của step","detail":"step(edge, x) — edge đứng TRƯỚC, x đứng SAU; viết nhầm thành step(x, edge) đảo ngược toàn bộ mặt nạ (vùng bật/tắt hoán đổi cho nhau) mà không có lỗi biên dịch nào báo, vì cả hai cách gọi đều hợp lệ về kiểu dữ liệu."},{"label":"Quên smoothstep yêu cầu edge0 < edge1","detail":"Nếu edge0 >= edge1, kết quả không đơn giản \"đảo ngược\" như nhiều người kỳ vọng — spec để hành vi này undefined, cho ra artifact khác nhau tuỳ driver. Muốn đảo chiều một smoothstep, đảo ở output (1.0 - smoothstep(...)), đừng đảo hai edge."},{"label":"Mang trực giác % của JavaScript/C sang mod() của GLSL","detail":"-0.3 % 1 trong JavaScript cho -0.3 (dấu theo số bị chia, phép chia cắt cụt về 0); mod(-0.3, 1.0) trong GLSL luôn cho 0.7 (dấu theo số chia, định nghĩa bằng floor, giống hệt fract) — code port trực giác từ JS/C sang GLSL mà giữ nguyên kỳ vọng dấu âm sẽ lệch hẳn ngay khi toạ độ UV âm, ví dụ sau khi dịch tâm hệ toạ độ về gốc."}],
    en: [{"label":"Swapping step's argument order","detail":"step(edge, x) — edge comes FIRST, x comes SECOND; writing step(x, edge) by mistake flips the entire mask (the on/off regions swap) with no compile error at all, since both call orders are type-valid."},{"label":"Forgetting smoothstep requires edge0 < edge1","detail":"If edge0 >= edge1, the result doesn't simply \"invert\" the way many expect — the spec leaves this case undefined, producing artifacts that vary by driver. To reverse a smoothstep, flip the output (1.0 - smoothstep(...)), never the two edges."},{"label":"Carrying JavaScript/C's % intuition into GLSL's mod()","detail":"-0.3 % 1 in JavaScript gives -0.3 (sign follows the dividend, truncating division toward zero); mod(-0.3, 1.0) in GLSL always gives 0.7 (sign follows the divisor, defined via floor, exactly like fract) — porting logic from JS/C to GLSL while keeping the negative-sign expectation breaks the moment a UV coordinate goes negative, for instance right after re-centering the coordinate system on the origin."}],
  },
  "glsl-syntax-types-swizzling": {
    vi: [{"label":"Quên dấu chấm thập phân trên literal cần là float","detail":"float x = 1; không biên dịch được vì 1 là int, GLSL không tự ép kiểu ở phép gán — sửa bằng 1.0. Ngược lại int n = 2.0; cũng lỗi vì 2.0 là float."},{"label":"Trộn hai bộ tên swizzle khác nhau trong cùng một biểu thức","detail":"color.rg hợp lệ, color.xy hợp lệ, nhưng color.rx thì không — r thuộc bộ rgba, x thuộc bộ xyzw, không được trộn dù chúng trỏ tới cùng slot bộ nhớ."},{"label":"Lặp tên thành phần ở vế ghi (l-value) của swizzle","detail":"color.xy = base.xy không sao, nhưng color.xx = vec2(1.0, 2.0) là lỗi biên dịch — chiều đọc cho lặp thoải mái, chiều ghi thì không, vì lặp ở vế trái tạo ra một slot có hai giá trị nguồn mâu thuẫn nhau."}],
    en: [{"label":"Forgetting the decimal point on a literal that needs to be float","detail":"float x = 1; fails to compile because 1 is an int and GLSL never auto-casts on assignment — fix it with 1.0. The reverse also fails: int n = 2.0; errors because 2.0 is a float."},{"label":"Mixing two different swizzle name sets in one expression","detail":"color.rg is valid, color.xy is valid, but color.rx isn't — r belongs to the rgba set, x to the xyzw set, and they can't mix even though they point at the same memory slots."},{"label":"Repeating a component name on the write side of a swizzle","detail":"color.xy = base.xy is fine, but color.xx = vec2(1.0, 2.0) is a compile error — reads tolerate repeats freely, writes don't, since a repeated name on the left creates a slot with two conflicting source values."}],
  },
  "gradients-patterns-tiling": {
    vi: [{"label":"Tính caro trên toạ độ liên tục thay vì trên id đã floor","detail":"Viết mod(uv.x * N + uv.y * N, 2.0) thay vì mod(floor(uv.x*N) + floor(uv.y*N), 2.0) cho ra dải màu chuyển tiếp mượt dọc theo hai trục thay vì các ô caro sắc cạnh — vì mod trên số thực liên tục không hề tạo bước nhảy đúng tại biên ô, chỉ floor mới rời rạc hoá được vị trí thành chỉ số ô nguyên."},{"label":"Xoay trước khi căn giữa","detail":"Viết rotate2d(angle) * fract(grid) (thiếu - 0.5) khiến phép xoay quay quanh góc (0,0) của ô thay vì tâm — motif văng lệch hẳn sang một phía, thậm chí chồm sang ô bên cạnh khi góc xoay đủ lớn."},{"label":"Áp dụng offset lệch hàng sau khi đã nhân N","detail":"Cộng độ lệch vào biến grid (đã nhân N) thay vì vào uv gốc (trước khi nhân) làm độ dịch sai hẳn đơn vị: giữ nguyên hằng 0.5/N khi cộng ở không gian grid co độ lệch xuống còn (0.5/N) của một ô — gần như vô hình, và càng tệ khi N tăng. Ở không gian grid, độ dịch nửa ô đúng là 0.5 chẵn."}],
    en: [{"label":"Computing checker on a continuous coordinate instead of a floored id","detail":"Writing mod(uv.x * N + uv.y * N, 2.0) instead of mod(floor(uv.x*N) + floor(uv.y*N), 2.0) produces a smooth color ramp along both axes instead of crisp checker cells — mod on a continuous real number never creates a jump exactly at the cell boundary; only floor discretizes a position into an integer cell index."},{"label":"Rotating before centering","detail":"Writing rotate2d(angle) * fract(grid) (missing the - 0.5) makes the rotation pivot around the cell's (0,0) corner instead of its center — the motif swings noticeably off to one side, even spilling into the neighboring cell once the angle is large enough."},{"label":"Applying the row offset after multiplying by N","detail":"Adding the shift to the grid variable (already multiplied by N) instead of to the raw uv (before multiplying) gets the units wrong: keeping the 0.5/N constant while adding in grid space shrinks the offset to (0.5/N) of a cell — nearly invisible, and worse as N grows. In grid space the correct half-cell shift is a plain 0.5, regardless of the right coordinate space."}],
  },
  "matrix-transforms-in-shaders": {
    vi: [{"label":"Gõ ma trận theo thứ tự hàng vào constructor cột","detail":"mat2(a,b,c,d) điền cột 0 =(a,b), cột 1 =(c,d) — gõ nhầm bốn số của R(θ) theo thứ tự đọc trên giấy cho ra R(-θ), xoay đúng độ lớn nhưng sai chiều, rất khó phát hiện chỉ bằng cách nhìn kết quả."},{"label":"Quên dịch chuyển pivot trước khi xoay","detail":"M * uv xoay quanh gốc (0,0) (góc dưới-trái của UV), không phải tâm pattern — thiếu bước uv - pivot trước và + pivot sau khiến hình văng quay quanh một góc màn hình thay vì tự xoay tại chỗ."},{"label":"Nhầm chiều xoay của toạ độ với chiều xoay của pattern nhìn thấy","detail":"Xoay UV +θ độ khiến pattern hiển thị lại xoay -θ độ — quên trực giác nghịch đảo này khiến animation xoay \"sai chiều\" so với thiết kế, dù công thức toán không hề sai."}],
    en: [{"label":"Typing a matrix's row order into a column-major constructor","detail":"mat2(a,b,c,d) fills column 0 =(a,b), column 1 =(c,d) — typing R(θ)'s four numbers in the order you'd read them on paper produces R(-θ), rotating by the right amount in the wrong direction, and it's nearly impossible to spot just from the output."},{"label":"Forgetting to translate to the pivot before rotating","detail":"M * uv rotates around the origin (0,0) (UV's bottom-left corner), not the pattern's center — skipping uv - pivot before and + pivot after makes the shape swing around a screen corner instead of spinning in place."},{"label":"Confusing the coordinate's rotation direction with the visible pattern's rotation direction","detail":"Rotating UV by +θ makes the rendered pattern appear to rotate by -θ — forgetting this inverse relationship makes an animation spin \"the wrong way\" compared to the design, even though the math itself is correct."}],
  },
  "precision-qualifiers": {
    vi: [{"label":"Quên khai báo precision ... float; trong fragment shader","detail":"Trong WebGL đây là lỗi biên dịch cứng như nhau trên mọi máy (\"No precision specified for (float)\"). Chuyện \"chạy desktop, vỡ mobile\" có thật nhưng nguồn gốc khác: cùng mediump, desktop cấp 32-bit còn nhiều GPU mobile cấp 16-bit — shader đúng cú pháp vẫn vỡ sạn trên điện thoại."},{"label":"Dùng mediump cho world-space position hoặc pha thời gian tích luỹ dài","detail":"uTime nhân với một tần số lớn rồi lưu bằng mediump gây jitter tăng dần theo thời gian chạy ứng dụng, không phải lỗi xuất hiện ngay lập tức nên dễ lọt qua một lượt test nhanh vài giây."},{"label":"Coi lowp là lựa chọn \"an toàn, tiết kiệm\" cho mọi giá trị 0..1","detail":"Quên rằng một phép tính trung gian (ví dụ cộng dồn nhiều lớp bloom trước khi tone-map) có thể vượt dải [-2, 2] dù giá trị hiển thị cuối cùng vẫn nằm trong 0..1 — lowp clip sai ngay giữa chừng phép tính, trước khi kịp ra tới bước chuẩn hoá cuối."}],
    en: [{"label":"Forgetting to declare precision ... float; in a fragment shader","detail":"In WebGL this is the same hard compile error on every machine (\"No precision specified for (float)\"). The real \"works on desktop, breaks on mobile\" story has a different root: at the same mediump, desktop grants 32-bit while many mobile GPUs grant 16-bit — a syntactically valid shader still falls apart visually on the phone."},{"label":"Using mediump for world-space position or a long-accumulating time phase","detail":"uTime multiplied by a large frequency and stored in mediump causes jitter that grows the longer the app has been running, not an immediate failure, so it easily slips past a quick few-second test."},{"label":"Treating lowp as a \"safe, cheap\" default for anything in 0..1","detail":"An intermediate calculation (like summing several bloom layers before tone-mapping) can exceed the [-2, 2] range even though the final displayed value stays within 0..1 — lowp clips incorrectly mid-calculation, before the value ever reaches the final normalization step."}],
  },
  "shader-debugging-by-color": {
    vi: [{"label":"Xuất giá trị có dấu thẳng ra màu mà không remap","detail":"Nửa âm bị GPU clamp về đen, khiến bạn kết luận nhầm \"giá trị này luôn bằng 0\" trong khi thực ra nó chỉ đang bị cắt mất một nửa thông tin — luôn * 0.5 + 0.5 trước khi nghi ngờ giá trị sai."},{"label":"Bỏ qua khả năng vector chưa normalize khi thấy màu 'bệt', ít tương phản","detail":"Một vector đơn vị remap ra màu trải rộng rõ rệt; màu quẩn quanh xám giữa gần như luôn là dấu hiệu độ lớn nhỏ hơn 1 rất nhiều — như trong ca \"vòng tròn đen\" ở trên, chứ không phải do ánh sáng yếu."},{"label":"Đổi nhiều chỗ cùng lúc rồi mừng vội khi hình \"trông đúng hơn\"","detail":"Không giữ baseline và không đổi từng thứ một khiến bạn không biết thay đổi nào thực sự sửa lỗi — bug tương tự quay lại ở chỗ khác vẫn phải dò từ đầu."}],
    en: [{"label":"Outputting a signed value straight to color without remapping","detail":"The negative half clamps to black on the GPU, leading to the wrong conclusion \"this value is always zero\" when really only half its information got cut off — always * 0.5 + 0.5 before suspecting the value itself is wrong."},{"label":"Missing an unnormalized vector when the color looks flat and low-contrast","detail":"A unit vector remaps into clearly spread-out colors; output clustered around mid-gray is almost always a sign the magnitude is much smaller than 1 — as in the \"black ring\" case above, not weak lighting."},{"label":"Changing several spots at once and celebrating too early when the image \"looks more correct.\"","detail":"Skipping a baseline and changing multiple things at once means you don't actually know which change fixed it — a similar bug resurfacing elsewhere sends you back to square one."}],
  },
  "shaping-functions-and-2d-sdf": {
    vi: [{"label":"Dùng ngưỡng nhị phân (d < 0.0 ? a : b) thay vì smoothstep","detail":"Ngưỡng cứng không có dải chuyển tiếp — mỗi pixel commit hẳn về một màu, không có khái niệm \"phủ một phần\" — nên biên hiện răng cưa rõ rệt, nhất là ở các góc nghiêng gần chéo 45°."},{"label":"Hardcode edge0/edge1 bằng hằng số cố định (như ±0.02 trong demo) rồi mang sang cảnh khác","detail":"Hằng số đó chỉ đúng ở đúng một độ phóng/độ phân giải nó được tinh chỉnh — zoom hoặc đổi kích thước canvas làm viền hoặc nhoè quá mức hoặc mỏng tới mức răng cưa quay lại; sản phẩm thật cần fwidth(d) để bề rộng dải tự scale theo pixel thực tế."},{"label":"Tính viền bằng abs(d) nhưng quên ngưỡng nó lại bằng smoothstep thứ hai","detail":"Chỉ gấp trục số (abs(d)) không tự vẽ ra đường viền nào — nó vẫn là một dải giá trị liên tục; quên bước threshold thứ hai (1.0 - smoothstep(0.0, w, abs(d))) thường khiến toàn bộ hình bị tô đầy màu viền, hoặc ngược lại không có viền nào hiện ra vì so sánh sai chiều."}],
    en: [{"label":"Using a binary threshold (d < 0.0 ? a : b) instead of smoothstep","detail":"A hard threshold has no transition band — each pixel commits fully to one color, with no concept of partial coverage — so the boundary shows up visibly jagged, most obviously along near-45°-diagonal edges."},{"label":"Hardcoding edge0/edge1 as fixed constants (like the demo's ±0.02) and carrying them into a different scene","detail":"That constant is only correct at the exact zoom/resolution it was tuned for — zooming or resizing the canvas either blurs the edge too much or thins it back into aliasing; production code needs fwidth(d) so the band width scales with actual on-screen pixels."},{"label":"Computing an outline with abs(d) but forgetting to threshold it with a second smoothstep","detail":"Folding the number line (abs(d)) alone doesn't draw an outline by itself — it's still a continuous range of values; skipping the second threshold step (1.0 - smoothstep(0.0, w, abs(d))) usually floods the whole shape with the outline color, or produces no visible outline at all from a flipped comparison."}],
  },
  "animation-mixer-and-clips": {
    vi: [{"label":"Quên gọi mixer.update(delta) trong render loop","detail":"action.play() chỉ đổi cờ trạng thái nội bộ, không ghi giá trị nào lên object — nếu render loop không gọi mixer.update(delta) mỗi frame, console sạch nhưng object đứng yên tuyệt đối, dễ tưởng nhầm là clip sai thay vì thiếu một dòng update."},{"label":"Nhồi giá trị không phải quaternion chuẩn hoá vào QuaternionKeyframeTrack","detail":"Bộ nội suy giả định bốn số mỗi keyframe là quaternion đơn vị rồi nội suy cầu giữa chúng; truyền một mảng bốn số tuỳ ý (ví dụ nhầm với Euler hoặc quên chuẩn hoá) làm object co giãn/méo dần giữa hai keyframe thay vì xoay đều."},{"label":"Set .weight trên một action chưa từng .play()","detail":"Mixer chỉ trộn giá trị của các action đang active; đổi .weight của một action chưa play() không có tác dụng gì cả — crossfade tưởng đã chạy nhưng object vẫn hoàn toàn theo action còn lại."}],
    en: [{"label":"Forgetting to call mixer.update(delta) in the render loop","detail":"action.play() only flips an internal state flag and writes nothing onto the object — if the render loop never calls mixer.update(delta) every frame, the console stays clean but the object sits perfectly frozen, easy to mistake for a broken clip instead of one missing line."},{"label":"Feeding non-normalized values into a QuaternionKeyframeTrack","detail":"The interpolator assumes every four numbers per keyframe form a unit quaternion and blends spherically between them; passing an arbitrary four-number array (confused with Euler angles, or simply un-normalized) makes the object stretch and skew between keyframes instead of rotating cleanly."},{"label":"Setting .weight on an action that's never been .play()ed","detail":"The mixer only blends values from actions currently active; changing .weight on an action that hasn't been played has no effect at all — the crossfade looks like it should be running, but the object stays fully driven by the other action."}],
  },
  "cameras-and-controls": {
    vi: [{"label":"Bật enableDamping mà chỉ gọi controls.update() trong sự kiện chuột","detail":"Khi kéo, camera trễ theo chuột; thả tay là dừng khựng ngay, không có chút quán tính nào, và phần chuyển động chưa áp sẽ giật vào ở lần tương tác sau — vì damping chỉ áp một phần chuyển động mỗi lần update(), nên nó cần chạy mỗi frame kể cả khi không có input."},{"label":"Tween camera bằng code trong khi vòng lặp vẫn gọi controls.update()","detail":"update() gọi lookAt(controls.target) mỗi lần chạy nên hướng nhìn bạn đặt bị ghi đè, còn quán tính dư và clamp kéo camera lệch đường tween — animate luôn controls.target, hoặc ngừng gọi update() trong lúc tween (controls.enabled = false không đủ)."},{"label":"Đổi kích thước canvas mà quên gọi updateProjectionMatrix()","detail":"camera.aspect (hay left/right/top/bottom với Orthographic) đổi giá trị nhưng ma trận chiếu vẫn giữ nguyên vì nó chỉ được tính lại khi hàm này được gọi tường minh — hình ảnh bị méo đúng bằng tỉ lệ sai lệch giữa aspect cũ và mới."}],
    en: [{"label":"Enabling enableDamping but only calling controls.update() on pointer events","detail":"While dragging, the camera lags behind the pointer; on release it stops dead with no inertia at all, and the unapplied motion jumps in at the next interaction — damping applies only part of the motion per update(), so it needs update() every frame, including frames with zero input."},{"label":"Tweening the camera in code while the loop still calls controls.update()","detail":"update() calls lookAt(controls.target) on every run, so the direction you set is overwritten, and leftover inertia or clamps drag the camera off the tween — animate controls.target too, or stop calling update() during the tween (controls.enabled = false is not enough)."},{"label":"Resizing the canvas and forgetting updateProjectionMatrix()","detail":"camera.aspect (or left/right/top/bottom on Orthographic) changes value, but the projection matrix stays stale because it's only recomputed when this call fires explicitly — the image stretches by exactly the mismatch between the old and new aspect ratio."}],
  },
  "geometries-and-buffergeometry": {
    vi: [{"label":"Gán geometry mới cho mesh mà không dispose() geometry cũ","detail":"mesh.geometry = newGeometry chỉ đổi tham chiếu JavaScript — buffer WebGL của geometry cũ vẫn nằm nguyên trong VRAM cho tới khi bạn tự gọi dispose() trên nó."},{"label":"Tưởng segment càng cao càng \"an toàn\"","detail":"Khi cả widthSegments lẫn heightSegments cùng tăng, số tam giác tăng gần bậc hai, không phải một khoản chi phí nhỏ tuyến tính — SphereGeometry(1, 24, 10) cho 432 tam giác, SphereGeometry(1, 50, 50) cho 4900 — hơn 11 lần cho một cải thiện thị giác thường không đáng."},{"label":"Kỳ vọng setIndex() luôn tiết kiệm bộ nhớ","detail":"Index chỉ có tác dụng khi các tam giác thật sự chia sẻ entry vertex giống hệt nhau (thường xảy ra trong cùng một mặt phẳng); với hình học toàn mặt tam giác rời như hình chóp ở trên, phần lớn entry vẫn không chia sẻ được dù có setIndex()."}],
    en: [{"label":"Assigning a new geometry to a mesh without dispose()-ing the old one","detail":"mesh.geometry = newGeometry only swaps a JavaScript reference — the old geometry's WebGL buffers stay allocated in VRAM until you explicitly call dispose() on it."},{"label":"Assuming higher segments is always \"safer.\"","detail":"When both widthSegments and heightSegments go up together, triangle count scales close to quadratically, not as a small linear cost — SphereGeometry(1, 24, 10) gives 432 triangles, SphereGeometry(1, 50, 50) gives 4900 — over 11 × more for a visual improvement that's often not worth it."},{"label":"Expecting setIndex() to always save memory","detail":"Indexing only helps when triangles genuinely share identical vertex entries (usually within the same flat face); for geometry made entirely of separate triangular faces, like the pyramid above, most entries still can't be shared even with setIndex()."}],
  },
  "lights-and-shadow-maps": {
    vi: [{"label":"Bật castShadow trên light và mesh nhưng quên renderer.shadowMap.enabled = true","detail":"Cả pipeline shadow tắt hoàn toàn ở cấp renderer, khiến castShadow/receiveShadow trên từng object trở thành vô nghĩa mà không có lỗi nào báo."},{"label":"Quên receiveShadow = true trên mặt sàn","detail":"Vật thể vẫn đổ bóng đúng vào shadow map, nhưng mặt sàn không bao giờ tra cứu shadow map khi shading nên bóng không hiện — dễ nhầm là lỗi ở light hoặc camera thay vì thiếu đúng một cờ trên mesh nhận bóng."},{"label":"Đẩy bias âm quá sâu để \"chữa\" shadow acne mà không kiểm tra lại điểm tiếp xúc","detail":"Acne biến mất nhưng đổi sang peter-panning, bóng trôi khỏi chân vật thể; nên tăng độ lớn bias âm từng bước nhỏ, hoặc ưu tiên normalBias trước khi đẩy bias thô lên cao."}],
    en: [{"label":"Turning on castShadow for a light and mesh but forgetting renderer.shadowMap.enabled = true","detail":"The entire shadow pipeline stays off at the renderer level, so every per-object castShadow/receiveShadow flag becomes meaningless with no error to tell you why."},{"label":"Forgetting receiveShadow = true on the ground","detail":"The object still casts a perfectly correct shadow into the shadow map, but the ground never samples that map while shading, so no shadow appears — easy to misdiagnose as a light or camera bug instead of one missing flag on the receiving mesh."},{"label":"Pushing bias too far negative to \"fix\" shadow acne without re-checking the contact point","detail":"The acne disappears but flips into peter-panning, the shadow drifting off the object's base; grow the negative bias in small steps instead, or reach for normalBias before pushing raw bias too far."}],
  },
  "loading-gltf-draco-meshopt": {
    vi: [{"label":"Quên gọi setDRACOLoader/setMeshoptDecoder trước lần load() đầu tiên","detail":"File dùng extension KHR_draco_mesh_compression hoặc EXT_meshopt_compression mà chưa đăng ký decoder tương ứng khiến GLTFLoader ném thẳng lỗi (\"No DRACOLoader instance provided.\" / \"setMeshoptDecoder must be called...\") — decoder phải có mặt trước khi bước parse bắt đầu; quy ước an toàn là gắn trước khi gọi load()."},{"label":"Gọi lại loader.load() mỗi lần effect chạy lại mà không hủy request cũ","detail":"Dưới React Strict Mode, effect chạy hai lần khi mount — nếu không có cờ cancelled trong cleanup, onLoad của lần gọi đầu vẫn chạy sau khi component đã unmount/remount, add trùng mesh vào scene hoặc ghi vào state đã chết."},{"label":"Quên dispose hierarchy khi đổi model hoặc unmount","detail":"gltf.scene cũ vẫn giữ geometry/material/texture trên VRAM dù đã bị gỡ khỏi scene — thấy rõ nhất khi người dùng đổi qua lại nhiều model trong một viewer, VRAM tăng dần mà không bao giờ giảm."}],
    en: [{"label":"Forgetting to call setDRACOLoader/setMeshoptDecoder before the first load()","detail":"A file using the KHR_draco_mesh_compression or EXT_meshopt_compression extension without the matching decoder registered makes GLTFLoader throw outright (\"No DRACOLoader instance provided.\" / \"setMeshoptDecoder must be called...\") — the decoder must exist before the parse step begins; the safe convention is to attach it before calling load()."},{"label":"Calling loader.load() again every time an effect re-runs, without cancelling the previous request","detail":"Under React Strict Mode, effects run twice on mount — without a cancelled flag checked in the cleanup, the first call's onLoad still fires after the component has unmounted/remounted, adding a duplicate mesh to the scene or writing into dead state."},{"label":"Forgetting to dispose the hierarchy when swapping models or unmounting","detail":"The old gltf.scene still holds geometry/material/texture VRAM even after being removed from scene — most visible when a user flips through several models in one viewer, with VRAM climbing and never coming back down."}],
  },
  "materials-from-basic-to-physical": {
    vi: [{"label":"Sửa property trên một material đang bị nhiều mesh dùng chung","detail":"const shared = new THREE.MeshStandardMaterial(...) rồi gán cho 50 mesh để tiết kiệm bộ nhớ là hợp lý — nhưng gọi shared.roughness = 0.1 sau đó đổi ngoại hình của cả 50 mesh cùng lúc, vì chúng tham chiếu đúng một object JS. Cần độc lập hoá appearance thì clone() material trước, hoặc dùng attribute per-instance."},{"label":"Gán mesh.material = newMat mà quên .dispose() material cũ","detail":"Three.js không tự dọn — làm việc này trong một vòng lặp (ví dụ mỗi lần kéo slider) mà không dispose sẽ tích tụ state per-material phía renderer và giữ sống mọi texture material cũ tham chiếu. Shader program được cache theo cấu hình và đếm tham chiếu — thay bằng material cùng cấu hình thì dùng chung program cũ, không nhân lên; nhưng material cũ khác cấu hình mà chưa dispose vẫn giữ program của nó sống. Thứ ăn VRAM nhanh nhất thường là texture không được dispose."},{"label":"Kỳ vọng MeshBasicMaterial phản ứng với ánh sáng hoặc đổ bóng","detail":"receiveShadow trên mesh dùng Basic không có tác dụng — shader của Basic không hề đọc shadow map. Nhưng castShadow thì vẫn hoạt động: pass đổ bóng render mọi vật bằng depth material nội bộ của renderer, bỏ qua material của chính vật, nên mesh Basic vẫn đổ bóng lên vật khác."}],
    en: [{"label":"Mutating a property on a material shared by many meshes","detail":"const shared = new THREE.MeshStandardMaterial(...) assigned to 50 meshes to save memory is a reasonable move — but calling shared.roughness = 0.1 afterward changes the appearance of all 50 meshes at once, since they reference the exact same JS object. To vary appearance independently, clone() the material first, or drive the difference through a per-instance attribute."},{"label":"Assigning mesh.material = newMat and forgetting .dispose() on the old one","detail":"Three.js doesn't clean this up automatically — doing this inside a loop (every slider drag, say) without disposing accumulates renderer-side per-material state and keeps alive every texture the old material references. Shader programs are cached per configuration and reference-counted — a replacement with the same configuration reuses the existing program rather than adding one; but an undisposed old material with a different configuration keeps its program alive. What usually eats VRAM fastest is undisposed textures."},{"label":"Expecting MeshBasicMaterial to respond to lighting or cast/receive shadows","detail":"receiveShadow on a Basic-material mesh does nothing — Basic's shader never reads a shadow map. But castShadow still works: the shadow pass renders every caster with the renderer's internal depth material, ignoring the object's own material, so a Basic mesh still throws shadows onto others."}],
  },
  "raycasting-and-picking": {
    vi: [{"label":"Quên lật trục Y khi map chuột sang NDC","detail":"Không throw lỗi, không crash — chỉ khiến hit test trúng object đối xứng qua tâm màn hình theo trục dọc, trông \"gần đúng\" nên rất khó nhận ra ngay."},{"label":"intersectObjects(scene.children, true) cho toàn bộ scene thay vì mảng pickable","detail":"Hoạt động đúng lúc scene còn nhỏ nhưng lag dần khi thêm object, vì mỗi lần raycast phải test luôn cả ánh sáng, helper và object không cần tương tác."},{"label":"Raycast Points/Lines với threshold mặc định quá nhỏ","detail":"Point cloud hay line mảnh không có bề mặt hình học để \"trúng\" theo nghĩa thông thường — quên set raycaster.params.Points.threshold/Line.threshold cho khớp tỉ lệ scene khiến click/hover tưởng như không hoạt động."}],
    en: [{"label":"Forgetting to flip the Y axis when mapping the mouse to NDC","detail":"No error, no crash — it just makes the hit test land on the object mirrored vertically across the screen's center, which looks \"roughly right\" and is easy to miss at first glance."},{"label":"intersectObjects(scene.children, true) against the whole scene instead of a pickable array","detail":"Works fine while the scene is small, then gets progressively laggier as objects are added, since every raycast has to test lights, helpers, and objects that were never meant to be interactive."},{"label":"Raycasting Points/Lines with a default threshold that's too small","detail":"A point cloud or thin line has no geometric surface to \"hit\" in the usual sense — forgetting to set raycaster.params.Points.threshold/Line.threshold to match the scene's scale makes clicking or hovering look like it simply doesn't work."}],
  },
  "reading-threejs-source": {
    vi: [{"label":"Tưởng add() giữ world position như attach()","detail":"add() không đụng tới position — object bị tái diễn giải toạ độ cục bộ trong hệ quy chiếu mới, nhảy vị trí ngay khi cha mới không ở gốc toạ độ; muốn giữ world transform bắt buộc phải dùng attach()."},{"label":"Tin frustumCulled luôn đúng với geometry bị vertex shader di chuyển","detail":"Test cull dùng geometry.boundingSphere tính từ vị trí đỉnh GỐC trên CPU, TRƯỚC khi vertex shader chạy — một shader làm cây đung đưa hay particle bay xa khỏi bounding sphere gốc có thể bị cull nhầm dù vẫn \"nhìn thấy được\"; phải tự phóng to boundingSphere.radius hoặc tắt frustumCulled cho geometry loại này."},{"label":"Đọc code trên branch dev/master rồi áp cho bản three đã cài","detail":"GitHub mặc định hiển thị branch mới nhất, luôn đi trước phiên bản npm đã pin trong package.json; hành vi có thể đã đổi giữa hai bản. Luôn mở đúng tag khớp version cài đặt, như r185 ở bài này."}],
    en: [{"label":"Assuming add() preserves world position like attach() does","detail":"add() never touches position — the object's local coordinate gets re-interpreted in the new frame, jumping instantly whenever the new parent isn't at the origin; preserving world transform requires attach()."},{"label":"Trusting frustumCulled for geometry a vertex shader displaces","detail":"The cull test uses geometry.boundingSphere, computed from the ORIGINAL vertex positions on the CPU, BEFORE the vertex shader ever runs — a shader that sways foliage or blows particles beyond that original sphere can get culled while still visibly needed; you have to manually inflate boundingSphere.radius or disable frustumCulled for that geometry."},{"label":"Reading code on the dev/master branch and applying it to the installed three version","detail":"GitHub defaults to showing the latest branch, which is always ahead of whatever's pinned in package.json; behavior can have changed between the two. Always open the tag matching the installed version, like r185 in this lesson."}],
  },
  "scene-camera-renderer": {
    vi: [{"label":"Đổi camera.fov/aspect/near/far mà quên gọi camera.updateProjectionMatrix()","detail":"Các field này chỉ là property JavaScript thường; ma trận P thật sự dùng để vẽ chỉ được tính lại khi bạn chủ động gọi hàm này — quên gọi, hình vẫn vẽ bằng ma trận cũ dù giá trị field đã đổi."},{"label":"Gọi renderer.render() một lần rồi mong animation tự chạy","detail":"Không có requestAnimationFrame nào ẩn bên trong render() — mỗi khung hình là một lệnh gọi tường minh, y hệt vòng lặp Track 1 bạn tự viết bằng gl.drawArrays mỗi frame."},{"label":"Gọi setPixelRatio(window.devicePixelRatio) không clamp","detail":"Trên thiết bị DPR cao, số fragment invocation mỗi frame tăng theo bậc hai của DPR — một chiếc điện thoại DPR 3 phải render nhiều hơn gấp hai lần so với clamp ở DPR 2, đổi lại độ nét gần như không ai phân biệt được bằng mắt thường."}],
    en: [{"label":"Changing camera.fov/aspect/near/far and forgetting camera.updateProjectionMatrix()","detail":"These fields are plain JavaScript properties; the P matrix actually used to draw is only recomputed when you explicitly call this method — skip it, and the frame still renders with the old matrix even though the field's value has changed."},{"label":"Calling renderer.render() once and expecting animation to run on its own","detail":"There's no hidden requestAnimationFrame inside render() — every frame is an explicit call, exactly like the loop you wrote by hand in Track 1 with gl.drawArrays every frame."},{"label":"Calling setPixelRatio(window.devicePixelRatio) without clamping","detail":"On high-DPR devices, fragment invocations per frame scale with the square of DPR — a DPR-3 phone ends up rendering more than twice as many pixels as a DPR-2 clamp, for sharpness nobody can actually tell apart by eye."}],
  },
  "scene-graph-and-transforms": {
    vi: [{"label":"Đọc object.position để lấy world position của một object lồng sâu trong hierarchy","detail":".position luôn là toạ độ local so với cha trực tiếp — object càng nằm sâu, sai lệch với world position thật càng lớn. Dùng getWorldPosition(target) khi cần toạ độ world thật."},{"label":"Dùng add() khi ý định thực sự là giữ nguyên world transform lúc đổi cha","detail":"add() giữ số local, khiến object \"nhảy\" world position ngay khi gắn vào cha mới có matrixWorld khác; attach() mới là hàm giữ world transform không đổi."},{"label":"Tắt matrixAutoUpdate rồi quên gọi updateMatrix() sau khi chỉnh transform bằng code","detail":"Object đứng yên ở vị trí cũ dù .position đã đổi giá trị trong bộ nhớ — không có lỗi hay warning nào hiện ra, chỉ là hình ảnh sai lặng lẽ."}],
    en: [{"label":"Reading object.position to get the world position of an object nested deep in a hierarchy","detail":".position is always local relative to the direct parent — the deeper the object sits, the further it drifts from its actual world position. Use getWorldPosition(target) when you need the real world coordinate."},{"label":"Using add() when the actual intent is preserving world transform across a reparent","detail":"add() keeps the local numbers, so the object visually jumps to a new world position the instant it's attached to a parent with a different matrixWorld; attach() is the call that keeps world transform unchanged."},{"label":"Turning off matrixAutoUpdate and then forgetting to call updateMatrix() after changing the transform in code","detail":"The object stays frozen at its old position even though .position changed in memory — no error, no warning, just a silently wrong render."}],
  },
  "textures-and-compression-ktx2": {
    vi: [{"label":"Tưởng \"file JPG nhẹ trên đĩa nên texture nhẹ\"","detail":"GPU luôn lưu ảnh đã giải mã đầy đủ (RGBA thô cộng mip chain) — con số VRAM hoàn toàn không liên quan đến kích thước file nén trên đĩa."},{"label":"Gắn SRGBColorSpace cho texture dữ liệu (normalMap/roughnessMap) thay vì chỉ gắn cho color map","detail":"GPU tự decode gamma sai trên giá trị không phải màu, làm lệch toàn bộ pháp tuyến/độ nhám — lỗi shading khó nhận ra vì không trực tiếp liên quan tới màu nhìn thấy."},{"label":"Gọi KTX2Loader.load() mà quên detectSupport(renderer) trước đó","detail":"Loader không biết định dạng transcode đích của thiết bị, load lỗi hoặc throw runtime dù file .ktx2 hoàn toàn hợp lệ."}],
    en: [{"label":"Assuming \"the JPG is small on disk, so the texture is light.\"","detail":"The GPU always stores a fully decoded image (raw RGBA plus its mip chain) — the VRAM number has nothing to do with the compressed file's size on disk."},{"label":"Marking SRGBColorSpace on a data texture (normalMap/roughnessMap) instead of only on color maps","detail":"The GPU gamma-decodes non-color values incorrectly, skewing every normal/roughness value — a shading bug that's hard to spot because it's not directly about visible color."},{"label":"Calling KTX2Loader.load() without calling detectSupport(renderer) first","detail":"The loader has no idea which transcode target the device supports, so loading fails or throws at runtime even though the .ktx2 file itself is perfectly valid."}],
  },
  "disposal-and-memory-leaks": {
    vi: [{"label":"Tưởng <primitive object={mesh} /> cũng auto-dispose như mesh JSX bình thường","detail":"Tài liệu R3F nói rõ primitive KHÔNG bao giờ tự dispose — object bên trong luôn cần dispose tay, dù tự new hay lấy từ useGLTF."},{"label":"Dispose một geometry/material đang được nhiều mesh dùng chung","detail":".dispose() giải phóng buffer GPU ngay — nhưng mesh khác còn tham chiếu geometry đó khiến renderer lặng lẽ upload lại từ mảng CPU ở lần vẽ kế: không lỗi, không rác, chỉ là lệnh dispose bị vô hiệu và tốn một lần upload — VRAM không hề được giải phóng như bạn tưởng. Dùng chung thì đặt dispose={null} và tự quản lý vòng đời ở nơi tạo ra, không phải từng consumer."},{"label":"Gọi loseContext()/forceContextLoss() trong cleanup để \"dọn sạch\" canvas","detail":"Strict Mode tái sử dụng đúng canvas element khi remount, context đã lost không tự phục hồi — cách đúng là dispose từng geometry/material/texture tự tạo, để trình duyệt tự thu hồi context khi canvas thật sự rời DOM."}],
    en: [{"label":"Assuming <primitive object={mesh} /> auto-disposes like an ordinary JSX mesh","detail":"The R3F docs are explicit that primitives NEVER auto-dispose — the object inside always needs manual disposal, whether you new'd it yourself or got it from useGLTF."},{"label":"Disposing a geometry/material still shared by multiple meshes","detail":".dispose() frees the GPU buffer immediately — but any other mesh still referencing that geometry makes the renderer silently re-upload it from the CPU arrays on the next draw: no garbage, no error, just a defeated dispose plus an extra upload — the VRAM is never actually reclaimed. For shared resources, set dispose={null} and manage the lifecycle at the place that created it, not at each consumer."},{"label":"Calling loseContext()/forceContextLoss() in cleanup to \"clean up\" the canvas","detail":"Strict Mode reuses the exact same canvas element on remount, and a lost context doesn't recover on its own — the correct cleanup is disposing every geometry/material/texture you created, and letting the browser reclaim the context once the canvas truly leaves the DOM."}],
  },
  "drei-essentials": {
    vi: [{"label":"Tự gọi controls.update() thêm một lần trong useFrame của riêng mình khi đã dùng <OrbitControls />","detail":"Component này tự update mỗi frame nội bộ — update kép không làm gì sai về logic nhưng lãng phí một lượt tính toán mỗi frame, và dễ gây lẫn lộn khi debug độ trễ input."},{"label":"Đặt hàng chục <Html occlude> trong một scene nặng mà quên occlusion là raycast CPU mỗi frame, không phải depth-test GPU","detail":"Vài label thì vô hình về chi phí; vài chục label trên scene nhiều mesh phức tạp có thể tụt fps rõ rệt — đo trước khi ship, không đoán."},{"label":"Coi mọi helper trong drei \"chắc chắn ổn định\" như core của react-three-fiber","detail":"Một số helper (đặc biệt các helper còn thử nghiệm) đổi API giữa các bản minor — khác hẳn cam kết semver của package lõi; luôn khoá version cụ thể và đọc changelog khi upgrade, không tự tin auto-update."}],
    en: [{"label":"Calling controls.update() again inside your own useFrame when already using <OrbitControls />","detail":"The component already updates every frame internally — the double update isn't logically wrong, but wastes a computation pass every frame and muddies input-lag debugging."},{"label":"Dropping dozens of <Html occlude> labels into a heavy scene while forgetting occlusion is a CPU raycast every frame, not a GPU depth test","detail":"A handful of labels costs nothing measurable; dozens on a scene full of complex meshes can visibly tank the frame rate — profile it, don't guess."},{"label":"Treating every drei helper as \"certainly stable\" the way react-three-fiber's core is","detail":"Some helpers (particularly the more experimental ones) change API between minor versions, unlike the core package's tight semver guarantees — pin an exact version and read the changelog on upgrade, don't auto-update blindly."}],
  },
  "jsx-to-three-mapping": {
    vi: [{"label":"Đưa giá trị animate mượt vào args","detail":"args chỉ chạy một lần lúc constructor — đổi nó mỗi frame (ví dụ nối args={[radius, 32, 32]} với một radius animate) huỷ và dựng lại toàn bộ geometry, re-upload buffer GPU liên tục thay vì chỉ mutate scale."},{"label":"Đặt geometry/material dưới nhầm HOST cha","detail":"Auto-attach quyết định theo KIỂU instance (isBufferGeometry → attach=\"geometry\", isMaterial → \"material\") và gắn vào host cha gần nhất — bọc qua component React tự viết vẫn ổn (component không tạo host node), nhưng lồng geometry dưới một <group> sẽ gắn thành group.geometry: không lỗi, không hiển thị gì. Với thứ không auto-attach được (ví dụ texture vào slot cụ thể), phải set attach tường minh."},{"label":"Tưởng color=\"hotpink\" tạo Color mới mỗi lần re-render","detail":"Khi giá trị đổi, R3F gọi .set() trên Color instance có sẵn, không cấp phát object mới — nhưng nếu bạn TỰ tạo new THREE.Color() trong thân component (ngoài useMemo) rồi truyền qua một prop khác, bạn mới thực sự tạo object rác mỗi lần render, không phải do JSX gây ra."}],
    en: [{"label":"Putting a smoothly-animated value into args","detail":"args only runs once, at construction — changing it every frame (say, wiring args={[radius, 32, 32]} to an animated radius) destroys and rebuilds the entire geometry, re-uploading a GPU buffer continuously instead of simply mutating scale."},{"label":"Forgetting attach when geometry/material sits under the wrong HOST parent","detail":"Auto-attach is decided purely by instance TYPE (isBufferGeometry → attach=\"geometry\", isMaterial → \"material\") and attaches to the nearest host parent — wrapping in a custom React component is fine (components create no host node), but nesting a geometry under a <group> attaches it as group.geometry: no error, nothing renders. For anything auto-attach cannot infer (say a texture into a specific slot), set attach explicitly."},{"label":"Assuming color=\"hotpink\" allocates a new Color on every re-render","detail":"When the value changes, R3F calls .set() on the Color instance the material already owns — it allocates nothing new. The real allocation trap is constructing new THREE.Color() yourself in the component body (outside useMemo) and passing that instance through a different prop — that's what creates garbage every render, not the JSX string prop itself."}],
  },
  "leva-debug-ui": {
    vi: [{"label":"Tưởng hidden={true} loại bỏ leva khỏi bundle production","detail":"Nó chỉ ẩn UI — code JavaScript của leva vẫn nằm trong bundle, vẫn được tải về, trừ khi import được tách theo NODE_ENV hoặc dynamic import."},{"label":"Gọi useControls() lặp lại bên trong useFrame để \"đọc giá trị mới nhất\"","detail":"useControls là một React hook, không phải một hàm đọc nhanh — gọi nó 60 lần một giây vi phạm rules-of-hooks và ép re-render liên tục; đúng chỗ cần dùng là dạng function-schema với get/set (transient read)."},{"label":"Nhầm control panel của một sản phẩm thật (như panel Demo của nền tảng này) với một devtool kiểu leva","detail":"Cả hai đều \"khai báo schema → sinh UI\", nhưng panel sản phẩm là một phần UI CHÍNH THỨC ship cho người dùng cuối, còn leva là công cụ dev-time — trộn lẫn hai vai trò dễ dẫn tới việc vô tình ship UI tinh chỉnh nội bộ ra bản production."}],
    en: [{"label":"Assuming hidden={true} removes leva from the production bundle","detail":"It only hides the UI — leva's JavaScript still ships in the bundle and still gets downloaded, unless the import itself is split by NODE_ENV or a dynamic import."},{"label":"Calling useControls() repeatedly inside useFrame to \"read the latest value.\"","detail":"useControls is a React hook, not a fast getter — calling it 60 times a second breaks the rules of hooks and forces continuous re-renders; the right tool is the function-schema form with get/set (a transient read)."},{"label":"Confusing a real product's control panel (like this platform's own Demo panel) with a leva-style devtool","detail":"Both are \"declare a schema, generate UI,\" but a product panel is official, shipped UI delivered to end users, while leva is a dev-time tool — blurring the two roles is how internal tuning UI accidentally ships in a production build."}],
  },
  "memoizing-geometry-and-materials": {
    vi: [{"label":"Bọc useMemo với dependency array thiếu sót","detail":"— ví dụ useMemo(() => new THREE.MeshStandardMaterial({ color }), []) quên color trong deps. Material \"đóng băng\" ở giá trị color ban đầu dù prop đổi liên tục, dễ khiến debug sai chỗ."},{"label":"Tưởng args giống hệt nhau giữa các JSX element anh em tự dedupe geometry","detail":"200 <boxGeometry args={[0.6,0.6,0.6]} /> ở 200 <mesh> khác nhau trong một .map() vẫn tạo 200 instance riêng — args-diff chỉ so một element với chính nó ở lần render trước."},{"label":"Kỳ vọng renderer.info.programs giảm khi chuyển sang material dùng chung","detail":"Nhầm lẫn giữa \"chia sẻ instance JS\" và \"chia sẻ chương trình GPU đã compile\" — Three.js đã dedupe theo cache key cấu trúc bất kể bạn share instance hay không; geometries mới là thước đo đúng."}],
    en: [{"label":"An incomplete useMemo dependency array","detail":"— e.g. useMemo(() => new THREE.MeshStandardMaterial({ color }), []) forgetting color. The material freezes at its initial color forever even as the prop keeps changing, an easy bug to misdiagnose elsewhere."},{"label":"Assuming identical args across sibling JSX elements auto-dedupes geometry","detail":"200 <boxGeometry args={[0.6,0.6,0.6]} /> across 200 different <mesh> elements in a .map() still create 200 separate instances — args-diff only compares an element against its own previous render, never across siblings."},{"label":"Expecting renderer.info.programs to drop with a shared material","detail":"This confuses \"sharing a JS instance\" with \"sharing a compiled GPU program\" — Three.js already dedupes programs by structural cache key regardless; geometries is the metric that actually reflects hoisting."}],
  },
  "portals-views-multi-canvas": {
    vi: [{"label":"Quên manual trên camera orthographic bên trong View","detail":"Thiếu nó, View tự ép left/right/top/bottom khớp pixel của rect đang track mỗi frame — frustum tự đặt trong code lặng lẽ bị ghi đè, không lỗi nào log ra console."},{"label":"Tưởng nhiều <View> chia sẻ chung một Three.js Scene","detail":"Mỗi <View> render vào một virtual scene riêng — di chuyển object ở khung nhìn này không tự động di chuyển bản \"giống hệt\" ở khung nhìn kia, trừ khi cả hai điều khiển từ cùng một state bên ngoài."},{"label":"Quên rằng scissor giới hạn cả vùng clear()","detail":"Khi scissor test đang bật, clear() chỉ xoá bên trong rect đó. Canvas mặc định (preserveDrawingBuffer: false) được trình duyệt xoá toàn bộ sau mỗi frame nên không sao; nhưng với preserveDrawingBuffer: true, hoặc khi vẽ vào một render target giữ qua nhiều frame, pixel cũ ở vùng không vẽ lại (chỗ object vừa rời khỏi) còn nguyên thành vệt bóng ma — tắt scissor rồi clear() toàn bộ ở đầu frame."}],
    en: [{"label":"Forgetting manual on an orthographic camera inside a View","detail":"Without it, View silently forces left/right/top/bottom to match the tracked rect's pixel dimensions every frame — any frustum set in code gets overwritten with nothing logged to the console."},{"label":"Assuming multiple <View>s share one Three.js Scene","detail":"Each <View> renders into its own virtual scene — moving an object in one viewport doesn't automatically move its \"identical\" counterpart in another, unless both are driven from the same external state."},{"label":"Forgetting that scissor restricts clear() too","detail":"With the scissor test on, clear() only wipes inside that rect. A default canvas (preserveDrawingBuffer: false) is cleared whole by the browser after every frame, so no harm done; but with preserveDrawingBuffer: true, or when rendering into a render target that persists across frames, old pixels in regions not repainted (say, where an object just moved away from) stay put as a ghost trail — turn scissor off and clear() everything at the frame's start."}],
  },
  "r3f-core-hooks": {
    vi: [{"label":"Gọi setState bên trong useFrame để lưu vị trí/góc animate","detail":"Đây chính là chủ đề chính của bài — mỗi setState là một lượt reconciliation React đầy đủ, 60 lần/giây với animation mượt, trong khi mutate ref qua object Three.js thật không tốn gì thêm ngoài một phép gán."},{"label":"Gọi useThree() không selector trong một component nằm sâu, cập nhật thường xuyên","detail":"Component subscribe vào toàn bộ state nên một sự kiện resize/DPR đổi kéo re-render cả những component chỉ cần đọc camera, dù chẳng liên quan gì đến kích thước canvas."},{"label":"Không kiểm tra ref.current trước khi dùng trong useFrame","detail":"Component có thể unmount giữa lúc animation đang chạy (chuyển route, đóng modal); truy cập .rotation trên null crash toàn bộ canvas — luôn if (!meshRef.current) return; đầu callback thay vì tin object luôn tồn tại."}],
    en: [{"label":"Calling setState inside useFrame to store an animated position or angle","detail":"This is this lesson's central topic for a reason — every setState is a full React reconciliation pass, 60 times a second for a smooth animation, while mutating a ref through a real Three.js object costs nothing beyond a single assignment."},{"label":"Calling useThree() without a selector inside a deep, frequently-updating component","detail":"The component subscribes to the entire state, so a resize or DPR change re-renders components that only ever read camera, even though neither has anything to do with canvas size."},{"label":"Not guarding ref.current before using it inside useFrame","detail":"A component can unmount mid-animation (route change, closed modal); reading .rotation off null crashes the whole canvas — always start the callback with if (!meshRef.current) return; instead of assuming the object still exists."}],
  },
  "r3f-vs-vanilla-three": {
    vi: [{"label":"Coi \"no overhead\" là toàn bộ câu chuyện hiệu năng","detail":"Docs R3F khẳng định component không tạo chi phí vì \"render outside of React\" — đúng cho việc commit từng frame, nhưng không nghĩa là mount/unmount hàng nghìn node JSX mỗi giây rẻ ngang vanilla: reconciler vẫn phải walk fiber tree mỗi khi cấu trúc JSX đổi, một chi phí khác hẳn chi phí render."},{"label":"Chạy song song hai vòng lặp animation","detail":"Vừa dựa vào frameloop=\"demand\" của DemoCanvas (tự invalidate khi visible), vừa tự thêm một requestAnimationFrame thủ công \"cho chắc\" trong cùng component — kết quả hai loop độc lập cùng update state, animation giật hoặc chạy đúp tốc độ mà không rõ nguyên nhân."},{"label":"Nghĩ chuyển vanilla sang R3F chỉ là \"bọc JSX quanh code cũ\"","detail":"Auto-dispose chỉ áp dụng cho geometry/material tạo trực tiếp trong JSX; geometry hoist bằng useMemo hay texture nạp thủ công vẫn phải tự .dispose() — đúng lỗi kinh điển ở bài Disposal & Memory Leaks, chỉ đội lốt mới khi ai đó nghĩ \"R3F lo hết rồi\"."}],
    en: [{"label":"Treating \"no overhead\" as the whole performance story","detail":"R3F's docs state components carry no cost because they \"render outside of React\" — true for per-frame commits, but it doesn't mean mounting/unmounting thousands of JSX nodes per second is as cheap as vanilla: the reconciler still walks the fiber tree every time the JSX structure changes, a different cost than render cost."},{"label":"Running two competing animation loops at once","detail":"Relying on DemoCanvas's frameloop=\"demand\" (auto-invalidating while visible) while also adding a manual requestAnimationFrame loop \"just to be safe\" in the same component — the result is two independent loops both updating state, causing stutter or doubled speed with no obvious cause."},{"label":"Assuming vanilla-to-R3F is \"just wrapping the old code in JSX.\"","detail":"Auto-dispose only applies to geometry/material created directly in JSX; geometry hoisted with useMemo or a manually loaded texture still needs its own .dispose() — the classic Disposal & Memory Leaks mistake, wearing a new disguise once someone assumes \"R3F handles it all.\""}],
  },
  "suspense-and-asset-loading": {
    vi: [{"label":"Đặt một <div> DOM thường làm fallback bên trong Canvas","detail":"Suspense nằm trong cây R3F yêu cầu con của nó là object Three.js hợp lệ (mesh, group) hoặc <Html> của drei — một <div> trần gây lỗi runtime ngay lập tức, không phải lỗi \"âm thầm\"."},{"label":"Quên Error Boundary, để Suspense một mình xử lý cả lỗi lẫn loading","detail":"Suspense chỉ bắt Promise pending; khi Promise reject, React throw một Error THẬT ở lần render kế, bay thẳng lên Error Boundary gần nhất — thiếu nó, một asset 404 làm sập cả nhánh UI thay vì chỉ hiện thông báo lỗi gọn gàng."},{"label":"Preload không khớp cache key","detail":"Gọi preload với constructor loader ở một chỗ, gọi useLoader với một instance loader tự tạo ở chỗ khác — hai cache key [loader, url] khác nhau dù url giống hệt, preload coi như chưa từng chạy."}],
    en: [{"label":"Using a plain DOM <div> as a fallback inside Canvas","detail":"A Suspense living inside the R3F tree requires its children to be valid Three.js objects (mesh, group) or drei's <Html> — a bare <div> fails at runtime immediately, not silently."},{"label":"Forgetting the Error Boundary and letting Suspense handle both loading and failure","detail":"Suspense only catches pending Promises; once a Promise rejects, React throws a REAL Error on the next render, propagating straight to the nearest Error Boundary — without one, a 404'd asset crashes the entire UI branch instead of showing a clean error message."},{"label":"A preload that doesn't match the cache key","detail":"Calling preload with the loader constructor in one place, then useLoader with a self-constructed instance somewhere else — two different [loader, url] cache keys despite an identical url, so the preload effectively never ran."}],
  },
  "why-r3f-reconciler": {
    vi: [{"label":"Gọi scene.add()/.remove() thủ công bên trong component R3F","detail":"Reconciler không biết gì về object bạn tự thêm bằng tay — nó không nằm trong cây fiber nên không được diff, không được dispose khi unmount, và dễ tạo ra object trùng lặp mỗi lần component re-render."},{"label":"Dùng index mảng làm key cho danh sách mesh có thể sắp lại hoặc lọc","detail":"Key bám theo vị trí, không theo dữ liệu: state gắn qua ref nhảy sang sai item và mesh giật chỗ."},{"label":"Tưởng unmount luôn tự dispose mọi thứ","detail":"Tự động dispose chỉ áp dụng cho geometry/material được JSX tạo ra trực tiếp; texture nạp thủ công ngoài JSX, event listener gắn tay, hay object dựng bằng new THREE.X() ngoài cây component vẫn phải tự cleanup — chi tiết đầy đủ ở bài Disposal & Memory Leak."}],
    en: [{"label":"Calling scene.add()/.remove() manually inside an R3F component","detail":"The reconciler knows nothing about an object you added by hand — it's not part of the fiber tree, so it never gets diffed, never gets disposed on unmount, and easily ends up duplicated on every re-render."},{"label":"Using the array index as key for a mesh list that can be reordered or filtered","detail":"Keys follow position, not data: the reconciler keeps the old meshes and writes other items' props onto them, so animation state attached via ref jumps to the wrong item and meshes pop."},{"label":"Assuming unmount always disposes everything","detail":"Automatic disposal only covers geometries/materials created directly by JSX; textures loaded imperatively outside JSX, manually attached event listeners, or objects built with new THREE.X() outside the component tree still need explicit cleanup — full details in the Disposal & Memory Leak lesson."}],
  },
  "animation-principles-for-ui": {
    vi: [{"label":"Thêm squash & stretch hoặc overshoot quá đà cho một thao tác lặp lại nhiều lần","detail":"Một nút hoạt hình vui mắt lần đầu bấm trở nên khó chịu ở lần bấm thứ 50 trong ngày — biên độ hợp lý cho một hành động thường xuyên nhỏ hơn nhiều so với hero moment chỉ chạy một lần."},{"label":"Bỏ qua prefers-reduced-motion vì \"chỉ là UI nhỏ\"","detail":"Đây không phải sở thích thẩm mỹ của một nhóm nhỏ — nó là yêu cầu accessibility có thể gây hại thật (chóng mặt, buồn nôn) nếu bỏ qua, tương đương mức độ nghiêm trọng với thiếu alt text hay contrast kém."},{"label":"Cho nhiều phần tử animate mạnh đồng thời, vi phạm staging","detail":"Kết quả không phải \"sống động hơn\" mà là mắt người xem không biết nhìn đâu — hai chuyển động cạnh tranh sự chú ý gây cảm giác hỗn loạn nhiều hơn hào hứng."}],
    en: [{"label":"Adding squash & stretch or heavy overshoot to a frequently-repeated action","detail":"A playful bounce feels charming the first time a button is pressed and grating by the 50th press of the day — the right amplitude for a routine action is much smaller than for a hero moment that only plays once."},{"label":"Skipping prefers-reduced-motion because \"it's just a small UI detail.\"","detail":"This isn't a niche aesthetic preference — it's an accessibility requirement that can cause real harm (dizziness, nausea) if ignored, on par in severity with missing alt text or poor contrast."},{"label":"Letting multiple elements animate strongly at the same instant, violating staging","detail":"The result isn't \"more lively,\" it's a viewer who doesn't know where to look — two motions competing for attention reads as chaos, not excitement."}],
  },
  "choosing-your-animation-tool": {
    vi: [{"label":"Kéo GSAP vào chỉ để animate một hover state","detail":"Một gsap.to(el, {y:-4}) khi hover làm đúng việc hai dòng CSS transition đã làm — trả giá ~27kB cho zero lợi ích thực. Mặc định dùng CSS trước, chỉ nâng cấp lên JS khi biên đạo vượt quá thứ CSS biểu đạt được."},{"label":"Tạo tween GSAP trong component React mà không scope qua gsap.context()","detail":"Tween sống sót qua unmount, tiếp tục animate một node đã gỡ khỏi DOM; dưới Strict Mode, effect chạy hai lần trên cùng DOM nên tween bị nhân đôi (một from() kẹt ở giá trị from) và ScrollTrigger chồng chất — mount một lần thì không lộ gì, bug chỉ hiện khi component mount lại (Strict Mode lúc dev, route change)."},{"label":"Coi layout animation của Motion là \"FLIP miễn phí\" không tốn gì","detail":"Mỗi phần tử có layout được đo getBoundingClientRect mỗi lần layout đổi — vài chục phần tử không vấn đề, danh sách hàng trăm dòng re-order liên tục mỗi frame cuộn thì phép đo đó cộng dồn thành cost thật, không phải phép màu không tính phí."}],
    en: [{"label":"Reaching for GSAP just to animate a hover state","detail":"A gsap.to(el, {y:-4}) on hover does exactly what two lines of CSS transition already do — for ~27kB with zero real benefit. Default to CSS first; only upgrade to JS once the choreography outgrows what CSS can express."},{"label":"Creating a GSAP tween inside a React component without scoping it in gsap.context()","detail":"The tween survives unmount and keeps animating a node that's already been removed from the DOM; under Strict Mode the effect runs twice on the same DOM, so tweens double up (a from() ends stuck at its from-values) and ScrollTriggers pile up — invisible on a single mount, so it only surfaces once the component remounts (Strict Mode in development, route changes)."},{"label":"Treating Motion's layout animation as \"free FLIP magic.\"","detail":"Every element with a layout prop gets measured with getBoundingClientRect on each layout change — fine for a few dozen elements, but a list of hundreds re-ordering every scroll frame turns that measurement into a real, accumulating cost, not a magic trick that costs nothing."}],
  },
  "compositor-friendly-animation": {
    vi: [{"label":"Animate top/left vì nghĩ \"chỉ là CSS nên chắc nhẹ\"","detail":"Cả hai đều nằm trong nhóm kích hoạt layout — mỗi frame trình duyệt phải tính lại vị trí của chính phần tử đó và thường cả các anh em phía sau nó trong flow, y hệt cơ chế \"layout thrash\" ở trên, dù bạn không hề đổi width."},{"label":"Quên set transform-origin khi dùng scaleX làm progress bar","detail":"Mặc định transform-origin là 50% 50% — scale một progress bar mà quên đặt transform-origin: left khiến nó phình ra từ giữa thay vì lớn dần từ mép trái như width vẫn làm, một lỗi thị giác rất dễ bỏ sót khi test ở tỉ lệ 100%."},{"label":"Rải will-change lên mọi phần tử \"cho chắc ăn\"","detail":"Mỗi layer promote thêm là một bitmap VRAM thật (công thức ở mục trên) — quá nhiều layer nhỏ cộng dồn thành áp lực bộ nhớ GPU, và trên thiết bị yếu trình duyệt có thể phải huỷ/tạo lại layer giữa chừng để giải phóng bộ nhớ, gây đúng cái giật mà will-change sinh ra để tránh."}],
    en: [{"label":"Animating top/left because \"it's just CSS, must be cheap\"","detail":"Both sit in the layout-triggering group — every frame the browser recomputes that element's position and usually the siblings following it in flow too, exactly the \"layout thrash\" mechanism above, even though you never touched width."},{"label":"Forgetting to set transform-origin when using scaleX for a progress bar","detail":"The default transform-origin is 50% 50% — scaling a progress bar without setting transform-origin: left makes it grow from the center instead of the left edge the way width naturally does, a visual bug that's easy to miss when testing at 100%."},{"label":"Slapping will-change on every element \"just in case\"","detail":"Every extra promoted layer is a real VRAM bitmap (the formula above) — too many small layers add up to real GPU memory pressure, and on weaker devices the browser may have to destroy and recreate layers mid-animation to free memory, causing exactly the stutter will-change was meant to prevent."}],
  },
  "easing-in-depth": {
    vi: [{"label":"Dùng back/elastic cho mọi thứ vì \"nhìn vui mắt\"","detail":"Hai họ ease này có overshoot — vọt qua điểm đích rồi lùi lại — hợp cho phản hồi nhỏ (nút, badge, toast) nhưng dùng cho layout lớn hay chuyển trang khiến giao diện thiếu chuyên nghiệp, càng lớn dao động càng gây khó chịu."},{"label":"Dùng chung một ease-out cho cả lúc xuất hiện lẫn lúc biến mất","detail":"power2.out giảm tốc dần VÀO điểm cuối — hợp cho entrance vì đọc như \"đang đáp xuống\". Áp dụng y hệt cho exit khiến phần tử trông như đang từ từ đáp xuống chỗ biến mất thay vì bị đẩy đi; nên đảo sang ease-in cho exit."},{"label":"Bỏ mặc ease: \"power1.out\" (hay bất kỳ ease non-linear nào) cho animation scrub theo ScrollTrigger","detail":"Scrub tween đã được điều khiển trực tiếp bởi vị trí cuộn — chồng thêm ease non-linear khiến progress hiển thị trễ hoặc vọt trước so với vị trí cuộn thật; ease: \"none\" mới giữ đúng quan hệ 1:1 giữa cuộn và animation."}],
    en: [{"label":"Reaching for back/elastic everywhere because \"it looks fun.\"","detail":"Both families overshoot — passing the target and settling back — which suits small feedback (buttons, badges, toasts) but makes large layout or page transitions look unprofessional, the oscillation growing more distracting as elements get bigger."},{"label":"Using the same ease-out for both an entrance and its matching exit","detail":"power2.out decelerates INTO the end value — perfect for an entrance since it reads as \"landing.\" Applying it unchanged to an exit makes the element look like it's slowly landing into being gone rather than pushed away; flip to an ease-in for exits instead."},{"label":"Leaving the default ease: \"power1.out\" (or any other non-linear ease) on a ScrollTrigger scrub animation","detail":"A scrub tween is already driven directly by scroll position — stacking a non-linear ease on top makes progress visibly lag behind or leap ahead of the real scroll position; ease: \"none\" is what keeps the 1:1 relationship between scroll and animation intact."}],
  },
  "flip-layout-transitions": {
    vi: [{"label":"Gọi Flip.getState() sau khi đã mutate DOM","detail":"Lúc đó First và Last đo ra cùng một giá trị — không có độ lệch để Invert, animation biến mất hoàn toàn dù code không báo lỗi gì."},{"label":"Quên data-flip-id (và targets) khi phần tử bị huỷ và tạo lại (unmount/mount ở React)","detail":"Thiếu id, Flip coi phần tử mới là \"vừa xuất hiện\" (onEnter); thiếu targets, nó đo Last trên phần tử gốc đã tách khỏi DOM — đằng nào cũng mất hiệu ứng dù trạng thái trước/sau đều đúng."},{"label":"Bỏ absolute: true khi nhiều phần tử flip cùng lúc","detail":"Các phần tử vẫn nằm trong luồng layout bình thường suốt animation, tween width/height của chúng đẩy nhau xê dịch ở từng frame — chính layout thrash mà FLIP sinh ra để tránh, giờ lại xảy ra ngay trong lúc Play."}],
    en: [{"label":"Calling Flip.getState() after the DOM has already been mutated","detail":"First and Last then read out the identical value — there's no delta to invert, and the animation disappears entirely without any error being thrown."},{"label":"Forgetting data-flip-id (and targets) when an element gets destroyed and recreated (an unmount/mount in React)","detail":"Without the id Flip can't pair the new element with the old one and treats it as something that just \"entered\" (onEnter); without targets it measures Last on the detached originals — either way the motion is silently lost even though the before/after states are both correct."},{"label":"Skipping absolute: true when several elements flip at once","detail":"The elements stay in normal document flow for the whole animation, and their width/height tweens nudge each other off by a fraction every frame — the exact layout thrash FLIP exists to avoid, now happening right in the middle of Play."}],
  },
  "observer-and-draggable": {
    vi: [{"label":"Gắn target của Observer vào window hoặc document cùng preventDefault: true","detail":"Việc này chặn cuộn/chạm trên TOÀN trang thay vì chỉ trong widget — người dùng không cuộn được trang nữa, một lỗi dễ bị bỏ sót nếu chỉ test bằng cách cuộn ngay trong demo."},{"label":"Nhầm đơn vị của snap giữa các type khác nhau","detail":"Với type: \"rotation\", snap tính bằng độ; với type: \"x,y\", snap tính bằng pixel (hoặc một hàm nhận toạ độ). Truyền nhầm đơn vị khiến snap hoặc không có tác dụng gì, hoặc kéo phần tử tới vị trí vô lý."},{"label":"Quên touch-action: none khi tự viết pointer handler","detail":"preventDefault() trên pointermove không ngăn được thiết bị cảm ứng \"giành\" cử chỉ để cuộn trang — kéo bị giật hoặc trang cuộn theo, dù trên desktop mượt tuyệt đối. Draggable không cần: nó tự set touch-action khi enable."}],
    en: [{"label":"Setting Observer's target to window or document alongside preventDefault: true","detail":"This blocks scrolling/touch on the ENTIRE page instead of just the widget — the user can no longer scroll the page at all, an easy mistake to miss if you only test by scrolling inside the demo itself."},{"label":"Mixing up snap's units across different type values","detail":"With type: \"rotation\", snap is measured in degrees; with type: \"x,y\", snap is measured in pixels (or a function receiving coordinates). Passing the wrong unit makes snap either do nothing or drag the element to a nonsensical position."},{"label":"Forgetting touch-action: none on hand-written pointer handlers","detail":"Calling preventDefault() on pointermove can't stop a real touch device from claiming the gesture for page scrolling — the drag stutters or the page scrolls, despite running perfectly smoothly on desktop. Draggable doesn't need the line: it sets touch-action on its element when it enables."}],
  },
  "scrolltrigger-fundamentals": {
    vi: [{"label":"Quên scroller khi animation nằm trong container cuộn riêng","detail":"ScrollTrigger mặc định lắng nghe window — thiếu scroller nghĩa là không có listener nào gắn vào đúng phần tử đang thực sự cuộn, nên animation \"đứng hình\" cho tới khi trang ngoài tình cờ cuộn."},{"label":"Không gọi ScrollTrigger.refresh() sau khi layout đổi vì lý do khác ngoài resize","detail":"Toạ độ start/end được cache tại thời điểm tạo/refresh gần nhất; ảnh lazy-load, font swap hay accordion mở ra đều không tự kích hoạt refresh, khiến trigger bắn sai vị trí cho tới lần resize cửa sổ tiếp theo."},{"label":"toggleActions chỉ viết 2-3 từ khoá thay vì đúng 4","detail":"Các vị trí còn thiếu tự rơi về \"none\" mà không có cảnh báo — hiệu ứng \"chỉ chạy một chiều, không bao giờ đảo ngược khi cuộn lên\" gần như luôn bắt nguồn từ đây."}],
    en: [{"label":"Forgetting scroller when the animation lives inside its own scrolling container","detail":"ScrollTrigger listens to window by default — without scroller, no listener is attached to the element that's actually scrolling, so the animation stays frozen until the outer page happens to scroll."},{"label":"Not calling ScrollTrigger.refresh() after a layout change other than a resize","detail":"start/end coordinates are cached at the last creation/refresh; a lazy-loaded image, a font swap, or an accordion opening none of them trigger a refresh automatically, so the trigger fires at the wrong position until the next window resize."},{"label":"Writing only 2-3 keywords in toggleActions instead of exactly 4","detail":"The missing trailing positions silently fall back to \"none\" with no warning — an effect that \"only plays once and never reverses on scroll-up\" almost always traces back to this."}],
  },
  "scrolltrigger-plus-r3f-single-loop": {
    vi: [{"label":"Đăng ký gsap.ticker.add(() => renderer.render(...)) bên cạnh <Canvas>","detail":"Đây chính là anti-pattern ở trên — tệ hơn khi frameloop=\"demand\": ticker thừa chạy ở tốc độ RAF đầy đủ bất kể có gì thay đổi hay không, vô hiệu hoá hoàn toàn lý do dùng demand mode."},{"label":"Vừa dùng <OrbitControls> vừa để ScrollTrigger ghi camera.position trong cùng một scene","detail":"Hai hệ thống cùng tưởng mình sở hữu camera; giá trị ai ghi sau trong frame đó thắng, tạo cảm giác camera \"giằng co\" mỗi khi cuộn và kéo chuột cùng lúc."},{"label":"Quên gọi invalidate() trong onUpdate khi dùng frameloop=\"demand\"","detail":"progress.value vẫn cập nhật đúng, nhưng không ai yêu cầu R3F vẽ lại — scene trông như bị đơ dù dữ liệu hoàn toàn chính xác."}],
    en: [{"label":"Registering gsap.ticker.add(() => renderer.render(...)) next to <Canvas>","detail":"This is the exact anti-pattern above — worse still under frameloop=\"demand\": the extra ticker fires at full RAF speed regardless of whether anything changed, completely defeating the point of demand mode."},{"label":"Running <OrbitControls> while ScrollTrigger also writes camera.position in the same scene","detail":"Both systems believe they own the camera; whichever writes last within a frame wins, producing a visible camera tug-of-war whenever scrolling and dragging happen together."},{"label":"Forgetting to call invalidate() inside onUpdate under frameloop=\"demand\"","detail":"progress.value still updates correctly, but nobody asked R3F to redraw — the scene looks frozen despite the underlying data being completely accurate."}],
  },
  "splittext-typography": {
    vi: [{"label":"Không gọi revert() trong cleanup","detail":"Split mới trên cùng element trả HTML gốc trước, nên không có gì lồng nhau — nhưng instance cũ vẫn sống: tween của nó animate những node đã tách khỏi DOM, và nếu bật autoSplit nó tách lại đè lên instance mới. Đặc biệt dễ gặp dưới React Strict Mode vì effect chạy hai lần lúc mount."},{"label":"Animate kết quả của autoSplit bên ngoài onSplit","detail":"Mỗi lần re-split lúc resize thay vào element mới; tween chạy từ trước vẫn giữ các element cũ đã tách khỏi DOM nên không animate được gì thấy được. Tạo tween bên trong onSplit và return nó, để SplitText revert nó và chuyển tiến độ sang lần split mới."},{"label":"Split cả đoạn văn dài theo \"chars\" vì tưởng càng chi tiết càng đẹp","detail":"Hàng nghìn <div> cho một đoạn văn dài không đổi lại được gì về thị giác so với split theo \"lines\", chỉ tốn bộ nhớ DOM và làm chậm lần split/revert tiếp theo."}],
    en: [{"label":"Not calling revert() on cleanup","detail":"A new split on the same element restores the original HTML first, so nothing nests — but the old instance lives on: its tweens animate detached nodes, and with autoSplit it re-splits over the new one. Especially easy to hit under React Strict Mode, since effects run twice on mount."},{"label":"Animating an autoSplit result outside onSplit","detail":"Each re-split on resize swaps in new elements; a tween started earlier still holds the old, detached ones and animates nothing visible. Create the tween inside onSplit and return it, so SplitText can revert it and carry its progress over to the new split."},{"label":"Splitting a long paragraph by \"chars\" assuming finer-grained always looks better","detail":"Thousands of <div>s for a long paragraph buy nothing visually over splitting by \"lines\", only burning DOM memory and slowing down the next split/revert cycle."}],
  },
  "tweens-timelines-stagger": {
    vi: [{"label":"Cộng dồn delay thủ công thay vì dùng position parameter","detail":"delay: 0, delay: 1, delay: 2 trên ba tween rời rạc trông hoạt động, nhưng chèn thêm một bước ở giữa hay đổi duration của bước đầu buộc tính lại tay toàn bộ số phía sau — position parameter (\"<\", \"-=0.2\", label) tính tương đối nên tự dồn lại đúng khi sequence bị chỉnh sửa."},{"label":"Quên stagger kéo dài tổng thời lượng sequence","detail":"T_total = duration + (n-1) · each, không phải bằng duration của một tween đơn lẻ. Bản thân timeline biết điều này — tween có stagger là MỘT tween với duration đã bao gồm cả stagger, nên bước nối tiếp mặc định vẫn chờ đúng phần tử cuối cùng xong. Cái bẫy nằm ở chỗ khác: khi bạn tự ước lượng nhịp — đặt position bằng số tuyệt đối, tính chỗ đặt label, đồng bộ với âm thanh — mà chỉ đếm duration, quên cộng (n-1) · each, mọi con số phía sau lệch cả một quãng stagger."},{"label":"Nhầm stagger: 0.1 (số = each, độ trễ CỐ ĐỊNH giữa các phần tử) với stagger: { amount: 0.1 } (tổng thời lượng CỐ ĐỊNH, độ trễ mỗi phần tử co lại khi thêm phần tử)","detail":"Thêm phần tử vào danh sách khi đang dùng each kéo dài cả sequence; thêm phần tử khi đang dùng amount giữ nguyên tổng thời lượng nhưng làm hiệu ứng \"dồn\" lại gần nhau hơn — hai hành vi trái ngược dễ gây bất ngờ nếu nhầm khoá."}],
    en: [{"label":"Stacking delay by hand instead of using a position parameter","detail":"delay: 0, delay: 1, delay: 2 on three separate tweens looks fine at first, but inserting a step in the middle or bumping the first tween's duration forces recomputing every number downstream by hand — a position parameter (\"<\", \"-=0.2\", a label) is relative, so it re-flows automatically when the sequence gets edited."},{"label":"Forgetting stagger extends the sequence's total length","detail":"T_total = duration + (n-1) · each, not just a single tween's duration. The timeline itself already knows this — a staggered tween is ONE tween whose duration includes the stagger, so the next appended step still waits for the last element to finish. The trap is elsewhere: whenever you estimate pacing by hand — absolute-number positions, computing where to drop a label, syncing to audio — and count only duration, forgetting (n-1) · each, every number downstream drifts by a full stagger."},{"label":"Mixing up stagger: 0.1 (a number = each, a FIXED per-element delay) with stagger: { amount: 0.1 } (a FIXED total duration, where each element's delay shrinks as more are added)","detail":"Adding elements while using each lengthens the whole sequence; adding elements while using amount keeps the total the same but bunches the effect closer together — two opposite behaviors that are easy to trip over if the wrong key gets used."}],
  },
  "custom-geometry-attributes": {
    vi: [{"label":"Đặt tên attribute JS và attribute GLSL lệch nhau (hoặc lệch hoa/thường)","detail":"geometry.setAttribute(\"aRandom\", ...) nhưng shader khai báo attribute float arandom; — không bao giờ là lỗi biên dịch: arandom không được cấp buffer nên đọc toàn số 0, hiệu ứng \"biến mất\" mà không có thông báo chỉ thẳng nguyên nhân."},{"label":"Quên needsUpdate = true sau khi ghi lại một Float32Array đã được render","detail":"Mảng JS đã đổi giá trị đúng, nhưng buffer trên GPU vẫn giữ dữ liệu cũ cho tới lần needsUpdate tiếp theo — dễ nhầm tưởng logic random/tính toán bị sai, trong khi vấn đề chỉ là quên báo cho Three copy lại."},{"label":"itemSize không khớp độ dài mảng","detail":"new THREE.BufferAttribute(data, 3) nhưng mảng lỡ tạo theo count thay vì count * 3 chỉ chứa một phần ba số vertex cần vẽ. Vertex trong buffer vẫn đọc đúng — không lệch pha. Nếu mảng thiếu là position trên geometry không có index, Three chỉ vẽ ít vertex hơn và một phần mesh biến mất; còn lại (geometry có index, hoặc attribute khác) mọi vertex vượt quá cuối buffer là truy cập ngoài phạm vi: tuỳ trình duyệt, lệnh vẽ bị từ chối với INVALID_OPERATION (không hiện gì) hoặc đọc ra 0 hay giá trị khác trong buffer. Kiểm tra data.length === count * itemSize trước khi gắn."}],
    en: [{"label":"The JS attribute name and the GLSL declaration drift apart (or differ in case)","detail":"geometry.setAttribute(\"aRandom\", ...) while the shader declares attribute float arandom; — this is never a compile error: the declared arandom just gets no buffer and reads as all zeros, and the effect just \"disappears\" with no message pointing at the cause."},{"label":"Forgetting needsUpdate = true after rewriting a Float32Array that has already been rendered","detail":"The JS array holds the correct new values, but the GPU-resident buffer still has stale data until the next needsUpdate — easy to mistake for a broken random/computation bug, when the real issue is simply forgetting to tell Three to re-copy it."},{"label":"itemSize mismatched against the array's length","detail":"new THREE.BufferAttribute(data, 3) where the array was sized by count instead of count * 3 holds only a third of the vertices the draw asks for. Vertices inside the buffer still read the right values — nothing shifts out of phase. If the short one is position on a non-indexed geometry, Three simply draws fewer vertices and part of the mesh goes missing; otherwise (an indexed geometry, or another attribute) every vertex past its end is an out-of-range fetch: depending on the browser, the draw fails with INVALID_OPERATION (nothing renders) or those vertices read zeros or other values from inside the buffer. Check data.length === count * itemSize before attaching."}],
  },
  "drei-shadermaterial-helper": {
    vi: [{"label":"Gọi shaderMaterial()/extend() bên trong thân component thay vì module scope","detail":"Mỗi lần component render lại tạo một class MỚI với một .key MỚI. Nếu đã gắn mẹo hot-reload key={Impl.key}, key đổi ở mọi lần render nên React unmount/remount material mỗi lần, mất sạch state — tệ hơn cả ShaderMaterial thuần. Không gắn thì dạng object extend({ ... }) không remount (loại phần tử là cái tên đã đăng ký), nhưng mỗi lần render vẫn dựng một class chẳng ai dùng."},{"label":"Dùng ref-mutation cho uniform đổi mỗi frame nhưng quên rằng đó vẫn cần thiết với class do drei sinh ra","detail":"Prop reactive không phải \"miễn phí\" — đẩy một giá trị đổi 60 lần/giây qua React state vẫn tốn một lượt re-render + applyProps mỗi lần, y hệt bất kỳ prop nào khác."},{"label":"Quên declare module augmentation rồi as any để \"cho qua\" lỗi TypeScript","detail":"Phần tử JSX tự tạo qua extend({ ... }) không tự nhiên xuất hiện trong ThreeElements — ép kiểu qua any xoá luôn mọi kiểm tra prop (gõ sai tên uniform, TypeScript sẽ không còn báo được), trong khi chỉ cần đúng vài dòng declare module là có type-safety đầy đủ."}],
    en: [{"label":"Calling shaderMaterial()/extend() inside a component body instead of module scope","detail":"Every re-render mints a NEW class with a NEW .key. With the key={Impl.key} hot-reload trick in place, the key changes on every render, so React unmounts/remounts the material each time, losing all state — worse off than plain ShaderMaterial would have been. Without it, the object form extend({ ... }) remounts nothing (the element type is the registered name), but every render still builds a class nobody uses."},{"label":"Using ref-mutation for a per-frame uniform but forgetting it's still required with a drei-generated class","detail":"A reactive prop isn't \"free\" — pushing a value that changes 60 times a second through React state still costs a re-render + an applyProps pass every single time, exactly like any other prop."},{"label":"Skipping the declare module augmentation and reaching for as any to silence TypeScript instead","detail":"A custom JSX element created via extend({ ... }) doesn't naturally show up in ThreeElements — casting through any wipes out ALL prop checking (a typo'd uniform name will no longer be caught), when a few lines of declare module buys full type-safety instead."}],
  },
  "instancedmesh-per-instance-attributes": {
    vi: [{"label":"Quên instanceMatrix.needsUpdate = true sau vòng lặp setMatrixAt chạy khi mesh đã render","detail":"Mesh compile sạch, console không báo lỗi gì, nhưng các bản sao đứng yên theo buffer cũ trên GPU (ở gốc toạ độ, nếu buffer đó vẫn là các ma trận identity ban đầu)."},{"label":"Bật material.vertexColors = true \"cho chắc\" khi chỉ dùng instanceColor","detail":"Cờ đó định nghĩa USE_COLOR ở vertex stage, khiến color_vertex đọc attribute color mà geometry không hề có — attribute không gắn trả về giá trị generic mặc định (0,0,0,1), vColor bị nhân về 0 trước khi nhân instanceColor, và cả trường instance render ĐEN thay vì màu setColorAt đã ghi. Trong three hiện tại, instanceColor một mình là đủ."},{"label":"Update toàn bộ instanceMatrix mỗi frame cho hàng nghìn instance mà không cân nhắc addUpdateRange","detail":"Kết quả vẫn đúng, nhưng mỗi frame re-upload nguyên buffer lên GPU dù phần lớn instance không đổi — dễ thành bottleneck CPU→GPU trước cả khi bản thân GPU bận."}],
    en: [{"label":"Forgetting instanceMatrix.needsUpdate = true after a setMatrixAt loop that runs once the mesh has already rendered","detail":"The mesh compiles cleanly, the console reports nothing, but the copies stay frozen where the GPU's stale buffer puts them (at the origin, if it still holds the initial identity matrices)."},{"label":"Flipping material.vertexColors = true on \"just in case\" when only instanceColor is used","detail":"That flag defines USE_COLOR in the vertex stage, making color_vertex read a color attribute the geometry doesn't have — an unbound attribute returns the generic default (0,0,0,1), vColor gets multiplied to zero before instanceColor is applied, and the whole instanced field renders BLACK instead of the colors setColorAt wrote. In current three, instanceColor alone is sufficient."},{"label":"Updating the entire instanceMatrix every frame for thousands of instances without considering addUpdateRange","detail":"The result is still correct, but every frame re-uploads the whole buffer to the GPU even when most instances didn't change — an easy CPU-to-GPU bottleneck before the GPU itself is even busy."}],
  },
  "onbeforecompile": {
    vi: [{"label":"Set shader.uniforms.uX mà quên khai báo uniform trong source GLSL","detail":"Trình biên dịch báo lỗi biến chưa khai báo — luôn thêm dòng uniform ...; cùng lúc với việc gán giá trị."},{"label":"Quên customProgramCacheKey khi code chèn phụ thuộc một biến runtime (không phải hằng số)","detail":"Vì default cache key chỉ so văn bản hàm onBeforeCompile qua .toString(), hai material dùng chung factory nhưng khác biến đóng gói có thể bị Three coi là \"cùng chương trình\" và âm thầm dùng chung."},{"label":"Gõ sai tên chunk trong replace()","detail":"Không có lỗi biên dịch nào xuất hiện — chuỗi tìm không khớp, code chèn biến mất trong im lặng, và bạn debug nhầm hướng vì tưởng logic sai chứ không nghĩ tới chuỗi tìm sai."}],
    en: [{"label":"Setting shader.uniforms.uX while forgetting to declare uniform in the GLSL source","detail":"The compiler reports an undeclared identifier — always add the uniform ...; line at the same time you assign a value."},{"label":"Forgetting customProgramCacheKey when the injected code depends on a runtime variable (not a constant)","detail":"Since the default cache key only compares the onBeforeCompile function's text via .toString(), two materials sharing a factory but differing only in a closed-over value can get treated as \"the same program\" and silently share one."},{"label":"Typo-ing a chunk name inside replace()","detail":"No compile error appears — the search string just doesn't match, your injected code vanishes silently, and you end up debugging the wrong thing, assuming broken logic instead of a wrong search string."}],
  },
  "shadermaterial-vs-rawshadermaterial": {
    vi: [{"label":"Copy shader ShaderMaterial nguyên xi sang RawShaderMaterial rồi ngạc nhiên vì lỗi biên dịch","detail":"uv, position, projectionMatrix, normalMatrix, precision — không cái nào còn tồn tại; thiếu bất kỳ khai báo nào trong số đó Raw sẽ báo lỗi ngay dòng đầu tiên dùng đến nó."},{"label":"Tưởng RawShaderMaterial \"nhanh hơn\" vì bỏ bớt code","detail":"Phần prelude Three chèn không tốn chi phí runtime đáng kể — nó chỉ là text nối vào chuỗi shader trước khi biên dịch một lần duy nhất (chương trình được cache theo cacheKey). Chọn Raw vì lý do kiểm soát/tương thích, không phải vì hiệu năng."},{"label":"Không set precision trong RawShaderMaterial vì quen với việc Three tự lo","detail":"ShaderMaterial thường có sẵn khối precision highp float;; Raw thì không — quên dòng này là LỖI BIÊN DỊCH CỨNG như nhau trên mọi nền tảng (\"No precision specified for (float)\"): fragment shader trong GLSL ES không có precision mặc định cho float. Cái bẫy desktop-chạy-mobile-hỏng thật sự nằm ở chỗ khác — mediump là 32-bit trên desktop nhưng 16-bit trên nhiều GPU mobile — đúng như bài Precision qualifier ở Track 2 đã phân tích."}],
    en: [{"label":"Copying a ShaderMaterial shader verbatim into RawShaderMaterial and being surprised by compile errors","detail":"uv, position, projectionMatrix, normalMatrix, precision — none of them exist anymore; missing any one of these declarations makes Raw fail on the very first line that touches it."},{"label":"Assuming RawShaderMaterial is \"faster\" because it skips code","detail":"The prelude Three prepends carries no meaningful runtime cost — it's just text concatenated onto the shader string before a single compile pass (programs are cached by cacheKey). Reach for Raw for control/compatibility reasons, not for performance."},{"label":"Forgetting to set precision in RawShaderMaterial out of habit from ShaderMaterial handling it automatically","detail":"Regular ShaderMaterial ships with a precision highp float; block built in; Raw doesn't — skipping it is a HARD compile error uniformly on every platform (\"No precision specified for (float)\"): a GLSL ES fragment shader has no default float precision. The real desktop-works-mobile-breaks trap lives elsewhere — mediump is 32-bit on desktop but 16-bit on many mobile GPUs — exactly as the Track 2 precision-qualifier lesson analyzed."}],
  },
  "three-injected-uniforms": {
    vi: [{"label":"Dùng 3×3 của modelViewMatrix thay vì normalMatrix khi mesh có scale không đều","detail":"Trông đúng trên mọi mesh scale đều (hình cầu, hình lập phương chưa méo), chỉ lộ sai khi ai đó scale.set(2, 1, 1) — pháp tuyến nghiêng sai hướng, lighting/rim sai mà rất khó nhận ra nếu không biết chính xác triệu chứng cần tìm."},{"label":"Truyền uniforms qua prop uniforms={...} rồi mutate .value về sau","detail":"applyProps copy từng entry vào map riêng của material ngay lúc mount — object gốc của bạn không bao giờ được gắn vào material, nên mọi lần ghi .value sau đó không tới GPU: uniform đóng băng ở giá trị đầu, lặng lẽ, không lỗi. Bind bằng ref={useSharedUniforms(uniforms)}; còn driving update qua state/props thì vừa dính bẫy copy vừa buộc React re-render cả cây con mỗi frame."},{"label":"Đặt tên custom uniform trùng một built-in (color, normal, position, modelMatrix, …)","detail":"Redefinition error khó đoán nếu không biết prelude đã chèn sẵn tên đó; quy ước tiền tố u (uTime, uColor) gần như loại bỏ hẳn rủi ro này."}],
    en: [{"label":"Using modelViewMatrix's 3×3 instead of normalMatrix on a non-uniformly scaled mesh","detail":"It looks correct on every uniformly-scaled mesh (an undistorted sphere, an undistorted cube), and only breaks once someone calls scale.set(2, 1, 1) — normals lean the wrong way, lighting/rim looks off, and it's hard to spot unless you know exactly which symptom to look for."},{"label":"Passing uniforms via the uniforms={...} prop and mutating .value later","detail":"applyProps copies each entry into the material's own map at mount — your original object is never installed on the material, so every later .value write silently misses the GPU: the uniform freezes at its initial value, with no error. Bind with ref={useSharedUniforms(uniforms)}; driving updates through state/props both hits the copy trap and forces a full-subtree React re-render every frame."},{"label":"Naming a custom uniform after a built-in (color, normal, position, modelMatrix, …)","detail":"The resulting redefinition error is hard to guess at unless you know the prelude already injected that name; the u-prefix convention (uTime, uColor) all but eliminates this risk."}],
  },
  "three-shader-chunk-system": {
    vi: [{"label":".replace() nhắm vào GLSL đã lắp ráp thay vì marker #include","detail":"Ở thời điểm onBeforeCompile, shader.vertexShader vẫn còn nguyên #include <chunk>, chưa resolve. Replace nhắm sai chuỗi không ném lỗi — chỉ âm thầm không làm gì, khó phát hiện nhất trong mọi lỗi shader."},{"label":"Ghi đè THREE.ShaderChunk toàn cục rồi quên khôi phục","detail":"Có thể rò rỉ sang bất kỳ material nào compile sau đó trên cùng trang, kể cả demo/component khác không liên quan — bug khó tái hiện vì phụ thuộc thứ tự mount các component."},{"label":"Tin tên chunk ổn định giữa các phiên bản","detail":"Nhiều bài viết cũ nhắc tới chunk output_fragment — chunk đó KHÔNG tồn tại trong three@0.185.1 cài trong repo này (xác nhận được bằng cách liệt kê thư mục ShaderChunk/); chunk ghi gl_FragColor cuối fragment ở bản này tên là opaque_fragment. Luôn đối chiếu tên chunk với node_modules/three đang cài, không copy nguyên từ tutorial không ghi rõ version."}],
    en: [{"label":".replace() targeting assembled GLSL instead of the #include marker","detail":"As covered above: at onBeforeCompile time, shader.vertexShader still contains the raw #include <chunk> line, unresolved. Replacing the wrong string throws no error — it just silently does nothing, the hardest kind of shader bug to spot."},{"label":"Overriding THREE.ShaderChunk globally and forgetting to restore it","detail":"It can leak into any material compiled afterward on the same page, including unrelated demos/components — a bug that's hard to reproduce because it depends on component MOUNT ORDER."},{"label":"Trusting chunk names to stay stable across versions","detail":"Plenty of older articles reference an output_fragment chunk — that chunk does NOT exist in the three@0.185.1 installed in this repo (verifiable by listing the ShaderChunk/ directory); the chunk that writes gl_FragColor at the end of the fragment shader in this version is named opaque_fragment. Always cross-check chunk names against the installed node_modules/three, never copy straight from a tutorial that doesn't state its version."}],
  },
  "tsl-and-webgpu-outlook": {
    vi: [{"label":"Import uniform/WebGPURenderer từ \"three\" thay vì \"three/tsl\"/\"three/webgpu\"","detail":"three/package.json cho ./tsl và ./webgpu entry riêng trong exports; core three không re-export bất cứ gì từ hai subpath kia. Lỗi báo rõ — TypeScript báo \"no exported member\", trình duyệt hay bundler báo three không có export tên uniform — không phải lỗi logic, chỉ là sai đường import."},{"label":"Quên await renderer.init() trước lần render đầu","detail":"Vì khởi tạo backend bất đồng bộ, gọi .render() ngay sau new WebGPURenderer(...) ném thẳng \"THREE.Renderer: .render() called before the backend is initialized. Use \\\"await renderer.init();\\\" before rendering.\" — thông báo lỗi đã nói rõ cách sửa, chỉ cần đọc."},{"label":"Render NodeMaterial bằng new THREE.WebGLRenderer() trơn (renderer cổ điển, không phải WebGPURenderer)","detail":"Mặc định pipeline cổ điển chỉ dựng string shader lắp bằng #include, mà NodeMaterial không có chuỗi nào — lần render đầu ném TypeError từ sâu trong bước dựng program, chẳng nhắc gì tới node. Render bằng WebGPURenderer, hoặc bật cho renderer cổ điển bằng renderer.setNodesHandler(new WebGLNodesHandler())."}],
    en: [{"label":"Importing uniform/WebGPURenderer from \"three\" instead of \"three/tsl\"/\"three/webgpu\"","detail":"three/package.json gives ./tsl and ./webgpu their own exports entries, and the core three module re-exports nothing from either. It fails loudly — TypeScript reports \"no exported member\", and the browser or bundler reports that three has no export named uniform — not a logic bug, just the wrong import path."},{"label":"Forgetting await renderer.init() before the first render","detail":"Because backend setup is async, calling .render() right after new WebGPURenderer(...) throws exactly \"THREE.Renderer: .render() called before the backend is initialized. Use \\\"await renderer.init();\\\" before rendering.\" — the error message already tells you the fix, just read it."},{"label":"Rendering a NodeMaterial with a plain new THREE.WebGLRenderer() (the classic renderer, not WebGPURenderer)","detail":"Out of the box the classic pipeline only builds string shaders assembled with #include, and a NodeMaterial has none — the first render throws a TypeError from deep inside program setup that never mentions nodes. Render it with WebGPURenderer, or opt the classic renderer in with renderer.setNodesHandler(new WebGLNodesHandler())."}],
  },
  "curl-noise-flow-fields": {
    vi: [{"label":"Dùng thẳng ∇ψ làm vận tốc, quên bước xoay 90°","detail":"Trông vẫn \"có vẻ chuyển động\" trong vài giây đầu, nhưng theo thời gian hạt luôn dồn cục về phía các cực trị của ψ — đúng hiện tượng nén mở đầu bài, dễ nhầm là lỗi tham số hoá thay vì thiếu đúng một bước hoán vị hai thành phần và đổi dấu."},{"label":"Chọn epsilon không theo tần số noise","detail":"Epsilon phải luôn là một phần nhỏ (1–2%) bước sóng của noise trong chính không gian nơi nó được cộng vào. Làm noise mịn hơn mà giữ epsilon cố định trong không gian đó thì epsilon lớn dần so với chi tiết: hai mẫu trùm qua chi tiết nhỏ và các octave mịn bị san phẳng khỏi gradient; làm noise thô hơn thì hai mẫu chênh nhau ngày càng ít, tới mức phép trừ chìm vào sai số làm tròn của float. (Demo tránh chuyện này bằng cách cộng EPS sau khi scale, trong không gian noise, nên uScale không bao giờ đổi tỉ lệ đó.)"},{"label":"Chỉ chứng minh phân kỳ triệt tiêu bằng mắt (nhìn hạt không dồn cục) mà không hiểu đó là tính chất đại số, không phải hên xui số học","detail":"Dẫn tới việc \"tối ưu\" công thức curl bằng cách xấp xỉ thô đạo hàm hỗn hợp theo hai cách khác nhau cho ∂ψ/∂ y và -∂ψ/∂ x (ví dụ epsilon khác nhau mỗi hướng) — phá vỡ đúng điều kiện làm hai đạo hàm hỗn hợp bằng nhau, phân kỳ mất luôn cả mức xấp xỉ O(ε²) mà sơ đồ sai phân đối xứng còn giữ được, dù công thức trông vẫn \"giống\" curl."}],
    en: [{"label":"Using ∇ψ directly as velocity, forgetting the 90° rotation","detail":"It still \"looks like motion\" for the first few seconds, but over time particles keep drifting toward ψ's extrema — exactly the compression artifact this lesson opens with, easy to misdiagnose as a parameter tuning issue rather than a missing component swap and sign flip."},{"label":"Picking an epsilon that doesn't scale with noise frequency","detail":"Epsilon has to stay a small fraction (1–2%) of the noise wavelength in whatever space it's added. Make the noise finer while epsilon stays fixed in that space and epsilon grows relative to the features: the two samples straddle fine detail and the finer octaves get averaged out of the gradient; make the noise coarser and the two samples differ less and less, until the subtraction sinks into float rounding. (The demo sidesteps this by adding EPS after scaling, in noise space, so uScale never changes the ratio.)"},{"label":"Confirming divergence-free only by eye (particles don't visibly clump) without understanding it's an algebraic property, not numerical luck","detail":"This leads to \"optimizing\" the curl formula by approximating the mixed partial two different ways for ∂ψ/∂ y and -∂ψ/∂ x (say, a different epsilon per direction) — breaking exactly the condition that makes the two mixed partials equal, so divergence loses even the O(ε²) accuracy the symmetric finite-difference scheme preserves, even though the formula still \"looks like\" curl."}],
  },
  "domain-warping": {
    vi: [{"label":"Dùng cùng một offset (hoặc offset = 0) cho cả hai kênh của q","detail":"Khiến q_x = q_y tại mọi điểm — warp chỉ kéo theo đúng một hướng chéo cố định thay vì xoáy tự nhiên theo mọi hướng, dù ảnh vẫn \"trông có vẻ\" đã warp."},{"label":"Đặt strength quá lớn ngay từ đầu","detail":"Quá vùng dải chảy, độ dịch đổi nhanh giữa các điểm gần nhau tới mức các nếp gấp sít hơn một pixel và aliasing thành hạt — mất hẳn cấu trúc mượt mà warping phải giữ. Tăng dần từ 0 và quan sát, đừng đoán ngay số lớn."},{"label":"Xem nhẹ hoá đơn của mỗi lớp lồng","detail":"Thêm lớp r vào một shader đã có q không phải \"cộng thêm một chút việc\" — mỗi lớp cộng thêm hai lần gọi fbm() trọn vẹn mỗi pixel (5 → 15 → 25 lần gọi noise so với fbm trơn); bật cả hai lớp trên một cảnh phủ kín màn hình mà không đo frame time trước dễ khiến GPU tầm trung tụt hẳn xuống dưới 30fps."}],
    en: [{"label":"Using the same offset (or offset = 0) for both channels of q","detail":"That makes q_x = q_y at every point — the warp only pulls in one fixed diagonal direction instead of swirling naturally in every direction, even though the image still \"looks\" warped."},{"label":"Setting strength too high right away","detail":"Past the flowing-band range, the displacement varies so fast between nearby points that the folds get tighter than a pixel and alias into grain — losing exactly the smooth structure warping is supposed to preserve. Start from 0 and increase gradually while watching, rather than guessing a large number upfront."},{"label":"Underestimating each nested layer's bill","detail":"Adding an r layer to a shader that already has q isn't \"a bit more work\" — each layer adds two full fbm() evaluations per pixel (5 → 15 → 25 noise calls vs plain fbm); enabling both layers across a screen-filling scene without measuring frame time first can easily drop a mid-range GPU below 30fps."}],
  },
  "fbm-fractal-brownian-motion": {
    vi: [{"label":"Đổi số octave mà quên chuẩn hoá lại theo tổng biên độ mới","detail":"Không chia cho 1-g^N/1-g, tăng octave từ 4 lên 8 làm ảnh sáng/tối hẳn lên dù hình dạng chi tiết không đổi nhiều — dễ nhầm tưởng octave cao hơn \"làm hỏng\" kết quả trong khi vấn đề chỉ là biên độ tổng chưa chuẩn hoá."},{"label":"Chọn quá nhiều octave vượt xa độ phân giải hiển thị","detail":"Octave có chu kỳ nhỏ hơn khoảng cách pixel không thêm chi tiết nhìn thấy được — chỉ tốn thêm phép tính mỗi frame và thêm nhiễu cao tần gây nhấp nháy khi có chuyển động nhẹ (camera rung, animate theo thời gian), một chi phí trả mà không đổi được gì về mặt thị giác."},{"label":"Nhầm turbulence và ridged FBM đảo ngược nhau","detail":"abs(noise) (turbulence) cho ĐÁY sắc nhọn tại điểm đổi dấu; 1.0 - abs(noise) (ridged) cho ĐỈNH sắc nhọn tại đúng điểm đó — copy nhầm công thức khiến địa hình \"núi\" nhìn giống hố sụt lộn ngược, hoặc ngược lại."}],
    en: [{"label":"Changing octave count without re-normalizing by the new max amplitude","detail":"Skip dividing by 1-g^N/1-g, and raising octaves from 4 to 8 brightens or darkens the whole image even though the detail shape barely changed — easy to mistake for \"more octaves broke the result\" when the real issue is an un-normalized total amplitude."},{"label":"Picking far more octaves than the display resolution can show","detail":"An octave with a period smaller than the pixel spacing adds no visible detail — it only costs extra computation every frame and adds high-frequency noise that flickers on the slightest motion (camera shake, time-based animation), a cost paid for zero visual gain."},{"label":"Mixing up turbulence and ridged FBM as opposites","detail":"abs(noise) (turbulence) produces sharp VALLEYS at zero-crossings; 1.0 - abs(noise) (ridged) produces sharp PEAKS at those exact same points — copying the wrong formula makes \"mountain\" terrain look like an inverted sinkhole, or vice versa."}],
  },
  "hash-functions-on-gpu": {
    vi: [{"label":"Seed bằng số tròn nhỏ (+1.0, +2.0) thay vì hằng số lẻ lớn","detail":"Cộng đúng 1 đơn vị đôi khi trùng với đúng bước nhảy của lưới đang hash (floor(uv * N) bước 1 đơn vị mỗi ô) — \"kênh ngẫu nhiên\" thứ hai vô tình trở thành kênh ô bên cạnh, không hề độc lập với kênh đầu."},{"label":"Nhét uTime hoặc toạ độ thế giới thẳng vào một hash dùng cho vân tĩnh","detail":"Hash vẫn xác định đúng nghĩa toán học, nhưng nếu input đổi theo thời gian hoặc theo khoảng cách camera, kết quả trông như noise \"nhấp nháy\" hay \"trôi\" — dễ nhầm là bug ngẫu nhiên trong khi thực ra chỉ là input đã đổi."},{"label":"Test hash sin trên demo nhỏ (toạ độ 0..1 hoặc vài chục đơn vị) rồi mang thẳng sang terrain toạ độ thế giới hàng nghìn đơn vị","detail":"Artefact banding của hash sin chỉ lộ rõ ở toạ độ lớn — bỏ qua bước test đúng scale thật dễ khiến lỗi chỉ xuất hiện sau khi build xong địa hình."}],
    en: [{"label":"Seeding with a small round number (+1.0, +2.0) instead of a large odd constant","detail":"Adding exactly 1 unit can line up with the very step of the grid being hashed (floor(uv * N) steps 1 unit per cell) — the \"second random channel\" accidentally becomes the neighboring cell's channel, not independent of the first at all."},{"label":"Feeding uTime or unnormalized world coordinates straight into a hash meant for static texture","detail":"The hash stays deterministic in the strict mathematical sense, but if the input changes over time or with camera distance, the result reads as noise that \"flickers\" or \"drifts\" — easy to mistake for a random bug when it's really just a changing input."},{"label":"Testing the sine hash on a small demo (coordinates 0..1 or a few dozen units) then carrying it straight into world-scale terrain spanning thousands of units","detail":"The sine hash's banding artifact only shows up at large coordinates — skipping a test at the real scale often means the bug only surfaces after the terrain is fully built."}],
  },
  "noise-in-3d-4d-time": {
    vi: [{"label":"Dùng scroll cho thứ cần tiến hoá hữu cơ (mây, lửa, nước)","detail":"Scroll dịch cả trường như một khối cứng nên mọi đốm giữ nguyên hình dạng mãi mãi — phép thử: đóng băng một đốm qua vài giây; nếu nó không đổi hình mà chỉ đổi vị trí, đó là dấu hiệu chắc chắn scroll đang bị dùng sai chỗ."},{"label":"Chọn bán kính R cho loop 4D mà không thử nghiệm","detail":"R quá nhỏ khiến cả vòng gần như đứng yên; R quá lớn khiến các bước liên tiếp nhảy sang vùng noise không tương quan, cho cảm giác nhiễu hạt/rung giật thay vì mượt — không có công thức đóng cho R \"đúng\", phải chỉnh bằng mắt theo tốc độ mong muốn."},{"label":"Để t tăng vô hạn mà không recenter, rồi bất ngờ khi hoạt ảnh giật sau vài giờ chạy","detail":"Lỗi không lộ lúc dev-test (vài phút), chỉ lộ khi chạy thật 24/7 (live-wallpaper, màn hình trưng bày) — bọc t trên CPU (elapsed % T) cho loop, hoặc dùng noise có chu kỳ theo t cho slice thuần, ngăn được vấn đề từ trước."}],
    en: [{"label":"Using scroll for something that needs organic evolution (clouds, fire, water)","detail":"Scroll translates the whole field like a rigid body, so every blob keeps its shape forever — the test: freeze one blob across a few seconds; if it never changes shape, only position, that's a sure sign scroll is misused."},{"label":"Picking a radius R for the 4D loop without testing it","detail":"Too small and the loop barely moves; too large and consecutive steps jump into uncorrelated noise, producing a grainy/jittery look instead of smooth motion — there's no closed-form \"correct\" R; it has to be tuned by eye against the desired speed."},{"label":"Letting t grow forever without recentering, then being surprised the animation stutters after hours","detail":"Easy to miss because it never shows up in dev-testing (a few minutes) and only surfaces in real deployment (a live-wallpaper or kiosk running 24/7) — wrapping t on the CPU before upload (elapsed % T) for loop mode, or a noise with a period in t for pure slice, prevents the problem instead of patching it after the fact."}],
  },
  "perlin-and-simplex-noise": {
    vi: [{"label":"Quên chuẩn hoá gradient về vector đơn vị","detail":"perlinGradient phải luôn trả về (cos θ,sin θ) — độ dài đúng 1; nếu vô tình để độ dài đổi theo hash (ví dụ nhân thêm một hệ số ngẫu nhiên khác), biên độ đổi theo từng ô — gradient ngắn nhạt về xám giữa, dài hơn 1 thì vượt dải — và mất luôn tính chất \"biên độ ổn định giữa các ô\" mà toàn bộ phép chuẩn hoá [-0.7,0.7] → [0,1] dựa vào."},{"label":"Nội suy bằng f thô thay vì fade(f)","detail":"Bỏ qua bước fade và mix thẳng bằng toạ độ cục bộ tương đương dùng đường cong bậc thấp nhất có thể (tuyến tính) — biên ô lộ rõ dưới dạng vệt kẻ ca-rô nhìn thấy được, đúng vấn đề mà cả hai đường cong fade ở trên được thiết kế để triệt tiêu."},{"label":"Copy công thức Simplex nhưng đổi mod(x, 289.0) thành một số khác \"cho gọn\"","detail":"Hằng số 289 không tuỳ ý — nó được chọn cùng hệ số permute ((x*34.0)+1.0)*x để giữ toàn bộ phép tính trong độ chính xác highp float an toàn trên phần lớn GPU di động; đổi hằng số này thường phá vỡ tính ngẫu nhiên nhìn thấy được (xuất hiện vệt lặp lại rõ rệt) mà không báo lỗi biên dịch nào."}],
    en: [{"label":"Forgetting to normalize gradients to unit vectors","detail":"perlinGradient must always return (cos θ,sin θ) — length exactly 1; letting the length accidentally vary with the hash (say, multiplying in another random factor) makes the amplitude vary by cell — short gradients wash toward mid-gray, lengths above 1 overshoot — and breaks the \"stable amplitude across cells\" property the entire [-0.7,0.7] → [0,1] normalization step depends on."},{"label":"Interpolating with raw f instead of fade(f)","detail":"Skipping the fade step and mix-ing directly with the local coordinate is equivalent to using the lowest-degree curve possible (linear) — cell boundaries show up as visible checkerboard-like seams, exactly the problem both fade curves above were designed to eliminate."},{"label":"Copying the Simplex formula but \"simplifying\" mod(x, 289.0) into a different number","detail":"The 289 constant isn't arbitrary — it's paired with the permute coefficient ((x*34.0)+1.0)*x to keep the whole computation safely inside highp float precision on most mobile GPUs; changing that constant usually breaks the visible randomness (obvious repeating streaks) with no compile error to warn you."}],
  },
  "value-and-gradient-noise": {
    vi: [{"label":"Nội suy trực tiếp bằng f (fade tuyến tính) rồi thắc mắc sao có vệt hình thoi","detail":"Quên áp smoothstep/quintic lên f trước khi mix khiến đạo hàm gián đoạn tại mọi biên ô — rõ nhất khi noise dùng làm bump map hoặc bị chiếu sáng xiên góc."},{"label":"Trong gradient noise, dùng chung f cho cả 4 góc thay vì trừ đúng offset từng góc","detail":"Phải là f, f - vec2(1,0), f - vec2(0,1), f - vec2(1,1) — sai offset phá vỡ tính chất \"bằng 0 tại điểm lưới\", noise trông lệch hẳn khỏi chuẩn."},{"label":"Quên tách i = floor(p) và f = fract(p) trước khi hash 4 góc","detail":"Hash thẳng vào p chưa tách sẽ sample sai vị trí góc, phá vỡ liên tục giữa các ô — noise hiện lưới bậc thang thay vì trường mượt."}],
    en: [{"label":"Interpolating directly with f (linear fade) and then wondering why diamond creases show up","detail":"Skipping smoothstep/quintic on f before feeding it into mix leaves the derivative discontinuous at every cell boundary — the crease is most visible when the noise is used as a bump map or lit from a grazing angle."},{"label":"In gradient noise, reusing the same f for all 4 corners instead of subtracting each corner's own offset","detail":"It must be f, f - vec2(1,0), f - vec2(0,1), f - vec2(1,1) for the four corners respectively — using the wrong offset breaks the \"zero at grid points\" property, so the noise no longer cancels where it should and looks noticeably off from standard gradient noise."},{"label":"Forgetting to split i = floor(p) and f = fract(p) before hashing the 4 corners","detail":"Hashing p directly, unsplit, samples the wrong corner positions and breaks continuity between cells — the noise shows an obvious stair-stepped grid instead of a smooth field."}],
  },
  "voronoi-and-worley": {
    vi: [{"label":"Chỉ quét ô chứa pixel, bỏ qua 8 ô lân cận","detail":"Kết quả đúng ở tâm ô nhưng sai hẳn gần biên — pixel gần mép ô thường có điểm hạt giống ở ô hàng xóm gần hơn điểm của chính ô nó, tạo ra đường ráp nối lởm chởm đúng tại mọi biên ô, dễ nhầm là lỗi hash thay vì lỗi phạm vi quét."},{"label":"Coi F_2 - F_1 như một khoảng cách có dấu thật đến biên","detail":"Nó không phải — độ rộng \"viền\" mà nó tạo ra co giãn theo khoảng cách giữa hai điểm hạt giống hai bên biên (biên giữa hai điểm gần nhau thường lại dày hơn biên giữa hai điểm xa nhau), không đồng đều như một SDF thật."},{"label":"Đặt jitter vượt quá phạm vi [0, 1] mà không mở rộng vùng quét","detail":"Toàn bộ lập luận \"3×3 là đủ\" dựa trên giả định điểm hạt giống không bao giờ rời khỏi ô chủ của nó; jitter lớn hơn 1 (hoặc cộng thêm độ lệch ngoài hash) có thể đẩy điểm sang ô cách 2 bước, nằm ngoài vùng quét — Voronoi bắt đầu bỏ sót điểm gần nhất thật sự mà không có cảnh báo lỗi nào."}],
    en: [{"label":"Scanning only the pixel's own cell, skipping the 8 neighbors","detail":"Correct near cell centers, wrong near edges — a pixel near a cell border often has a neighboring cell's feature point closer than its own, producing a jagged seam at every cell boundary that's easy to misdiagnose as a hash bug instead of a scan-range bug."},{"label":"Treating F_2 - F_1 as a real signed distance to the border","detail":"It isn't — the \"border\" width it produces stretches and shrinks with the distance between the two feature points on either side (borders between close pairs of points tend to come out wider than borders between far-apart ones), unlike a true SDF's uniform width."},{"label":"Letting jitter exceed the [0, 1] range without widening the scan","detail":"The entire \"3x3 is enough\" argument depends on feature points never leaving their owning cell; jitter above 1 (or extra offset added outside the hash) can push a point two cells away, outside the scanned neighborhood — Voronoi silently starts missing the true nearest point with no error to flag it."}],
  },
  "domain-repetition": {
    vi: [{"label":"Quên bước dịch 0.5c trước và sau mod, dùng thẳng mod(p, c)","detail":"Đặt object ở góc mỗi ô thay vì tâm — nửa object bị cắt lìa sang ô bên cạnh, hiện thành một đường ráp lộ rõ giữa các bản sao thay vì một trường liền mạch."},{"label":"Object lệch tâm ô (hoặc mỗi ô một biến thể) mà vẫn fold như object đặt giữa","detail":"Gần biên ô, bản sao của ô lân cận thật sự gần điểm truy vấn hơn bản sao \"chính chủ\" mà fold đánh giá — d(p) bị thổi phồng, march xuyên qua bề mặt thật (overstepping), lỗ hổng/răng cưa ngay đường lưới. Lời khuyên \"giữ object trong nửa ô\" vẫn nên theo với object đặt giữa, nhưng vì lý do hình học (bản sao cắt/dính nhau), không phải vì Lipschitz."},{"label":"Hash bằng q (toạ độ đã fold, đổi liên tục trong ô) thay vì cellId (chỉ số ô nguyên, tính trước khi fold)","detail":"Mỗi fragment trong cùng một ô nhận một màu/chiều cao khác nhau thay vì một giá trị đồng nhất cho cả cell — kết quả trông như nhiễu loang lổ chứ không phải biến thể \"mỗi cell một kiểu\" như mong muốn."}],
    en: [{"label":"Skipping the 0.5c shift before and after mod, calling mod(p, c) directly","detail":"Places the object at each cell's corner instead of its center — half the object splits into the neighboring cell, showing up as a visible seam between copies instead of a continuous field."},{"label":"An off-center object (or per-cell variation) folded as if it were centered","detail":"Near a cell border, the neighboring cell's copy is genuinely closer to the query point than the \"home\" copy the fold evaluates — d(p) comes back inflated, the march steps through the real surface (overstepping), holes/jagged edges right along the grid lines. The \"keep the object inside half a cell\" advice still applies to centered objects, but for geometric reasons (copies clipping/merging), not Lipschitz ones."},{"label":"Hashing with q (the folded coordinate, which changes continuously inside a cell) instead of cellId (the integer cell index, computed before folding)","detail":"Every fragment inside the same cell gets a different color/height instead of one uniform value per cell — the result reads as blotchy noise instead of the intended \"one variation per cell\" look."}],
  },
  "fog-and-atmospheric-scattering": {
    vi: [{"label":"Nhầm t march (đã tích luỹ) với giá trị SDF trả về ở bước cuối","detail":"Vòng lặp sphere tracing thường dùng chung một tên biến kiểu d cho cả khoảng-cách-an-toàn-mỗi-bước lẫn quãng-đường-tổng — nếu vô tình đưa d (gần 0 tại bề mặt) vào công thức fog thay vì t (quãng đường thật), fog gần như không bao giờ kích hoạt dù cảnh rất sâu."},{"label":"Chia cho d_y (thành phần y của hướng tia) mà không chặn khi nó gần 0","detail":"Với height fog, một tia gần như nằm ngang (nhìn thẳng ra chân trời) có d_y ≈ 0, và công thức tích phân đóng chia một đại lượng gần 0 cho một đại lượng gần 0 khác: giới hạn thật vẫn hữu hạn, nhưng kết quả float thành nhiễu (và đúng d_y = 0 thì ra 0/0, NaN trên phần cứng IEEE), biểu hiện thành các điểm ảnh chớp nháy hoặc một vệt sáng bất thường đúng ngay đường chân trời."},{"label":"Áp cùng công thức fog cho cả pixel nền trời (sky) khi tia không chạm gì","detail":"Sky đã LÀ khí quyển ở vô cực — trộn thêm một lớp fog theo công thức bề mặt lên trên nó là \"fog hoá\" hai lần, làm chân trời bẹt hẳn về một màu fog phẳng lì thay vì giữ gradient trời tự nhiên."}],
    en: [{"label":"Confusing the accumulated march t with the SDF's return value at the final step","detail":"Sphere-tracing loops often reuse the same variable name, something like d, for both the per-step safe distance and the running total distance — accidentally feeding d (near 0 at the surface) into the fog formula instead of t (the real distance traveled) means fog almost never activates, no matter how deep the scene is."},{"label":"Dividing by d_y (the ray direction's y-component) without guarding near zero","detail":"With height fog, a nearly horizontal ray (looking straight at the horizon) has d_y ≈ 0, and the closed-form integral divides a near-zero quantity by another: the limit is finite, but the float result turns noisy (exactly d_y = 0 gives 0/0, NaN on IEEE hardware), showing up as flickering pixels or a stray bright streak right along the horizon line."},{"label":"Applying the same fog formula to sky pixels when the ray hits nothing","detail":"The sky already IS the atmosphere at infinity — blending an extra layer of surface-style fog on top of it double-fogs the horizon, flattening it into a single flat fog color instead of keeping its natural sky gradient."}],
  },
  "raymarch-raster-depth-integration": {
    vi: [{"label":"Dùng thẳng linear eye depth làm t_bound, quên chia cho -rd_view.z","detail":"Đúng ở tâm màn hình, sai tăng dần ra rìa — lỗi \"chìm nhẹ\" ở biên khung hình rất dễ bị nhầm là artefact khác vì trung tâm ảnh luôn trông đúng."},{"label":"Ghi gl_FragDepth bằng world-space z hoặc view-space z thay vì NDC đã map về [0,1]","detail":"Depth buffer chỉ hiểu đúng dải [0,1] theo depthRange mặc định — ghi một số ngoài dải đó (ví dụ world z âm) khiến depth test so sánh vô nghĩa, occlusion vỡ theo cách khó truy vết vì không có lỗi biên dịch hay runtime nào báo."},{"label":"Quên rằng render target dùng để lấy depth texture phải cùng kích thước pixel với canvas thật","detail":"gl_FragCoord.xy / uResolution chỉ đúng khi uResolution khớp chính xác kích thước meshTarget — lệch kích thước (ví dụ quên nhân viewport.dpr) làm UV lấy mẫu depth bị co giãn quanh gốc của gl_FragCoord, nên occlusion chỉ đúng ở góc dưới-trái và lệch dần khi ra xa góc đó."}],
    en: [{"label":"Using linear eye depth directly as t_bound, forgetting to divide by -rd_view.z","detail":"Correct at screen center, increasingly wrong toward the edges — the resulting faint \"sinking\" near the frame border is easy to mistake for a different artifact, since the center of the image always looks right."},{"label":"Writing gl_FragDepth from world-space or view-space z instead of NDC mapped into [0,1]","detail":"The depth buffer only understands the [0,1] range under the default depthRange — writing a number outside that range (like a raw negative world z) makes the depth test comparison meaningless, and occlusion breaks in a way that's hard to trace since nothing throws a compile or runtime error."},{"label":"Forgetting the render target used for the depth texture must match the real canvas's pixel size","detail":"gl_FragCoord.xy / uResolution is only correct when uResolution exactly matches meshTarget's size — a size mismatch (like forgetting to multiply by viewport.dpr) scales the depth sample's UV about gl_FragCoord's origin, so occlusion looks right only at the bottom-left corner and drifts wrong away from it."}],
  },
  "raymarched-shadows-and-ao": {
    vi: [{"label":"Quên offset điểm gốc shadow ray theo normal","detail":"March thẳng từ p (đúng trên biên f=0) khiến bước march đầu tiên gần như luôn đọc được f ≈ 0, bị hiểu nhầm thành \"chạm vật cản ngay lập tức\" — toàn cảnh hiện ra tối om vì mọi điểm tự che chính nó (shadow acne)."},{"label":"Quên cập nhật ph = h ở cuối mỗi vòng lặp","detail":"Công thức cải tiến dựa vào khoảng cách của bước TRƯỚC (ph) để ước lượng điểm gần nhất giữa hai mẫu: bỏ dòng đó thì ph đứng nguyên ở giá trị khởi tạo khổng lồ, y → 0, d → h — hàm lặng lẽ thoái hoá về đúng bản naive k*d/t, banding quay lại mà không có lỗi nào báo. (Còn clamp(res, 0.0, 1.0) cuối hàm chỉ là bảo hiểm: res khởi tạo 1.0 và chỉ đi qua min với tỉ số không âm, tự nó không bao giờ vượt 1.)"},{"label":"Nhân AO vào cả thành phần diffuse, không chỉ ambient","detail":"AO mô phỏng ánh sáng gián tiếp bị che, không phải ánh sáng trực tiếp (đã có shadow ray lo việc đó) — nhân AO vào diffuse làm tối cả ánh sáng trực tiếp ngay cả khi đường tới nguồn sáng thông thoáng, khiến các góc tiếp xúc giữa vật và sàn tối bất thường, \"bẩn\" một cách không tự nhiên."}],
    en: [{"label":"Forgetting to offset the shadow ray's origin along the normal","detail":"Marching straight from p (which sits exactly on the f=0 boundary) means the very first step almost always reads f ≈ 0, misread as \"hit an occluder immediately\" — the whole scene turns pitch black because every point shadows itself (shadow acne)."},{"label":"Forgetting the ph = h update at the end of each loop iteration","detail":"The improved formula leans on the PREVIOUS step's distance (ph) to estimate the closest point between two samples: drop that line and ph stays at its huge initial value, y → 0, d → h — the function silently degenerates into the naive k*d/t, banding returns, and nothing errors. (The final clamp(res, 0.0, 1.0) is mere insurance by contrast: res starts at 1.0 and only ever passes through min with a non-negative ratio, so it can never exceed 1 on its own.)"},{"label":"Multiplying AO into the diffuse term too, not just ambient","detail":"AO approximates blocked indirect light, not direct light (the shadow ray already handles that) — multiplying AO into diffuse dims direct light even where its path to the light is open, making contact points between an object and the ground look unnaturally dark and \"muddy.\""}],
  },
  "raymarching-optimization": {
    vi: [{"label":"Test bounding volume nhưng vẫn march từ t=0","detail":"Bỏ qua tia trượt là đúng, nhưng nếu tia CÓ chạm box mà vẫn march từ 0 thay vì từ t_near, toàn bộ đoạn \"trước box\" vẫn bị march lãng phí — bounding volume chỉ phát huy hết tác dụng khi cả hai nửa (skip khi miss, dịch điểm bắt đầu khi hit) đều làm."},{"label":"Nới over-relaxation mà không có bước lùi khi overshoot","detail":"ω > 1 không có heuristic kiểm tra là một canh bạc: hình ảnh có thể đúng ở phần lớn cảnh rồi vỡ đột ngột (lỗ, vết lõm) ở đúng vùng hình học mỏng — loại lỗi im lặng, không log ra console, chỉ hiện khi nhìn kỹ silhouette."},{"label":"Coi số đo trên máy mình là số đo phổ quát","detail":"Một con số \"bước/pixel\" hay \"ms/frame\" đo trên GPU desktop rời không nói lên gì về GPU tích hợp hay di động (Track 12 sẽ nói kỹ tile-based rendering) — luôn gắn nhãn thiết bị đo, đừng suy rộng từ một mẫu."}],
    en: [{"label":"Testing the bounding volume but still marching from t=0","detail":"Skipping a missed ray is correct, but if a ray DOES hit the box and still marches from 0 instead of t_near, the whole \"before the box\" span is still wasted — a bounding volume only pays off fully when both halves happen: skip on miss, shift the start point on hit."},{"label":"Widening over-relaxation with no step-back on overshoot","detail":"ω > 1 with no overshoot check is a gamble: the image can look correct across most of the scene and then break suddenly (a hole, a dent) exactly at thin geometry — a silent failure, nothing logged to the console, visible only on close inspection of a silhouette."},{"label":"Treating a measurement from your own machine as universal","detail":"A \"steps/pixel\" or \"ms/frame\" figure measured on a discrete desktop GPU says nothing about an integrated or mobile GPU (Track 12 covers tile-based rendering in depth) — always label the device you measured on, don't generalize from one sample."}],
  },
  "sdf-boolean-ops-smooth-min": {
    vi: [{"label":"Để k chạm 0 trong smin","detail":"Công thức chia cho k: với k = 0, (dB - dA)/k thành ±Inf, nên clamp ép h về 0 hoặc 1 — thành min cứng, không còn góc bo — và đúng chỗ dA == dB thì ra 0/0 — NaN trên phần cứng IEEE, GLSL ES không quy định — có thể in thành điểm đen/nhiễu dọc đường nối. Luôn max(k, epsilon_nhỏ) trong code, không chỉ đặt min slider > 0 ở UI."},{"label":"Quên đảo dấu khi viết subtraction","detail":"Gõ nhầm max(d1, d2) thay vì max(d1, -d2) vẫn compile, vẫn chạy, vẫn cho hình — chỉ là hình sai (biến thành intersection). Không có lỗi biên dịch nào báo, chỉ nhìn ra khi hình không giống kỳ vọng."},{"label":"Áp subtraction/intersection trước rồi mới smin hai khối chính lại","detail":"Như ví dụ cây nấm ở trên, thứ tự phép toán đổi kết quả dù min/max từng cái tự thân có tính kết hợp — số hạng bù của smin không \"biết\" phần đã bị khoét trước đó, có thể lấp lại đúng chỗ vừa khoét."}],
    en: [{"label":"Letting k hit 0 inside smin","detail":"The formula divides by k: at k = 0, (dB - dA)/k becomes ±Inf, so clamp snaps h to 0 or 1 — a hard min with no fillet — and exactly where dA == dB it is 0/0 — NaN on IEEE hardware, left unspecified by GLSL ES — which can print black or noisy pixels along the seam. Always max(k, tiny_epsilon) in code, not just a UI slider floor above zero."},{"label":"Forgetting to flip the sign when writing subtraction","detail":"Typing max(d1, d2) instead of max(d1, -d2) still compiles, still runs, still produces a shape — it's just the wrong shape (it silently becomes an intersection). No compile error flags it; the only sign is the render not matching expectations."},{"label":"Applying subtraction/intersection before welding the two main masses with smin","detail":"As in the mushroom example above, operation order changes the result even though min/max are each individually associative — smin's correction term doesn't \"know\" about material already carved away earlier, and can partially fill the exact notch just cut."}],
  },
  "sdf-normals-from-gradient": {
    vi: [{"label":"Quên normalize sau central-diff/tetrahedron","detail":"Cả hai công thức trả về một vector có độ dài phụ thuộc ε và độ dốc cục bộ của f — không tự động là vector đơn vị. Dùng thẳng vào dot(n, lightDir) mà chưa normalize làm sai toàn bộ cường độ sáng, đặc biệt lộ rõ khi ε thay đổi (đổi ε không nên đổi độ sáng, nhưng nếu quên normalize thì có)."},{"label":"Gọi calcNormal bên trong vòng lặp raymarch thay vì chỉ tại điểm chạm","detail":"Vòng lặp sphere tracing có thể chạy 50–100 bước; tính normal ở mỗi bước nhân chi phí lên gấp 4–6 lần số bước đó một cách vô nghĩa, vì chỉ điểm chạm cuối cùng mới cần biết hướng bề mặt."},{"label":"Dùng cùng một ε cố định cho mọi tỉ lệ cảnh","detail":"Một ε tinh chỉnh tốt cho vật thể bán kính ~1 đơn vị sẽ bo tròn nặng nề chi tiết nhỏ hơn nhiều (ví dụ chữ khắc SDF) hoặc gây nhiễu số trên vật thể lớn hơn nhiều — ε nên tỉ lệ theo kích thước hình học nhỏ nhất cần giữ chi tiết trong cảnh, không phải một hằng số toàn cục."}],
    en: [{"label":"Forgetting to normalize after central-diff/tetrahedron","detail":"Both formulas return a vector whose length depends on ε and the local slope of f — not automatically a unit vector. Feeding that straight into dot(n, lightDir) without normalizing throws off the whole lighting intensity, most visibly when ε changes (changing ε shouldn't change brightness, but without normalize it does)."},{"label":"Calling calcNormal inside the raymarch loop instead of only at the hit point","detail":"A sphere-tracing loop can run 50–100 steps; computing the normal at every step multiplies cost by 4–6x that step count for no reason, since only the final hit point ever needs a surface direction."},{"label":"Reusing one fixed ε across every scene scale","detail":"An ε tuned well for an object with a ~1-unit radius will heavily round out much smaller details (engraved SDF text, for instance) or produce float noise on much larger objects — ε should scale with the smallest geometric feature that needs to stay crisp, not stay a single global constant."}],
  },
  "sdf-primitives": {
    vi: [{"label":"Quên số hạng min(max(q.x,q.y,q.z), 0) trong box SDF (hoặc sai dấu)","detail":"Thiếu nó, d luôn không âm — điểm bên TRONG hộp báo khoảng cách 0 hoặc dương thay vì âm dần về tâm, phá vỡ mọi kỹ thuật dựa vào dấu của d."},{"label":"Xoay điểm truy vấn theo đúng góc mong muốn thay vì góc NGƯỢC","detail":"Đang biến đổi p để mô phỏng biến đổi hình, mọi phép biến đổi phải dùng nghịch đảo — nhầm +angleY thay vì -angleY làm hình quay ngược chiều slider."},{"label":"Scale điểm truy vấn không đều mà không nhận ra hậu quả","detail":"Chiều nào an toàn, chiều nào nguy hiểm phụ thuộc hệ số: p / vec3(2.0, 1.0, 1.0) (phóng to hình theo x) chỉ làm field ước lượng THIẾU — march chậm đi chứ không thủng, và chính là bound SDF hợp lệ ở mục \"Exact vs bound\" phía trên. Ngược lại p * vec3(2.0, 1.0, 1.0) (nén hình còn một nửa theo x) làm gradient của field vượt quá 1: quả cầu an toàn bán kính f(p) nói dối theo trục bị nén, tia xuyên qua phần hình mỏng, rõ nhất ở góc nhìn lướt cạnh — đúng cơ chế thủng silhouette đã học ở bài trước, chỉ khác nguyên nhân là SDF sai thay vì thiếu bước march. Hệ số bù an toàn: nhân kết quả với min của các hệ số scale."}],
    en: [{"label":"Dropping the min(max(q.x,q.y,q.z), 0) term in the box SDF (or flipping its sign)","detail":"Without it, d is never negative — points INSIDE the box report 0 or positive instead of increasingly negative toward the center, breaking anything relying on d's sign."},{"label":"Rotating the query point by the intended angle instead of its INVERSE","detail":"Since you're transforming p to simulate transforming the shape, every transform needs inverting — +angleY instead of -angleY makes the shape spin backward relative to the slider."},{"label":"Non-uniformly scaling the query point without accounting for the consequences","detail":"Which direction is safe depends on the factors: p / vec3(2.0, 1.0, 1.0) (stretching the shape along x) only makes the field UNDERestimate — the march slows down but never tunnels; it is exactly the valid bound SDF from \"Exact vs bound\" above. p * vec3(2.0, 1.0, 1.0) (squeezing the shape to half along x) is the dangerous one — the field's gradient exceeds 1, the safety sphere of radius f(p) lies along the squeezed axis, and the ray tunnels through the thinned part, especially at grazing angles — the exact silhouette-hole mechanism from the previous lesson, now caused by a wrong SDF instead of an insufficient step budget. The safe correction: multiply the result by the minimum of the scale factors."}],
  },
  "sphere-tracing-principle": {
    vi: [{"label":"Quên chuẩn hoá rd","detail":"Công thức t_i+1 = t_i + f(p_i) giả định rd là vector đơn vị — nếu không, t không còn đo khoảng cách thật dọc tia và mỗi bước đi |rd| · f(p) trong không gian. Hướng tia không đổi nên phối cảnh vẫn đúng; nhưng bước march vượt quá khoảng cách an toàn, nặng nhất ở rìa màn hình nơi |rd| lớn nhất, làm thủng các bề mặt mỏng hoặc bị tia lướt cạnh, và mọi thứ đọc t như một khoảng cách (fog, depth, maxDist) đều bị scale sai."},{"label":"Dùng epsilon tuyệt đối không theo tỉ lệ cảnh","detail":"epsilon = 0.001 hợp lý cho mặt cầu bán kính 1, nhưng vô nghĩa nếu cảnh scale lên bán kính 100 (quá nhỏ, gây banding và tốn hiệu năng) hoặc xuống 0.01 (quá lớn, gây lồi lõm rõ rệt)."},{"label":"Không giới hạn maxDist, chỉ dựa maxSteps","detail":"Thiếu t > maxDist, mọi tia bắn ra bầu trời vẫn buộc chạy hết maxSteps mới dừng — lãng phí đúng số bước tối đa cho phần lớn pixel khung hình, vì bầu trời thường chiếm diện tích màn hình nhiều hơn vật thể."}],
    en: [{"label":"Forgetting to normalize rd","detail":"The formula t_i+1 = t_i + f(p_i) assumes rd is a unit vector — otherwise t no longer measures real distance along the ray and each step moves |rd| · f(p) in space. The direction is unchanged, so perspective still looks right; but steps overshoot the safe distance, worst toward the screen edges where |rd| is largest, punching holes through thin or grazed surfaces, and anything that reads t as a distance (fog, depth, maxDist) comes out scaled."},{"label":"Using an absolute epsilon that ignores scene scale","detail":"epsilon = 0.001 is reasonable for a radius-1 sphere, but meaningless if the scene is scaled up to radius 100 (too tiny, causing banding and wasted performance) or down to radius 0.01 (too large, causing obvious lumpiness)."},{"label":"Skipping maxDist and relying on maxSteps alone","detail":"Without a t > maxDist check, every ray shot into open sky (hitting nothing) is still forced to run the full maxSteps before the loop ends — wasting exactly the maximum step count on most of the frame's pixels, since sky typically covers far more screen area than any object."}],
  },
  "volumetric-rendering-basics": {
    vi: [{"label":"Nhầm volumetric march với surface raymarch","detail":"Dừng ngay khi mật độ đầu tiên lớn hơn 0 (giống hệt sphere tracing dừng khi f < ε) thay vì march hết vùng bao rồi TÍCH LUỸ — cắt cụt đám mây thành một lớp vỏ mỏng dính ở rìa gần camera nhất, mất hẳn cảm giác khối đặc dần vào trong."},{"label":"Cộng L_e SAU KHI đã cập nhật T của chính bước đó","detail":"(đảo ngược thứ tự hai dòng cập nhật ở phần 2) — mọi lớp mây tự chặn một phần ánh sáng của chính nó trước khi nó kịp góp vào C, nên các bước dày ra quá tối, tăng mật độ còn tệ hơn (cộng trước thì sai theo chiều ngược lại, hơi quá sáng)."},{"label":"Đặt ngưỡng early-exit quá cao","detail":"(ví dụ T < 0.5) tưởng là tối ưu — dừng march khi vẫn còn 50% ánh sáng có thể xuyên qua, cắt cụt phần thể tích chưa march tới giữa chừng, méo hẳn silhouette phía xa của mây."}],
    en: [{"label":"Confusing a volumetric march with surface raymarching","detail":"Stopping the instant density is first greater than 0 (exactly like sphere tracing stopping at f < ε) instead of marching the whole bounding region and ACCUMULATING — this shears the cloud down to a thin shell stuck at the nearest edge to the camera, losing any sense of a volume that thickens toward its interior."},{"label":"Adding L_e AFTER updating that same step's T","detail":"(swapping the two update lines from the accumulation section) — every layer of cloud blocks part of its own emitted light before it can contribute to C, so thick steps come out too dark, and raising the density makes it worse (emitting first errs the other way, a little too bright)."},{"label":"Setting the early-exit threshold too high","detail":"(say, T < 0.5) thinking it's an optimization — stopping the march while 50% of the light could still pass through cuts off unmarched volume midway, visibly distorting the cloud's silhouette on its far side."}],
  },
  "boids-flocking-on-gpu": {
    vi: [{"label":"Trọng số separation quá thấp so với cohesion","detail":"Cohesion luôn kéo boid vào tâm khối và chỉ separation đẩy ra — alignment chỉ làm các boid cùng hướng, không kéo lại gần hay đẩy ra xa — nên cohesion gần như luôn \"thắng\" nếu separation không được nhân trọng số đủ mạnh ở cự ly gần — kết quả là cả đàn co lại thành một khối chồng lấn thay vì bay sát nhau có khoảng cách. Luôn kiểm tra: ở khoảng cách rất nhỏ, lực đẩy separation phải thắng rõ lực kéo cohesion (demo này normalize tổng separation, nên độ lớn của nó chỉ do trọng số quyết định)."},{"label":"So sánh UV bằng dấu == để bỏ qua chính mình thay vì so khoảng cách","detail":"gl_FragCoord.xy / resolution.xy và (vec2(x, y) + 0.5) / resolution là hai phép tính độc lập — sai số làm tròn dấu phẩy động đôi khi khiến otherUv == uv sai dù cùng một texel, khiến boid tự đẩy chính mình (self-repulsion), gây rung giật khó truy. Luôn dùng dist < epsilon để bỏ qua chính mình."},{"label":"Quên khai báo chính biến làm dependency của chính nó trong setVariableDependencies","detail":"textureVelocity cần đọc chính textureVelocity frame trước để cộng dồn lực lên vận tốc hiện có — bỏ sót dependency này nghĩa là init() không bao giờ chèn dòng uniform sampler2D textureVelocity; vào shader — shader tham chiếu tên chưa khai báo và LỖI BIÊN DỊCH ngay (undeclared identifier), đúng ca lỗi bài GPUComputationRenderer đã tập. (Sample một texture chưa bind trong WebGL trả về (0,0,0,1), không phải giá trị bất định.)"}],
    en: [{"label":"Setting the separation weight too low relative to cohesion","detail":"Cohesion keeps pulling every boid toward the group's center and only separation pushes back — alignment matches headings but doesn't pull boids together or push them apart — so cohesion routinely \"wins\" unless separation is weighted strongly enough at close range — the result is the whole flock collapsing into an overlapping clump instead of flying tightly together with real spacing. Always check that at very small distances separation's push clearly beats cohesion's pull (this demo normalizes the separation sum, so its size is set by its weight alone)."},{"label":"Comparing UV coordinates with == to skip self, instead of comparing distance","detail":"gl_FragCoord.xy / resolution.xy and (vec2(x, y) + 0.5) / resolution are two independently computed values — floating-point rounding can occasionally make otherUv == uv false even for the exact same texel, which makes a boid apply separation against itself, producing hard-to-trace jitter. Always use dist < epsilon to skip self instead."},{"label":"Forgetting to list a variable as its own dependency in setVariableDependencies","detail":"textureVelocity needs to read its own previous frame to accumulate forces onto the existing velocity — omitting that self-dependency means init() never prepends the uniform sampler2D textureVelocity; line — the shader references an undeclared identifier and FAILS TO COMPILE immediately, the exact error the GPUComputationRenderer lesson drilled. (Sampling an unbound texture in WebGL returns (0,0,0,1), not undefined values.)"}],
  },
  "cloth-simulation-basics": {
    vi: [{"label":"Tự khai báo lại uniform của dependency","detail":"init() prepend sẵn uniform sampler2D <tên>; cho mọi dependency, kể cả self-dependency. Viết thêm dòng đó trong shader là lỗi trùng định nghĩa — demo im lặng ra canvas trắng chứ không báo gì rõ ràng."},{"label":"Đưa kết quả Jacobi relax pass cuối cùng nhầm chỗ","detail":"Nếu texture \"hiện tại\" dùng cho frame sau vẫn là candidate CHƯA relax, vận tốc ngầm của Verlet ở frame kế bị tính sai — vải trông như có thêm một lực bí ẩn không nguồn gốc."},{"label":"Gió không chiếu theo pháp tuyến","detail":"Cộng thẳng vector gió hằng vào gia tốc mà không nhân ( n · w) khiến cả tấm vải chỉ nghiêng đi rồi treo im, như thể trọng lực bị nghiêng — dấu hiệu nhận biết là vải \"treo xiên\" thay vì \"gợn\"."}],
    en: [{"label":"Redeclaring a dependency's uniform","detail":"init() already prepends uniform sampler2D <name>; for every dependency, the self-dependency included. Writing that line in the shader too is a duplicate-definition error — the demo goes blank rather than reporting anything obvious."},{"label":"Feeding the wrong texture back as \"current\" after relaxation","detail":"If next frame's \"current\" texture is still the un-relaxed candidate, Verlet's implicit velocity next frame gets computed against the wrong reference — the cloth appears to gain a mysterious extra force from nowhere."},{"label":"Wind not projected onto the normal","detail":"Adding a constant wind vector straight into acceleration without multiplying by ( n · w) makes the whole sheet lean over and hang still, as if gravity were tilted — the giveaway is cloth that \"hangs sideways\" instead of \"ripples\"."}],
  },
  "flow-field-particles": {
    vi: [{"label":"Cộng field trực tiếp vào vận tốc mà quên damping tương xứng","detail":"vel += field * strength * dt không có gì sai về mặt cú pháp, nhưng field liên tục bơm năng lượng vào hệ mỗi frame — sau vài chục giây vận tốc tăng dần không giới hạn, particle bay xuyên khỏi khung hình. Steering (mix) tránh được lỗi này vì nó có \"trần\" tự nhiên: vận tốc không bao giờ vượt quá strength."},{"label":"Quên normalize() hướng field trước khi nhân với strength","detail":"Độ lớn thô của vector curl không đều khắp không gian — vùng noise \"phẳng\" cho vector gần như bằng 0, vùng noise dốc cho vector lớn hơn hẳn. Không chuẩn hoá khiến strength không còn kiểm soát tốc độ nhất quán: một số particle gần như đứng yên, số khác lao vút qua màn hình, dù cùng một giá trị strength."},{"label":"Gieo tuổi ban đầu bằng 0 cho toàn bộ particle thay vì ngẫu nhiên trong [0, lifetime)","detail":"Hệ vẫn chạy đúng về mặt logic, nhưng mọi particle tái sinh cùng lúc mỗi lifetime giây — một cú nháy toàn đám mây rất dễ nhận ra, phá vỡ cảm giác \"dòng chảy liên tục\" mà cả bài học hướng tới."}],
    en: [{"label":"Adding the field directly to velocity without matching damping","detail":"vel += field * strength * dt isn't syntactically wrong, but the field keeps pumping energy into the system every frame — after a few dozen seconds velocity grows unbounded and particles fly clean off screen. Steering (mix) avoids this because it has a natural \"ceiling\": velocity never exceeds strength."},{"label":"Forgetting to normalize() the field direction before scaling by strength","detail":"The raw curl vector's magnitude isn't uniform across space — \"flat\" noise regions produce near-zero vectors, steep regions produce much larger ones. Skipping normalization means strength no longer controls speed consistently: some particles nearly stand still while others rocket across the screen, all at the same strength value."},{"label":"Seeding every particle's starting age at 0 instead of randomly in [0, lifetime)","detail":"The system still runs correctly in a logical sense, but every particle respawns at the exact same moment every lifetime seconds — a very noticeable whole-cloud blink that breaks the \"continuous flow\" feeling the lesson is built around."}],
  },
  "fluid-simulation-intro": {
    vi: [{"label":"Đổ lỗi cho \"GPU chậm\" khi thật ra thuật toán là O(N^2)","detail":"Một SPH brute-force 5000 hạt tụt khung hình không phải vì GPU yếu — vì thiếu cấu trúc không gian (uniform grid/spatial hash) để giới hạn tìm hàng xôm về vùng lân cận thật sự, không phải toàn bộ tập hạt."},{"label":"Giảm số lần lặp Jacobi để \"tiết kiệm\" mà không nhận ra phân kỳ chưa thực sự về 0","detail":"Kết quả là dòng chảy trông vuông vức, xoáy yếu hoặc biến mất hẳn — không phải lỗi công thức, chỉ đơn giản là nghiệm áp suất chưa hội tụ đủ; đúng hiện tượng slider số vòng lặp trong demo minh hoạ."},{"label":"Nhầm \"ổn định vô điều kiện\" của semi-Lagrangian advection với \"chính xác.\"","detail":"Đặt dissipation về giá trị không làm mất màu mực gì cả nhưng trường vẫn mờ dần theo thời gian — đó là khuếch tán số học vốn có của phép nội suy mỗi bước advect, không phải bug ở dissipation."}],
    en: [{"label":"Blaming \"the GPU is slow\" when the algorithm is actually O(N^2)","detail":"A brute-force SPH with 5000 particles tanking framerate isn't a weak GPU — it's the missing spatial structure (uniform grid/spatial hash) that would limit neighbor search to a real local neighborhood instead of the entire particle set."},{"label":"Cutting Jacobi iterations to \"save time\" without realizing divergence hasn't actually reached zero","detail":"The result looks blocky, weakly swirling, or has no recirculation at all — not a formula bug, just a pressure solution that hasn't converged enough; exactly what the demo's iteration slider demonstrates."},{"label":"Confusing semi-Lagrangian advection's \"unconditional stability\" with \"accuracy.\"","detail":"Setting dissipation to zero doesn't remove any dye color directly, yet the field still visibly fades over time — that's the inherent numerical diffusion of interpolating at every advect step, not a dissipation bug."}],
  },
  "gpucomputationrenderer": {
    vi: [{"label":"Quên gọi setVariableDependencies trước init()","detail":"Không có dependency, không có uniform sampler2D nào được chèn — shader tham chiếu texturePosition/textureVelocity sẽ không biên dịch được (identifier chưa khai báo), hoặc nếu bạn không tham chiếu gì thì trạng thái đơn giản là đứng yên mãi mãi vì chẳng đọc được frame trước."},{"label":"Tự khai báo lại uniform sampler2D texturePosition","detail":"cho một biến đã liệt kê chính nó trong dependency. init() đã tự chèn đúng dòng đó rồi — khai báo tay thêm một lần nữa là lỗi biên dịch \"redefinition\"."},{"label":"Coi FloatType mặc định là chạy được trên mọi thiết bị","detail":"Không có fallback tự động trong bản three hiện tại (đã đọc source xác nhận) — thiết bị thiếu EXT_color_buffer_float không ném lỗi ở init() hay compute() — three chỉ in một cảnh báo một lần — và trạng thái không bao giờ rời khỏi 0 (đen ngòm)."}],
    en: [{"label":"Forgetting to call setVariableDependencies before init()","detail":"With no dependency, no sampler2D uniform gets prepended — a shader referencing texturePosition/textureVelocity fails to compile (undeclared identifier), or if you never reference them at all, state simply sits frozen forever since it can never read the previous frame."},{"label":"Redeclaring uniform sampler2D texturePosition; by hand","detail":"for a variable that already lists itself as a dependency. init() already prepended that exact line — a hand-written second declaration is a \"redefinition\" compile error."},{"label":"Assuming the default FloatType just works everywhere","detail":"There's no automatic fallback in the current three version (verified by reading the source) — a device missing EXT_color_buffer_float doesn't throw at init() or compute() — three only logs a one-time warning — and the state never leaves zero (solid black)."}],
  },
  "instancing-a-million-objects": {
    vi: [{"label":"Đọc vị trí ngược về CPU bằng readPixels để điều khiển thứ gì đó phía CPU","detail":"Vẫn chạy, nhưng buộc CPU chờ GPU mỗi frame — đúng chỗ nghẽn mà cả pipeline này sinh ra để tránh. Giữ trọn compute → render trên GPU, và tìm đường khác cho thứ phía CPU cần."},{"label":"Xoay transformed (vị trí) theo basis vận tốc mà quên xoay pháp tuyến theo đúng basis đó","detail":"Vị trí đỉnh đúng nhưng ánh sáng tính từ pháp tuyến cũ (chưa xoay) — hình vẫn ở đúng chỗ, hướng đúng chiều bay, nhưng phần sáng/tối trên mỗi mặt không khớp với hướng nó đang chỉ, nhìn \"sai sai\" dù không lỗi rõ ràng."},{"label":"Không tắt frustumCulled trên InstancedMesh có vị trí đến từ texture","detail":"Three tính frustum culling dựa trên bounding sphere của geometry gốc (thường ở gần origin) — vì vị trí thật của từng instance nằm ngoài đó, xoay camera một chút có thể khiến Three quyết định \"cả object nằm ngoài khung hình\" và bỏ qua draw call dù instance vẫn đang hiển thị đúng vị trí thực."}],
    en: [{"label":"Reading positions back with readPixels to drive something on the CPU","detail":"It works, but it forces the CPU to wait for the GPU every frame — the stall this whole pipeline exists to avoid. Keep compute → render on the GPU and find another route for whatever the CPU side needs."},{"label":"Rotating transformed (position) by the velocity basis but forgetting to rotate the normal the same way","detail":"Vertex positions land correctly, instances point the right direction, but lighting is computed from the old, un-rotated normal — the shape sits in the right place facing the right way, yet its shading looks subtly wrong on every face."},{"label":"Leaving frustumCulled on for an InstancedMesh whose positions come from a texture","detail":"Three computes frustum culling from the base geometry's bounding sphere (usually near the origin) — since instances' real positions live far outside that, a small camera turn can make Three decide the \"whole object\" is off-screen and skip the draw call, even though instances are still visibly rendering at their real positions."}],
  },
  "pingpong-fbo-state-textures": {
    vi: [{"label":"Bind cùng một render target vừa làm input sampler vừa làm output framebuffer trong cùng draw call","detail":"— ví dụ quên đảo read/write sau swap, hoặc gán nhầm uniform texture. Trong WebGL, draw call đó bị bỏ qua và trình duyệt in cảnh báo feedback loop ra console — triệu chứng là trạng thái ĐỨNG YÊN (frame ghi bị nuốt), nên hãy mở console trước khi đoán mò về shader."},{"label":"Không clamp uDelta sau một frame chậm hoặc tab bị ẩn rồi mở lại","detail":"— delta có thể nhảy vọt tới vài trăm mili-giây. Particle \"nhảy\" xuyên qua biên va chạm hoặc vận tốc nổ tung, vì tích phân Euler với delta lớn không còn ổn định số học."},{"label":"Quên renderer.setRenderTarget(null) sau compute pass","detail":"Three.js tiếp tục render mọi thứ sau đó — kể cả scene chính — vào render target cũ; màn hình đứng yên hoặc đen, trong khi console không báo lỗi nào vì về mặt kỹ thuật, mọi lệnh render vẫn \"thành công\"."}],
    en: [{"label":"Binding the same render target as both the input sampler and the output framebuffer in one draw call","detail":"— say, forgetting to flip read/write after a swap, or wiring the wrong texture to a uniform. In WebGL that draw call is skipped and the browser logs a feedback-loop warning to the console — the symptom is a FROZEN state (the write frame gets swallowed), so open the console before second-guessing your shader."},{"label":"Not clamping uDelta after a slow frame or a hidden-then-reopened tab","detail":"— delta can spike to hundreds of milliseconds. Particles tunnel straight through boundary bounds or their velocities explode, because Euler integration with a large delta is no longer numerically stable."},{"label":"Forgetting renderer.setRenderTarget(null) after the compute pass","detail":"Three.js keeps rendering everything after that — including the main scene — into the stale render target; the screen sits frozen or black, while the console reports nothing wrong, because technically every render call still \"succeeded.\""}],
  },
  "transform-feedback": {
    vi: [{"label":"Gọi transformFeedbackVaryings SAU gl.linkProgram","detail":"Chương trình vẫn link được, nhưng layout output đã cố định trước khi lệnh này chạy nên nó không ghi output nào — beginTransformFeedback báo INVALID_OPERATION và không có gì được capture. (Lời gọi muộn chỉ có hiệu lực ở lần link kế tiếp.)"},{"label":"Dùng cùng một buffer vừa làm input VAO vừa làm đích bindBufferBase","detail":"trong một draw call (quên double-buffer) — WebGL từ chối lệnh vẽ với INVALID_OPERATION, vì nếu không, hàng nghìn invocation vertex shader chạy song song sẽ đọc/ghi chồng lên cùng vùng nhớ."},{"label":"Quên gl.disable(RASTERIZER_DISCARD) sau update pass","detail":"Mọi draw call render TIẾP THEO — kể cả không liên quan gì tới simulation — im lặng không vẽ gì lên màn hình, vì trạng thái discard vẫn còn bật toàn cục cho tới khi tắt tay."}],
    en: [{"label":"Calling transformFeedbackVaryings AFTER gl.linkProgram","detail":"The program still links, but its output layout was frozen before this call ran, so it records no outputs — beginTransformFeedback then fails with INVALID_OPERATION and nothing gets captured. (The late call only takes effect at the next link.)"},{"label":"Using the same buffer as both the VAO's input source and the bindBufferBase destination","detail":"in one draw call (forgetting to double-buffer) — WebGL rejects the draw with INVALID_OPERATION, because thousands of parallel vertex shader invocations reading and writing the same memory would otherwise race."},{"label":"Forgetting gl.disable(RASTERIZER_DISCARD) after the update pass","detail":"Every following render draw call — even ones unrelated to the simulation — silently draws nothing at all, because the discard state is still globally on until it's turned off by hand."}],
  },
  "why-particles-live-on-gpu": {
    vi: [{"label":"Đổ lỗi cho \"băng thông\" khi particle system giật","detail":"Số liệu thực tế (như tính ở trên) gần như luôn cho thấy JS loop cộng GC cộng overhead gọi bufferSubData mới là thủ phạm, không phải dung lượng dữ liệu truyền — nghi ngờ sai chỗ khiến bạn tối ưu sai thứ (ví dụ nén dữ liệu xuống half-float) trong khi vấn đề thật nằm ở allocation trong vòng lặp."},{"label":"Tạo object tạm trong vòng lặp cập nhật","detail":"— new THREE.Vector3(), spread một mảng, tạo closure mới mỗi lần lặp. Tưởng vô hại vì object nhỏ, nhưng đó chính là nguồn gây GC pause bất định, biểu hiện như một frame ngẫu nhiên bị giật dù trung bình vẫn mượt, cực khó tái hiện khi profiling."},{"label":"Quên needsUpdate = true sau khi ghi trực tiếp vào mảng của BufferAttribute","detail":"Particle \"cập nhật\" đúng trong RAM, nhưng hình vẽ trên màn hình đứng yên, vì Three.js không biết dữ liệu đã đổi nên không bao giờ gọi bufferSubData — không có lỗi console nào báo hiệu việc này."}],
    en: [{"label":"Blaming \"bandwidth\" when a particle system stutters","detail":"The real numbers (as computed above) almost always show the JS loop plus GC plus bufferSubData call overhead as the actual culprit, not the volume of data transferred — suspecting the wrong cause leads you to optimize the wrong thing (say, compressing data to half-float) while the real problem is allocation inside the loop."},{"label":"Allocating temporary objects inside the update loop","detail":"— a new THREE.Vector3(), spreading an array, creating a fresh closure every iteration. It feels harmless because the object is small, but that's exactly the source of unpredictable GC pauses, showing up as a random stutter frame even though the average stays smooth — and it's brutally hard to reproduce while profiling."},{"label":"Forgetting needsUpdate = true after writing directly into a BufferAttribute's array","detail":"The particles genuinely update in RAM, but the drawing on screen sits frozen, because Three.js has no way of knowing the data changed and so never calls bufferSubData — no console error ever signals this."}],
  },
  "bloom-done-right": {
    vi: [{"label":"Threshold gần 0 rồi \"sửa\" bằng cách hạ strength","detail":"Hạ strength chỉ làm quầng sáng yếu đi ĐỀU trên mọi vật — bloom vẫn không phân biệt được vật phát sáng thật với vật chỉ sáng màu, vì nguyên nhân gốc (threshold không loại được gì) chưa được giải quyết."},{"label":"Test bloom trên cảnh nền sáng rồi mang config sang cảnh tối","detail":"Cùng một strength/threshold trông \"vừa mắt\" trên nền sáng có thể bị ngợp hoàn toàn trên nền tối, vì đóng góp additive của bloom nổi bật hẳn lên khi nền xung quanh không còn cạnh tranh độ sáng."},{"label":"Tin rằng tonemapping kẹp material ngay trong RenderPass — rồi rắc toneMapped={false} khắp nơi để \"cứu HDR\"","detail":"Renderer bỏ qua tonemapping của material khi render vào render target, nên buffer composer luôn linear HDR và cờ đó là no-op bên trong chuỗi; nó chỉ đổi hành vi khi render thẳng ra màn hình (không composer) — nơi chẳng có bloom nào để cứu. Bẫy thật nằm ngược lại: quên OutputPass cuối chuỗi thì ảnh linear chưa tonemap/chưa sRGB đổ thẳng ra canvas."}],
    en: [{"label":"Threshold near 0, then \"fixing\" it by lowering strength","detail":"Lowering strength only weakens the glow EVENLY across every object — bloom still can't tell a genuine emitter from a merely-bright-colored object, since the root cause (threshold catching everything) was never actually addressed."},{"label":"Testing bloom against a bright background scene, then carrying the config into a dark one","detail":"The same strength/threshold that looks \"just right\" against a bright background can completely overwhelm a dark one, since bloom's additive contribution stands out far more sharply once the surrounding scene stops competing for brightness."},{"label":"Believing tone mapping clamps materials inside RenderPass — then sprinkling toneMapped={false} everywhere to \"rescue HDR\"","detail":"The renderer skips material tone mapping when rendering into a render target, so composer buffers are always linear HDR and that flag is a no-op inside the chain; it only changes behavior when rendering straight to the screen (no composer) — where there is no bloom to rescue anyway. The real trap points the other way: forget the chain-ending OutputPass and raw un-tonemapped, un-encoded linear output lands on the canvas."}],
  },
  "color-grading-lut-tonemapping": {
    vi: [{"label":"Grade trước khi tone map (LUT pass trước OutputPass)","detail":"LUT 16^3 chỉ phủ [0,1]; feed giá trị linear HDR (có thể 40.0) khiến các vùng sáng bị kẹp lên mặt ngoài của LUT — vùng trắng chói rơi đúng vào cùng một ô góc — bất kể chênh lệch — hiệu ứng teal-orange chưa kịp chạm highlight thật, vì \"highlight\" theo nghĩa display-referred chưa tồn tại ở bước đó."},{"label":"Quên inset nửa-texel khi sample LUT","detail":"Sample thẳng rgb chưa qua rgb · (1-frac 1N) + frac 12N khiến dải màu trải lên mép ngoài của texture thay vì tâm các ô góc: đen, trắng và đúng xám giữa vẫn ra đúng, nhưng mọi giá trị ở giữa bị đẩy xa khỏi xám giữa tới 1/2N (≈0.03 với N = 16), còn giá trị nằm trong nửa ô sát hai đầu bị ép thành đen hoặc trắng tuyệt đối — một sai lệch tương phản nhỏ nhưng có hệ thống."},{"label":"Coi neutral LUT là trang trí, không phải test","detail":"Một lỗi đảo trục (R và B sample nhầm chỗ) hay sai công thức inset vẫn có thể cho ảnh \"gần đúng\" khi dùng LUT có màu — chỉ neutral LUT bắt lỗi này ngay, vì đó là trường hợp duy nhất bắt buộc tái tạo pixel gốc y hệt."}],
    en: [{"label":"Grading before tone mapping (LUT pass before OutputPass)","detail":"A 16^3 LUT covers only [0,1]; feed it linear HDR values (possibly 40.0) and highlights clamp onto the LUT's outer faces — the white-hot ones into the very same corner cell — regardless of how different they are — the teal-orange shift never reaches a real highlight, because \"highlight\" in the display-referred sense doesn't exist yet at that stage."},{"label":"Forgetting the half-texel inset when sampling a LUT","detail":"Sampling raw rgb without rgb · (1-frac 1N) + frac 12N maps the color range onto the texture's outer edges instead of the corner cells' centers: black, white and exact mid-gray still come out right, but everything in between is pushed away from mid-gray by up to 1/2N (≈0.03 at N = 16), and values within half a cell of either end crush to pure black or white — a small, systematic contrast error."},{"label":"Treating the neutral LUT as decoration, not a test","detail":"A swapped-axis bug (R and B sampled in the wrong place) or a wrong inset formula can still look \"close enough\" with a colored LUT — only the neutral LUT catches it immediately, since it's the one case required to reproduce the original pixel exactly."}],
  },
  "depth-of-field-and-motion-blur": {
    vi: [{"label":"Coi aperture/maxblur của BokehPass là tham số quang học thật","detail":"Chúng là hệ số tuỳ chỉnh cho công thức xấp xỉ tuyến tính, không phải f-number hay tiêu cự — đẩy aperture lên rất cao để \"DOF mạnh hơn\" mà không hiểu nó chỉ là hệ số nhân cho kết quả nhảy cảm, khó đoán hơn hẳn đổi focus (đơn vị world rõ ràng)."},{"label":"Tưởng blend frame trước = motion blur","detail":"Lỗi khái niệm, không phải lỗi code: blend cho ghosting (ảnh rời rạc chồng lớp), không phải vệt mờ liên tục — muốn đúng phải tính vận tốc màn hình rồi gather dọc vector đó."},{"label":"Dùng camera-only motion blur rồi thắc mắc vì sao vật tự chuyển động không bị mờ","detail":"Kỹ thuật này chỉ suy vận tốc từ depth + delta ma trận camera, giả định hình học đứng yên trong world space — một nhân vật chạy giữa cảnh tĩnh không có vệt mờ nào từ chính việc chạy — khi camera di chuyển, nó chỉ mờ theo đúng cách một vật đứng yên bị mờ — vì world position \"frame trước\" mà pass tái tạo lại chính là depth hiện tại, không phải vị trí thật của vật một frame trước."}],
    en: [{"label":"Treating BokehPass's aperture/maxblur as real optical parameters","detail":"They're tuning coefficients for the linear approximation, not an f-number or focal length — cranking aperture up expecting \"stronger DOF\" without realizing it's just a multiplier gives jumpy, hard-to-predict results compared to adjusting focus, which has a clear world-unit meaning."},{"label":"Thinking blending previous frames equals motion blur","detail":"A conceptual bug, not a code bug: blending produces ghosting, not a continuous streak — getting it right requires computing screen-space velocity and gathering along that vector."},{"label":"Using camera-only motion blur, then wondering why self-animating objects show no blur","detail":"This technique only derives velocity from depth plus the camera matrix delta — it assumes geometry sits still in world space; a character running through an otherwise static scene gets no streak from its own running — with a moving camera it blurs only the way a static object would — because the \"previous frame\" world position the pass reconstructs for it reuses the current depth, not the object's actual position one frame earlier."}],
  },
  "effectcomposer-and-passes": {
    vi: [{"label":"Quên OutputPass (hoặc bất kỳ pass tonemapping/color-space nào) ở cuối chuỗi","detail":"Pass cuối cùng ghi thẳng dữ liệu linear ra canvas thay vì sRGB đã tonemap — ảnh tối và gắt bất thường so với những gì R3F từng render mặc định, dù composer \"chạy không lỗi.\""},{"label":"Quên gọi composer.setSize() khi canvas đổi kích thước","detail":"R3F tự resize canvas và camera qua ResizeObserver, nhưng composer có buffer RIÊNG, không tự theo — ảnh vẫn render ở kích thước buffer cũ rồi bị kéo giãn ra canvas mới — mềm nhoè khi canvas to ra, răng cưa khi thu nhỏ, dù tỉ lệ vẫn đúng — một lỗi dễ bị nhầm là \"bug shader.\""},{"label":"Coi readBuffer/writeBuffer là hai texture cố định thay vì hai VAI TRÒ hoán đổi","detail":"Giữ một tham chiếu cứng tới composer.renderTarget1 rồi coi nó luôn là \"ảnh scene mới nhất\" sẽ sai ngay sau lượt swapBuffers() đầu tiên — chỉ readBuffer/writeBuffer (thuộc tính động trên composer) mới phản ánh đúng trạng thái hiện tại của chuỗi."}],
    en: [{"label":"Forgetting OutputPass (or any tonemapping/color-space pass) at the end of the chain","detail":"The final pass writes linear data straight to the canvas instead of tonemapped sRGB — the image looks darker and harsher than what R3F used to render by default, even though the composer \"runs without errors.\""},{"label":"Forgetting to call composer.setSize() when the canvas resizes","detail":"R3F auto-resizes the canvas and camera through a ResizeObserver, but the composer owns its OWN buffers that don't follow along — the image keeps rendering at the old buffer size and gets stretched over the new canvas — soft when the canvas grew, jagged when it shrank, though the proportions stay right — a bug easy to misdiagnose as \"a shader bug.\""},{"label":"Treating readBuffer/writeBuffer as two fixed textures instead of two swapping ROLES","detail":"Holding onto a hard reference to composer.renderTarget1 and assuming it's always \"the latest scene image\" breaks right after the first swapBuffers() call — only readBuffer/writeBuffer (the composer's dynamic properties) reflect the chain's actual current state."}],
  },
  "pass-order-and-fillrate": {
    vi: [{"label":"Đặt bloom sau tone mapping (hoặc sau grade)","detail":"Bloom lúc đó trích sáng từ ảnh đã bị nén về gần [0,1] thay vì từ giá trị HDR thật — quầng sáng mất hẳn sự phân biệt cường độ, trông bẹt và nhạt thay vì rực rỡ theo đúng năng lượng nguồn sáng."},{"label":"Đếm chi phí theo số lệnh addPass() thay vì texel thực sự bị chạm","detail":"Một \"1 pass\" như UnrealBloomPass hay SSAOPass giấu bên trong nhiều draw call ở nhiều độ phân giải khác nhau — coi nó ngang với một ShaderPass đơn giản làm ước lượng ngân sách sai lệch hẳn theo cả hai chiều tuỳ effect."},{"label":"Quên bình phương DPR khi tính ngân sách","detail":"Ước lượng fillrate ở DPR 1 rồi mặc định nó đúng luôn cho thiết bị DPR 2–3 bỏ sót một số nhân 4× đến 9× — đúng phần khiến demo mượt trên laptop dev nhưng giật trên điện thoại test thật."}],
    en: [{"label":"Putting bloom after tone mapping (or after grading)","detail":"Bloom then extracts brightness from an image already squeezed toward [0,1] instead of true HDR values — the glow loses all sense of intensity, reading flat and washed out instead of matching the source's real brightness."},{"label":"Counting cost by the number of addPass() calls instead of texels actually touched","detail":"A \"single pass\" like UnrealBloomPass or SSAOPass hides multiple draw calls at multiple resolutions inside it — treating it as equal to one simple ShaderPass skews the budget estimate in either direction depending on the effect."},{"label":"Forgetting to square DPR when budgeting","detail":"Estimating fillrate at DPR 1 and assuming it holds for a DPR 2–3 device misses a 4x–9x multiplier — exactly the gap that makes a demo feel smooth on a dev laptop and stutter on the actual test phone."}],
  },
  "ssao": {
    vi: [{"label":"Chỉnh kernelRadius bằng đơn vị pixel trong đầu, thay vì view-space unit","detail":"Vì nó khớp thẳng đơn vị thế giới của cảnh, một cảnh scale nhỏ (đơn vị mét thật) cần kernelRadius nhỏ hơn hẳn mặc định 8 — để nguyên mặc định cho cảnh cỡ 1-2 unit làm AO loang phủ gần hết khung hình, trông như sương mù thay vì bóng tiếp xúc cục bộ."},{"label":"Đặt minDistance = 0 để \"cho chắc không mất chi tiết\"","detail":"Đây chính là bias chống acne — bỏ nó khiến mọi bề mặt phẳng tự occlude chính nó, cả cảnh phủ một lớp AO xám xịt giả tạo dù không có góc lõm thật nào."},{"label":"Nhân AO vào diffuse trong shader tự viết vì \"thấy SSAOPass làm vậy\"","detail":"SSAOPass buộc phải nhân vào buffer đã phẳng vì không còn lựa chọn nào khác ở giai đoạn post-process — nhưng tự viết AO ngay trong material shader (có quyền truy cập riêng từng thành phần ánh sáng) mà vẫn nhân vào diffuse là lặp lại đúng lỗi đã nêu ở bài raymarch Track 8: làm tối cả ánh sáng trực tiếp ngay cả khi đường tới nguồn sáng thông thoáng."}],
    en: [{"label":"Thinking of kernelRadius in pixel units instead of view-space units","detail":"Since it matches the scene's world units directly, a small-scale scene (real-world meters) needs a kernelRadius far smaller than the default 8 — leaving the default on a scene sized 1-2 units spreads AO across nearly the whole frame, reading as haze instead of localized contact shadow."},{"label":"Setting minDistance = 0 \"to be safe about losing detail.\"","detail":"That's precisely the anti-acne bias — removing it makes every flat surface occlude itself, coating the scene in a fake gray wash with no real concave corners anywhere."},{"label":"Multiplying AO into diffuse in a hand-written shader \"because SSAOPass does it.\"","detail":"SSAOPass is forced to multiply into the already-flattened buffer with no other option at the post-process stage — but writing AO directly inside a material shader (with separate access to each lighting term) and still multiplying it into diffuse repeats the exact mistake flagged in the Track 8 raymarch lesson: darkening direct light even where its path to the light is open."}],
  },
  "stylistic-effects-grain-vignette": {
    vi: [{"label":"Hash grain chỉ theo uv, quên time","detail":"Kết quả là một khung nhiễu TĨNH, lặp lại y hệt mỗi frame — nhìn như một lớp nylon bẩn dán cố định lên màn hình, dấu hiệu \"amateur shader\" ngay lập tức chứ không phải grain thật."},{"label":"Quên nhân aspect vào khoảng cách tới tâm","detail":"Vignette và CA tối/lệch theo hình ELIP kéo dài theo cạnh dài khung hình thay vì hình tròn — rõ nhất trên canvas ultra-wide hoặc portrait, dễ bị nhầm là bug hơn là hiệu ứng thẩm mỹ."},{"label":"Chỉnh độ mạnh chromatic aberration mà không chốt s đếm loại pixel nào","detail":"Offset chia s cho uResolution.x, nên s đo bằng đúng loại pixel mà uResolution chứa. Demo này truyền size của R3F (pixel CSS), nên s trông như nhau ở mọi DPR; nếu truyền kích thước drawing buffer (pixel render) thì cùng một s chỉ còn một nửa hay một phần ba trên màn DPR 2x–3x, và viền màu chỉnh vừa mắt ở màn 1x gần như biến mất trên điện thoại retina. Giữ uResolution theo pixel CSS, hoặc định nghĩa s theo tỉ lệ màn hình (đơn vị UV thô)."}],
    en: [{"label":"Hashing grain only on uv, forgetting time","detail":"The result is a STATIC noise frame, repeating identically every frame — reading as a dirty nylon sheet permanently stuck to the screen, an instant \"amateur shader\" tell rather than real grain."},{"label":"Forgetting to multiply the distance-to-center by aspect","detail":"Vignette and CA darken/shift in an ELLIPSE stretched along the frame's long edge instead of a circle — most visible on ultra-wide or portrait canvases, easy to mistake for a bug rather than an aesthetic effect."},{"label":"Tuning the chromatic aberration strength without deciding which pixels it counts","detail":"The offset divides s by uResolution.x, so s is measured in whatever pixels uResolution holds. This demo feeds R3F's size (CSS pixels), so its s looks the same at any DPR; feed the drawing-buffer size (render pixels) instead and the same s shrinks to a half or a third on a 2x–3x display, so a fringe tuned on a 1x screen nearly vanishes on a retina phone. Keep uResolution in CSS pixels, or define s as a fraction of the screen (plain UV units)."}],
  },
  "writing-custom-passes": {
    vi: [{"label":"Quên set needsSwap, hoặc set sai giá trị cho hiệu ứng của mình","detail":"Một pass ghi kết quả hợp lệ vào writeBuffer nhưng lỡ để needsSwap = false khiến composer.readBuffer không bao giờ được cập nhật trỏ tới nó — pass sau đọc nhầm buffer cũ, hiệu ứng \"biến mất\" dù code render hoàn toàn đúng."},{"label":"Đọc nhầm writeBuffer thay vì readBuffer","detail":"writeBuffer là đích mà CHÍNH pass này đang render vào — sample nó cùng lúc là feedback loop, nên WebGL bỏ qua lệnh vẽ với INVALID_OPERATION kèm cảnh báo trên console, và pass không cho ra gì — pass sau đọc lại nội dung cũ còn trong writeBuffer."},{"label":"Không cập nhật uniform phụ thuộc độ phân giải trong setSize()","detail":"Bỏ qua bước này khiến hiệu ứng đúng hoàn toàn ở kích thước ban đầu rồi méo/lệch tỉ lệ ngay khi resize cửa sổ — lỗi chỉ lộ ra khi test resize, dễ lọt qua review nếu chỉ test ở một kích thước cố định."}],
    en: [{"label":"Forgetting needsSwap, or setting it wrong for your effect","detail":"A pass that writes a valid result into writeBuffer but leaves needsSwap = false means composer.readBuffer never gets updated to point at it — the next pass reads the stale old buffer instead, and the effect \"disappears\" even though the render code was entirely correct."},{"label":"Reading writeBuffer instead of readBuffer by mistake","detail":"writeBuffer is the target THIS very pass renders into — sampling it at the same time is a feedback loop, so WebGL skips the draw with INVALID_OPERATION and a console warning, and the pass produces nothing — the next pass reads whatever writeBuffer last held, a stale image."},{"label":"Not updating a resolution-dependent uniform in setSize()","detail":"Skip this and the effect is perfectly correct at the initial size, then stretches or skews the instant the window resizes — a bug that only surfaces on resize testing, easy to miss if you only ever test at one fixed size."}],
  },
  "area-lights-and-probes": {
    vi: [{"label":"Quên gọi RectAreaLightUniformsLib.init()","detail":"LUT LTC chưa nạp vào UniformsLib, ánh sáng mất hẳn phần specular — dễ nhầm tưởng do sai intensity/vị trí, trong khi nguyên nhân chỉ là thiếu một dòng gọi trước khi render."},{"label":"Kỳ vọng RectAreaLight tự đổ bóng","detail":"Không shadow map nào được cài cho loại đèn này — castShadow = true vô tác dụng, phải thêm một đèn khác (thường một DirectionalLight/SpotLight mờ) riêng cho việc đổ bóng."},{"label":"Dùng một probe/environment toàn cục cho không gian có nhiều vùng chiếu sáng khác hẳn nhau","detail":"Màu ánh sáng gián tiếp bị \"lai\" sai khắp nơi thay vì đúng riêng từng vùng — vật thể ở góc tối vẫn ánh lên màu vùng sáng cách đó rất xa."}],
    en: [{"label":"Forgetting to call RectAreaLightUniformsLib.init()","detail":"The LTC LUTs never get loaded into UniformsLib, so the light effectively loses its specular contribution — easy to misdiagnose as a wrong intensity or wrong position when the actual cause is one missing setup call before the first render."},{"label":"Expecting RectAreaLight to cast shadows on its own","detail":"No shadow-map path exists for this light type in three.js — setting castShadow = true does nothing, and any contact shadow needs a separate light (usually a dim DirectionalLight/SpotLight) added just for that job."},{"label":"Using one global probe/environment for a space with visually distinct lighting zones","detail":"The indirect light color ends up \"averaged wrong\" everywhere instead of correct per zone — the tell is an object sitting in a dim corner still picking up the color of a bright zone far away."}],
  },
  "brdf-and-microfacets": {
    vi: [{"label":"Quên epsilon ở mẫu số 4(n · v)(n · l)","detail":"Ở góc nhìn cực xiên, (n · v) hoặc (n · l) tiến gần 0, chia không epsilon cho ra NaN/Inf lan ra vùng rìa — \"viền đen kỳ lạ\" hoặc \"viền trắng cháy\" quanh silhouette là dấu hiệu kinh điển."},{"label":"Dùng chung một k cho cả G (direct light) lẫn IBL","detail":"Karis (2013) định nghĩa hai công thức k khác nhau — dùng nhầm direct-light cho IBL (hoặc ngược lại) không lỗi biên dịch, chỉ âm thầm sai độ sáng specular, khó phát hiện nếu không so reference."},{"label":"Quên nhân (1-metalness) vào k_d","detail":"Thiếu hệ số này, quả cầu kim loại hoàn toàn (metalness=1) vẫn có lớp diffuse mờ phủ lên specular — kim loại trông như bị sơn phủ nhựa mờ thay vì phản chiếu thuần khiết, một nguyên nhân phổ biến khiến vật liệu kim loại \"trông giả\" (chủ đề bài \"Vì sao asset trông như nhựa\" cuối track)."}],
    en: [{"label":"Forgetting the epsilon in the 4(n · v)(n · l) denominator","detail":"At extreme grazing angles, (n · v) or (n · l) approach 0, and dividing without an epsilon produces NaN/Inf that bleeds across the surface's edge region — a strange black rim or blown-out white rim around a silhouette is the textbook symptom."},{"label":"Reusing the same k for both direct-light G and IBL","detail":"Karis (2013) defines two different k formulas — one for direct analytic lights, one for environment (IBL) lighting — using the direct-light formula for IBL (or vice versa) causes no compile error, it just silently skews specular brightness, which is hard to catch without comparing against a reference."},{"label":"Forgetting to multiply (1-metalness) into k_d","detail":"Without that factor, a fully metallic sphere (metalness=1) still gets a faint diffuse layer on top of its specular response — the metal ends up looking coated in a thin layer of dull plastic instead of reflecting purely, one of the most common reasons metallic materials \"read as fake\" (the exact subject of this track's later \"Why Your Assets Look Like Plastic\" lesson)."}],
  },
  "fresnel-and-schlick": {
    vi: [{"label":"Coi F_0=0.04 là hằng số dùng được cho mọi vật liệu, kể cả kim loại","detail":"F_0 kim loại nằm trong 0.5–1.0 và có màu; gán 0.04 cho quả cầu lẽ ra là vàng khiến nó phản xạ như nhựa xỉn, mất hẳn ánh kim."},{"label":"Quên clamp/max cos θ trước khi đưa vào pow","detail":"Ở rìa silhouette hoặc pháp tuyến nội suy trên mesh ít vertex, dot(N,V) có thể âm nhẹ; pow() cơ số âm cho kết quả không xác định theo GLSL spec, gây artifact chớp đen/NaN đúng ở viền — dòng clamp trong schlickFresnel tồn tại vì lý do này."},{"label":"Gán F một hằng số cố định (bỏ qua θ) mà vẫn tưởng đó là \"Fresnel\"","detail":"F_0 nhỏ (nước, 0.02) không có nghĩa bề mặt luôn phản xạ yếu — ở góc xiên F vẫn tiến gần 1. Tắt số hạng góc (công tắc \"Schlick vs hằng số\" trong demo) làm mặt nước ở góc quay thấp mất hẳn độ loé gương đặc trưng."}],
    en: [{"label":"Treating F_0=0.04 as universal, including for metals","detail":"Metal F_0 sits in 0.5–1.0 and is colored; assigning 0.04 to a sphere meant to be gold makes it reflect like dull plastic."},{"label":"Forgetting to clamp/max cos θ before pow","detail":"At silhouette edges or with interpolated normals on low-poly meshes, dot(N, V) can go slightly negative; pow() with a negative base is undefined per the GLSL spec, producing flickering black artifacts right at edges — the clamp in schlickFresnel exists for exactly this."},{"label":"Hardcoding F to a constant while still calling it \"Fresnel.\"","detail":"A small F_0 (water's 0.02) doesn't mean weak reflectance everywhere — at grazing angles F still climbs toward 1. Disabling the angle term (the demo's \"Schlick vs constant\" toggle) makes water at a low camera angle lose its characteristic glare."}],
  },
  "hdri-exposure-tonemapping": {
    vi: [{"label":"Nhầm exposure với tăng cường độ đèn/emissive","detail":"Exposure là một số nhân ĐỀU áp lên toàn cảnh trước tone map; tăng intensity của một đèn cụ thể lại thay đổi tỉ lệ tương đối giữa các nguồn sáng (đèn đó sáng hơn HẲN so với các đèn khác) — hai thao tác trông có vẻ \"làm sáng cảnh\" nhưng cho kết quả hoàn toàn khác nhau về contrast và bóng đổ."},{"label":"Vặn brightness hậu kỳ để \"cứu\" một cảnh phơi sáng sai thay vì sửa exposure","detail":"Dữ liệu hậu kỳ đã nằm trong [0,1] và đã bị nén theo đường cong tone map — nhân thêm chỉ đẩy pixel đã gần 1.0 chạm biên và cắt cụt, không tái định vị được gì trên đường cong như exposure thật sự làm."},{"label":"Quên vật liệu toneMapped = false không phản ứng với exposure/tone mapping","detail":"Sau khi chỉnh exposure cho toàn cảnh, các vật liệu emissive dùng cờ này (đèn neon, marker UI...) vẫn giữ nguyên độ sáng cũ — dễ nhầm là bug render, thực chất là quên bước (2) trong quy trình hiệu chỉnh ở trên."}],
    en: [{"label":"Confusing exposure with raising a light's or emissive's intensity","detail":"Exposure is a single multiplier applied EVENLY to the whole scene before tone mapping; raising one light's intensity instead changes the relative balance between sources (that light gets brighter RELATIVE to the others) — both look like \"making the scene brighter\" but produce completely different contrast and shadow behavior."},{"label":"Turning up post-hoc brightness to \"save\" a badly exposed scene instead of fixing exposure","detail":"Post-hoc data already sits in [0,1], already compressed by the tone-mapping curve — multiplying it further just pushes pixels already near 1.0 into the screen's ceiling and clips them, without re-placing anything on the curve the way real exposure does."},{"label":"Forgetting that toneMapped = false materials ignore exposure and tone mapping entirely","detail":"After adjusting exposure for the whole scene, emissive materials using this flag (neon signs, UI markers) keep their old brightness unchanged — easy to mistake for a rendering bug when it's really just step (2) of the calibration workflow above getting skipped."}],
  },
  "ibl-irradiance-and-prefilter": {
    vi: [{"label":"Tưởng envMapIntensity là intensity ánh sáng chung, ảnh hưởng cả light trực tiếp","detail":"Nó chỉ nhân vào phần IBL — một scene có envMapIntensity=3 nhưng DirectionalLight yếu vẫn nhìn phẳng, vì specular highlight của light trực tiếp đi qua một code path hoàn toàn khác, không đọc envMapIntensity."},{"label":"Tưởng Three dựng riêng một irradiance cubemap cho diffuse","detail":"Như đã chỉ ra ở trên, getIBLIrradiance() tái dùng đúng atlas CubeUV đã prefilter, sample ở mip mờ nhất — không có pass convolve cosine riêng nào cả."},{"label":"Quên dispose render target PMREM (và scene/texture nguồn) sau khi build environment","detail":"Mỗi lần rebuild (ví dụ đổi environment qua một control) mà không .dispose() render target cũ trước sẽ rò rỉ nguyên một render target nhiều mip — cộng dồn nhanh nếu người dùng đổi qua đổi lại."}],
    en: [{"label":"Treating envMapIntensity as a general light intensity that also affects direct lights","detail":"It only scales the IBL contribution — a scene with envMapIntensity=3 but a weak DirectionalLight still looks flat, because direct-light specular highlights go through a completely separate code path that never reads envMapIntensity."},{"label":"Assuming Three builds a separate irradiance cubemap for diffuse","detail":"As shown above, getIBLIrradiance() reuses the exact same prefiltered CubeUV atlas at its blurriest mip — there is no separate cosine-convolution pass at all."},{"label":"Forgetting to dispose the PMREM render target (and the source scene/texture) after building an environment","detail":"Every rebuild (e.g. swapping environments through a control) that skips .dispose()ing the old render target first leaks a full multi-mip render target — it adds up fast if a user toggles environments back and forth."}],
  },
  "metalness-roughness-workflow": {
    vi: [{"label":"Đổi/gỡ một map rồi quên material.needsUpdate = true","detail":"Map tồn tại hay không là #ifdef biên dịch sẵn vào shader — Three không tự phát hiện material.metalnessMap = null, chương trình đã compile chạy y nguyên, như \"không đổi gì\" dù code không lỗi cú pháp. Đúng lỗi Track 6 (onBeforeCompile) đã gặp dưới hình hài khác."},{"label":"Sơn metalness = 0.5 đều khắp một bề mặt để \"trông vừa kim loại vừa không\"","detail":"Theo Filament, tổ hợp này không tồn tại trong tự nhiên; kết quả là bề mặt xám mờ, không thuyết phục ở cả hai hướng — giá trị giữa chỉ hợp lệ tại ranh giới mask hoặc dải chuyển tiếp có chủ đích."},{"label":"Gán nhầm color space: quên SRGBColorSpace cho albedo, hoặc lỡ gán nó cho map dữ liệu","detail":"Trường hợp đầu làm ảnh nhạt/cháy sáng giả như trên; trường hợp sau giải mã gamma sai lên giá trị pháp tuyến/độ nhám vốn không phải năng lượng ánh sáng, méo shading theo cách khó truy vì không liên quan trực tiếp tới màu nhìn thấy."}],
    en: [{"label":"Swapping or removing a map and forgetting material.needsUpdate = true","detail":"Whether a map exists is a compile-time #ifdef baked into the shader program — Three doesn't detect material.metalnessMap = null; the already-compiled program runs unchanged, looking like nothing happened despite no syntax error. The same root cause Track 6's onBeforeCompile lesson already ran into."},{"label":"Painting metalness = 0.5 uniformly to make a surface \"look sort of metal, sort of not.\"","detail":"Per Filament, this combination doesn't exist in nature; the result is a flat, unconvincing gray surface — an in-between value is only valid at a mask boundary or deliberate transition, never a \"safe\" way to dodge the metal-or-not decision."},{"label":"Mixing up color space: forgetting SRGBColorSpace on albedo, or applying it to a data map","detail":"The first produces the washed-out result analyzed above; the second incorrectly gamma-decodes values that were never light energy, distorting shading in a way that's hard to trace since it doesn't look directly related to color."}],
  },
  "rendering-equation-intuition": {
    vi: [{"label":"Coi Lambert/Phong là \"xấp xỉ tệ\" thay vì trường hợp riêng hợp lệ trong đúng giả định của nó","detail":"Lambert đúng khi vật liệu khuếch tán hoàn toàn và bạn chấp nhận vài đèn điểm rời rạc; nó chỉ \"sai\" khi bị áp ngoài đúng giả định đó (dùng cho kim loại, hoặc kỳ vọng tự có bóng đổ mềm từ môi trường)."},{"label":"Hiểu nhầm \"PBR\" nghĩa là giải chính xác phương trình","detail":"PBR chỉ có nghĩa xấp xỉ có NGUỒN GỐC VẬT LÝ thật (D/G/F dẫn xuất từ model microfacet, năng lượng bảo toàn) — vẫn là xấp xỉ, khác Lambert/Phong ở *độ chặt chẽ*, không phải ở việc \"không còn là xấp xỉ\"."},{"label":"Quên số hạng cosine hoặc dùng sai dạng của nó","detail":"Cộng thẳng L_i vào tổng mà không nhân max (0, n · ω_i) khiến bề mặt sáng đều bất kể góc chiếu; dùng abs(dot(n, l)) thay vì max(0, dot(n, l)) còn tệ hơn — ánh sáng \"xuyên\" qua mặt sau và vẫn thắp sáng phần quay lưng nguồn sáng."}],
    en: [{"label":"Treating Lambert/Phong as \"bad approximations\" instead of valid special cases under their own assumptions","detail":"Lambert is correct when a material is genuinely fully diffuse and you accept a handful of discrete point lights; it only \"breaks\" outside that assumption — say, on metal, or expecting it to produce soft ambient shadowing on its own."},{"label":"Assuming \"PBR\" means the equation is solved exactly","detail":"PBR only means the approximations are PHYSICALLY GROUNDED (D/G/F derived and measured from a real microfacet model, energy conserved) — still an approximation, differing from Lambert/Phong in *rigor*, not in ceasing to be an approximation."},{"label":"Dropping the cosine term or applying the wrong form of it","detail":"Adding L_i straight in without max (0, n · ω_i) makes a surface equally bright regardless of angle; using abs(dot(n, l)) instead of max(0, dot(n, l)) is worse — it lets light leak through to the back of a surface and lights up the side facing away from the source."}],
  },
  "shadow-techniques-pcf-vsm-csm": {
    vi: [{"label":"Tin rằng PCFSoftShadowMap luôn mềm hơn PCFShadowMap","detail":"Ở bản three.js cài trong dự án này, PCFSoftShadowMap đã bị deprecated và tự động chạy y hệt PCFShadowMap (xác nhận trực tiếp từ WebGLShadowMap.js, kèm cảnh báo console) — chọn nó không sai, nhưng kỳ vọng một kernel rộng hơn riêng biệt là sai với bản three hiện tại."},{"label":"Tăng shadow.radius/blurSamples của VSM để \"sửa\" light bleeding","detail":"Bán kính blur chỉ làm biên bóng mềm hơn, không thu hẹp được phương sai của phân bố depth gây ra chặn Chebyshev lỏng — tăng radius nhiều khi làm quầng xám bleed LAN RỘNG hơn thay vì biến mất; hướng sửa đúng là thu hẹp frustum shadow camera hoặc chấp nhận remap light-bleed đã có sẵn trong shader."},{"label":"Mở rộng frustum shadow camera \"cho chắc\" mà không tăng mapSize tương ứng","detail":"Texel footprint = frustumWidth/mapSize — mở rộng frustum mà giữ nguyên mapSize trực tiếp phóng to từng texel trong thế giới thực, tăng aliasing đúng theo công thức ở phần \"ba căn bệnh\", dù bias/normalBias đã tinh chỉnh đúng."}],
    en: [{"label":"Assuming PCFSoftShadowMap is always softer than PCFShadowMap","detail":"In the three.js version installed in this project, PCFSoftShadowMap has been deprecated and now silently runs identically to PCFShadowMap (confirmed directly in WebGLShadowMap.js, with a console warning) — picking it isn't wrong, but expecting a separate, wider kernel is wrong for the currently installed version."},{"label":"Raising VSM's shadow.radius/blurSamples to \"fix\" light bleeding","detail":"The blur radius only softens the shadow's edge — it doesn't shrink the depth-distribution variance that makes Chebyshev's bound loose in the first place; cranking radius up often makes the gray bleed halo SPREAD FURTHER instead of disappearing. The real fix is tightening the shadow camera's frustum, or accepting the light-bleed remap already baked into the shader."},{"label":"Widening the shadow camera's frustum \"to be safe\" without raising mapSize to match","detail":"Texel footprint = frustumWidth/mapSize — widening the frustum while keeping mapSize fixed directly enlarges each texel's real-world footprint, worsening aliasing by the exact formula from the \"three diseases\" section, even if bias/normalBias are already tuned correctly."}],
  },
  "why-assets-look-like-plastic": {
    vi: [{"label":"Đổi nhiều tham số cùng lúc rồi kết luận \"đỡ nhựa hơn\"","detail":"Không có cách nào tách được thay đổi nào thật sự tạo ra khác biệt — lần sau gặp lỗi tương tự trên cảnh khác, bài học không lặp lại được."},{"label":"Sửa map chi tiết (normal, AO) trước khi sửa ánh sáng","detail":"Một normal map hoàn hảo vẫn vô hình nếu cảnh không có IBL để phản chiếu vào — công sức bỏ vào bước triage sai thứ tự gần như phí hoàn toàn."},{"label":"Tin rằng \"trông đẹp hơn\" nghĩa là \"đúng vật lý hơn\"","detail":"Metalness 0.5 đôi khi trông bắt mắt hơn dưới một góc camera cụ thể, nhưng sai hoàn toàn về vật lý — sẽ lộ rõ dưới góc nhìn khác hoặc ánh sáng khác, trong khi bản sửa đúng ổn định trên mọi điều kiện."}],
    en: [{"label":"Changing several parameters at once and concluding \"looks less plastic now.\"","detail":"There's no way to isolate which change actually mattered — the next time the same failure shows up on a different scene, the lesson doesn't transfer."},{"label":"Fixing detail maps (normal, AO) before fixing lighting","detail":"A flawless normal map stays invisible if the scene has no IBL to reflect into — effort spent on a triage step out of order is nearly wasted."},{"label":"Believing \"looks nicer\" means \"more physically correct.\"","detail":"Metalness 0.5 sometimes looks more eye-catching from one specific camera angle, but is entirely wrong physically — it'll show under a different angle or lighting, while the correct fix stays stable across every condition."}],
  },
  "adaptive-quality-tiers": {
    vi: [{"label":"Cho watchdog đổi tier ngay sau MỘT mẫu frame-time xấu","detail":"Một lần giật hình do garbage collection hay asset đang tải không phản ánh hiệu năng thật của thiết bị — thiếu hysteresis khiến tier nhảy lên xuống liên tục, trải nghiệm còn tệ hơn giữ nguyên một tier hơi thấp suốt."},{"label":"Tin navigator.deviceMemory/chuỗi GPU debug là tuyệt đối, quên rằng chúng có thể vắng mặt hoặc bị làm mờ","detail":"Code phụ thuộc cứng vào các API này mà không có fallback (ví dụ mặc định về medium khi API trả undefined) sẽ crash hoặc chọn sai tier trên chính những trình duyệt tôn trọng privacy nhất."},{"label":"Giữ mọi thứ ở tier cao rồi chỉ ẩn bằng visible={false} thay vì thật sự KHÔNG dựng nó","detail":"Mesh ẩn không tốn draw call — projectObject của renderer return ngay khi visible === false, bỏ cả subtree (đúng như bài culling đã dạy) — nhưng toàn bộ geometry/texture của nó vẫn chiếm VRAM, và cây React vẫn trả chi phí reconcile — tier thấp phải nghĩa là component đó không hề tồn tại trong cây React, không phải \"có nhưng vô hình\"."}],
    en: [{"label":"Letting the watchdog switch tiers after a SINGLE bad frame-time sample","detail":"One stutter from garbage collection or an asset still loading doesn't reflect the device's real performance — without hysteresis the tier bounces up and down constantly, which is a worse experience than just staying on a slightly-too-low tier the whole time."},{"label":"Trusting navigator.deviceMemory/the GPU debug string as absolute, forgetting they can be missing or blurred","detail":"Code that hard-depends on these APIs with no fallback (say, defaulting to medium when the API returns undefined) will crash or pick the wrong tier on exactly the browsers that respect user privacy the most."},{"label":"Keeping everything at the high tier and just hiding it with visible={false} instead of not building it at all","detail":"A hidden mesh costs no draw call — the renderer's projectObject returns as soon as visible === false, skipping the whole subtree (exactly as the culling lesson taught) — but all of its geometry/textures still occupy VRAM, and the React tree still pays reconciliation — a low tier has to mean that component doesn't exist in the React tree at all, not \"exists but invisible.\""}],
  },
  "asset-pipeline-draco-ktx2": {
    vi: [{"label":"Gọi setKTX2Loader/setDRACOLoader sau khi đã gọi load()","detail":"Cả ba hàm chỉ gắn tham chiếu loader phụ vào instance — GLTFLoader tra cứu chúng lúc parse extension, nên đăng ký muộn khiến GLTFLoader ném lỗi rõ ràng (\"setKTX2Loader must be called before loading KTX2 textures\"), lỗi thường gặp nhất là KTX2Loader: Missing initialization with .detectSupport() (nguồn: thông báo lỗi thật trong KTX2Loader.js) vì quên gọi detectSupport(renderer) trước load()."},{"label":"Dùng ETC1S cho mọi loại texture, kể cả normal map","detail":"ETC1S nén mạnh nhưng mất chi tiết cao tần — chấp nhận được cho base color, nhưng làm normal map/roughness map nhiễu hạt rõ rệt; UASTC giữ chi tiết tốt hơn với tỉ lệ nén thấp hơn, đúng lựa chọn cho các map dữ liệu."},{"label":"Nén một model nhỏ theo phản xạ mà không đo trước","detail":"Chi phí tải decoder WASM lần đầu (vài trăm KB, cộng thời gian khởi tạo) có thể vượt hẳn dung lượng tiết kiệm được trên một mesh vài nghìn vertex — luôn đo network time vs decode time trước khi thêm bước nén vào pipeline."}],
    en: [{"label":"Calling setKTX2Loader/setDRACOLoader after load() has already run","detail":"All three methods just attach a reference to the auxiliary loader on the instance — GLTFLoader looks them up while parsing the matching extension, so registering late makes GLTFLoader throw an explicit error (\"setKTX2Loader must be called before loading KTX2 textures\"); the other common symptom is KTX2Loader: Missing initialization with .detectSupport() (source: the actual error message in KTX2Loader.js) from forgetting to call detectSupport(renderer) before load()."},{"label":"Using ETC1S for every texture type, including normal maps","detail":"ETC1S compresses aggressively but loses high-frequency detail — fine for base color, but visibly grainy on normal/roughness maps; UASTC preserves detail better at a lower compression ratio, the right choice for data maps."},{"label":"Compressing a small model by reflex without measuring first","detail":"The one-time cost of fetching the WASM decoder (a few hundred KB, plus init time) can easily outweigh the bytes saved on a mesh with a few thousand vertices — always measure network time vs. decode time before adding a compression step to the pipeline."}],
  },
  "culling-and-lod": {
    vi: [{"label":"Tưởng object bị vertex-shader displace vẫn được cull đúng","detail":"boundingSphere tính từ vị trí GỐC trên CPU, không biết vertex shader di chuyển đỉnh đi đâu — object biến mất sớm dù mắt vẫn thấy nó. Mở rộng bounding sphere thủ công hoặc tắt frustumCulled cho riêng mesh đó."},{"label":"Đặt distance của addLevel giống nhau cho mọi object bất kể kích thước thật","detail":"Object nhỏ và object lớn ở cùng khoảng cách chiếm diện tích màn hình khác hẳn nhau — ngưỡng nên tính theo screen-coverage (s_px ở trên), không phải một con số mét cố định copy giữa các object khác kích thước."},{"label":"Đặt group.visible = false rồi tưởng con của nó vẫn được test frustum bình thường","detail":"Ngược lại: visible = false chặn toàn bộ subtree khỏi cả traversal lẫn test — hữu ích cho zone culling có chủ đích, nhưng dễ gây bug nếu tưởng nhầm nó chỉ ẩn hình chứ không ảnh hưởng logic render bên dưới."}],
    en: [{"label":"Assuming a vertex-shader-displaced object still gets culled correctly","detail":"boundingSphere is computed from the ORIGINAL positions on the CPU and knows nothing about where the vertex shader moves vertices — the object disappears too early even though the eye still sees it. Manually expand the bounding sphere or disable frustumCulled for that one mesh."},{"label":"Setting the same addLevel distance for every object regardless of its real size","detail":"A small object and a large one at the same distance cover very different amounts of screen space — thresholds should come from screen coverage (s_px above), not one fixed meter value copied across differently sized objects."},{"label":"Setting group.visible = false and assuming its children still get tested by the frustum as normal","detail":"The opposite is true: visible = false blocks the whole subtree from both traversal and testing — useful for deliberate zone culling, but an easy source of bugs if mistaken for something that only hides visuals without touching render logic underneath."}],
  },
  "dispose-and-leak-hunting": {
    vi: [{"label":"Dispose material nhưng quên từng map slot gắn trên nó","detail":"material.dispose() không cascade xuống map/normalMap/roughnessMap/... — mỗi texture slot là một object riêng, cần texture.dispose() độc lập, kể cả khi material \"trông như\" đã được dọn."},{"label":"Tưởng renderer.dispose() cũng phá context/canvas như loseContext()","detail":"Nó chỉ xoá cache nội bộ (WebGLProperties, program cache) và gỡ listener context-lost — context WebGL vẫn sống. Gọi nó trong cleanup của một component con, trong khi <Canvas>/DemoCanvas cha đã tự quản lý vòng đời renderer, là dư thừa và có thể phá lịch dispose của chính R3F."},{"label":"Kết luận \"không leak\" sau một lần thử","detail":"renderer.info.memory chỉ lộ leak khi so sánh qua nhiều chu kỳ mount/unmount — một lần mount/unmount duy nhất gần như luôn \"trông ổn\" kể cả khi mỗi chu kỳ đang âm thầm cộng dồn vài đối tượng."}],
    en: [{"label":"Disposing a material but forgetting each map slot attached to it","detail":"material.dispose() doesn't cascade to map/normalMap/roughnessMap/... — each texture slot is its own object and needs its own texture.dispose(), even when the material \"looks\" cleaned up."},{"label":"Assuming renderer.dispose() destroys the context/canvas like loseContext() does","detail":"It only clears internal caches (WebGLProperties, program cache) and removes the context-lost listeners — the WebGL context is still alive. Calling it in a child component's cleanup, when the parent <Canvas>/DemoCanvas already owns and manages the renderer's lifecycle, is redundant and can interfere with R3F's own dispose schedule."},{"label":"Concluding \"no leak\" after a single try","detail":"renderer.info.memory only reveals a leak when compared across multiple mount/unmount cycles — a single mount/unmount almost always \"looks fine\" even when every cycle is silently accumulating a few objects."}],
  },
  "draw-calls-batching-instancing": {
    vi: [{"label":"Dùng chung material rồi kỳ vọng draw call giảm","detail":"Material dùng chung chỉ giảm số lần đổi program — draw call vẫn bằng đúng số mesh, vì mỗi mesh vẫn là một node transform riêng cần một lệnh vẽ riêng."},{"label":"Gộp tĩnh (mergeGeometries) những object cần di chuyển hoặc ẩn/hiện độc lập","detail":"Transform đã bake cứng vào geometry ngay lúc gộp — muốn di chuyển \"một\" object trong khối gộp sau đó là bất khả thi trừ khi gộp lại từ đầu mỗi frame, tự triệt tiêu lợi ích ban đầu; cần chuyển động độc lập thì dùng InstancedMesh ngay từ đầu, không dùng merge."},{"label":"Coi render.calls luôn bằng số mesh trong scene","detail":"Shadow-casting light nhân số pass, khiến con số thực tế cao hơn kỳ vọng — dễ kết luận nhầm \"instancing không có tác dụng\" khi thực ra main pass đã giảm đúng như mong đợi, phần dư ra là các pass shadow không liên quan tới kỹ thuật vừa áp dụng."}],
    en: [{"label":"Sharing a material and expecting draw calls to drop","detail":"A shared material only cuts program switches — draw calls stay exactly equal to mesh count, since each mesh remains its own transform node needing its own draw command."},{"label":"Static-merging (mergeGeometries) objects that need to move or show/hide independently","detail":"Transforms are baked hard into the geometry at merge time — moving \"one\" object inside the merged blob afterward is impossible short of re-merging from scratch every frame, which erases the original benefit; use InstancedMesh from the start whenever independent motion is needed."},{"label":"Assuming render.calls always equals scene mesh count","detail":"Shadow-casting lights multiply the number of passes, pushing the real number higher than expected — easy to wrongly conclude \"instancing didn't work\" when the main pass actually dropped exactly as expected and the leftover calls are unrelated shadow passes."}],
  },
  "mobile-tile-gpus-and-overdraw": {
    vi: [{"label":"Coi discard/alphaTest ngang hàng với early-Z thật","detail":"GPU chỉ biết một fragment \"chết\" SAU khi shader đã chạy tới lệnh discard — hidden-surface removal không thể loại nó trước khi tô màu như opaque thật, nên discard tiết kiệm băng thông ghi/blend nhưng không tiết kiệm chi phí chạy shader."},{"label":"Tin rằng Three.js luôn vẽ opaque theo đúng thứ tự front-to-back tuyệt đối","detail":"painterSortStable ưu tiên gộp theo material.id TRƯỚC, z chỉ là tiêu chí phụ — một cảnh có hàng trăm mesh dùng chung material nhưng nằm ở độ sâu rất khác nhau không được đảm bảo thứ tự front-to-back, phải tự set renderOrder nếu cần chắc chắn."},{"label":"Gọi readPixels/đọc render target ngay giữa lúc đang vẽ vào nó rồi chỉ test trên desktop","detail":"Desktop devtools không thấy gì bất thường vì immediate-mode không có khái niệm \"tile flush\" — nhưng trên mobile, thao tác này buộc GPU resolve tile sớm, gây GPU stall lớn mà chỉ profiler mobile thật (hoặc throttle CPU/GPU trong Chrome DevTools) mới lộ ra."}],
    en: [{"label":"Treating discard/alphaTest as equivalent to real early-Z","detail":"The GPU only learns a fragment is \"dead\" AFTER the shader has already run to the discard instruction — hidden-surface removal can't reject it ahead of shading the way it does for true opaque geometry, so discard saves write/blend bandwidth but not shader execution cost."},{"label":"Assuming Three.js always draws opaque objects in strict front-to-back order","detail":"painterSortStable groups by material.id FIRST, with z only as a tiebreaker — a scene with hundreds of meshes sharing one material but sitting at very different depths gets no guaranteed front-to-back order; set renderOrder yourself when it actually matters."},{"label":"Calling readPixels/reading a render target mid-frame and testing only on desktop","detail":"Desktop devtools show nothing unusual because immediate-mode has no concept of a \"tile flush\" — but on mobile this forces an early tile resolve and a real GPU stall that only a genuine mobile profiler (or CPU/GPU throttling in Chrome DevTools) will reveal."}],
  },
  "nextjs-ssr-hydration-canvas": {
    vi: [{"label":"Gọi next/dynamic(..., { ssr: false }) bên trong một Server Component","detail":"Next 16 báo lỗi thẳng, không chạy — ssr: false chỉ hợp lệ trong file \"use client\"; muốn tắt SSR cho canvas, tạo một Client Component wrapper rồi dynamic từ bên trong nó."},{"label":"Đọc window.innerWidth/devicePixelRatio ở module scope","detail":"thay vì trong effect hoặc callback — chạy được trên client (vô tình) nhưng sập ngay trên server vì window không tồn tại ở đó, dù bạn chỉ test bằng next dev trên máy có thể không lộ ra ngay nếu route đó chưa từng được server-render."},{"label":"Không giữ chỗ layout cho canvas sắp mount","detail":"Thiếu aspect-ratio/kích thước cố định khiến nội dung bên dưới nhảy vị trí đúng lúc <Canvas> xuất hiện — về mặt UX tệ ngang một quảng cáo pop-in giữa trang."}],
    en: [{"label":"Calling next/dynamic(..., { ssr: false }) inside a Server Component","detail":"Next 16 errors outright and refuses to build — ssr: false is only valid inside a \"use client\" file; to disable SSR for a canvas, create a Client Component wrapper and call dynamic from inside it."},{"label":"Reading window.innerWidth/devicePixelRatio at module scope","detail":"instead of inside an effect or callback — it works by accident on the client but crashes outright on the server, since window doesn't exist there, and testing only with next dev on a route that never got server-rendered may not surface it right away."},{"label":"Not reserving layout space for a canvas that's about to mount","detail":"Missing a fixed aspect-ratio/size makes content below jump the instant <Canvas> appears — a UX failure on par with a pop-in ad shoving the page around."}],
  },
  "profiling-webgl-tools": {
    vi: [{"label":"Tin vào FPS trung bình mà không nhìn phương sai","detail":"Một cảnh 59fps trung bình vẫn có thể chứa cú đứng hình 300ms làm người dùng khó chịu — trung bình là thống kê tổng hợp, che mất đúng frame gây khó chịu; phải nhìn chuỗi frame-time theo thời gian, không phải một con số tổng kết."},{"label":"Đọc renderer.info.render.calls mà quên nó tự reset mỗi frame","detail":"Đọc ở thời điểm sai (giữa hai lần render, hoặc cộng dồn qua nhiều frame tưởng là \"tổng\") ra giá trị vô nghĩa — phải đọc lại đúng ngay sau MỖI lần render(), không cache hay trung bình hoá thủ công."},{"label":"Mặc định \"chậm vì đây là 3D nên chắc do GPU\"","detail":"Phần lớn cảnh WebGL chậm vì lý do CPU — hàng nghìn draw call, hoặc JS tính lại thứ không cần thiết mỗi frame — nhảy thẳng vào tối ưu fragment shader trước khi mở flame chart kiểm tra track Main là lãng phí thời gian ở sai tầng."}],
    en: [{"label":"Trusting an average FPS number without looking at its variance","detail":"A scene averaging 59fps can still contain a single 300ms stall the user actually noticed — an average is a summary statistic that erases exactly the frame that annoyed someone; look at the frame-time sequence over time, not one rolled-up number."},{"label":"Reading renderer.info.render.calls without accounting for its per-frame reset","detail":"Sampling this value at the wrong moment (between two renders, or accumulating it across frames thinking it's a \"total\") produces a meaningless number — it must be re-read right after each render(), never cached or manually averaged."},{"label":"Defaulting to \"it's slow because it's 3D, so it must be the GPU.\"","detail":"Most slow WebGL scenes are slow for CPU reasons — thousands of draw calls, or JS recomputing something every frame it doesn't need to — jumping straight to fragment-shader optimization before ever opening the flame chart wastes time solving the wrong layer."}],
  },
  "shader-compilation-stalls": {
    vi: [{"label":"Gọi renderer.compile() ngay lúc người dùng tương tác","detail":"(ví dụ trong callback thêm object) thay vì trước khi hiện scene — vẫn đúng một chi phí compile đồng bộ, chỉ đổi chỗ giật hình từ \"lúc thêm object\" sang \"lúc gọi compile\", không hề biến mất."},{"label":"Toggle material.map giữa null và một texture để bật/tắt hiệu ứng","detail":"Mỗi lần đổi qua lại đổi define USE_MAP, buộc Three compile lại chương trình mỗi lần bấm, dù trông như chỉ đổi một thuộc tính runtime."},{"label":"Tin rằng compileAsync() luôn không chặn","detail":"Nếu trình duyệt/driver không hỗ trợ KHR_parallel_shader_compile, nó lặng lẽ quay về hành vi đồng bộ của compile(), không có cảnh báo nào báo hiệu điều đó."}],
    en: [{"label":"Calling renderer.compile() right at the moment of user interaction","detail":"(say, inside an \"add object\" callback) instead of before the scene is shown — it's still the exact same synchronous compile cost, just relocated from \"when the object is added\" to \"when compile() is called,\" never erased."},{"label":"Toggling material.map between null and a texture to switch an effect on/off","detail":"Every switch flips the USE_MAP define, forcing Three to recompile the program on every click, even though it looks like a plain runtime property change."},{"label":"Assuming compileAsync() is always non-blocking","detail":"If the browser or driver doesn't support KHR_parallel_shader_compile, it silently falls back to compile()'s synchronous behavior, with no warning that it happened."}],
  },
  "texture-memory-budget": {
    vi: [{"label":"Quên nhân b theo format hoặc quên nhân k=4/3 khi bật mipmap","detail":"Đổi từ RGBA8 sang half-float mà không nhân đôi b, hoặc bật mipmap mà không nhân thêm 4/3, khiến ước tính ngân sách sai lệch hàng chục phần trăm — đủ để một scene \"vừa đủ\" thực ra đã vượt ngân sách từ lâu."},{"label":"Coi renderer.info.memory.textures là \"MB đang dùng\"","detail":"Đó là số lượng object, không phải byte — một texture 512 × 512 và một texture 4096 × 4096 đều cộng đúng 1 vào con số này, nên dựa vào nó để quyết định ngân sách luôn cho kết quả sai."},{"label":"Nghĩ PNG/JPEG \"đã nén rồi nên an toàn\"","detail":"texImage2D giải nén về RGBA thô trước khi upload — một ảnh JPG nhẹ vẫn tốn đúng dung lượng RGBA8 đầy đủ trên GPU, không tiết kiệm gì so với ảnh chưa nén; chỉ định dạng nén GPU thật sự (S3TC/ETC2/ASTC, qua KTX2) mới giữ được mức nén đó trong VRAM."}],
    en: [{"label":"Forgetting to multiply by b for the format, or by k=4/3 when mipmaps are on","detail":"Switching from RGBA8 to half-float without doubling b, or enabling mipmaps without the extra 4/3, throws a budget estimate off by tens of percent — enough that a scene that \"just fits\" was actually over budget all along."},{"label":"Treating renderer.info.memory.textures as \"MB in use.\"","detail":"It's an object count, not bytes — a 512 × 512 texture and a 4096 × 4096 texture both add exactly 1 to it, so basing a budget decision on it always gives the wrong answer."},{"label":"Assuming PNG/JPEG is \"already compressed, so it's safe.\"","detail":"texImage2D decodes back to raw RGBA before uploading — a lightweight JPG still costs the full RGBA8 footprint on the GPU, saving nothing over an uncompressed image; only real GPU-native compression (S3TC/ETC2/ASTC, via KTX2) keeps that compression inside VRAM."}],
  },
};

